package referenz;


import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int count = 0;
        for (int i = 0; i < grid.length - 2; i++) {
            for (int j = 0; j < grid[0].length - 2; j++) {
                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagicSquare(int[][] grid, int row, int col) {
        Set<Integer> numbers = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (!numbers.add(grid[row + i][col + j])) {
                    return false;
                }
            }
        }

        // Calculate the expected sum
        int expectedSum = 15;

        // Check if all rows have the same sum
        for (int i = 0; i < 3; i++) {
            int sumRow = 0;
            for (int j = 0; j < 3; j++) {
                sumRow += grid[row + i][col + j];
            }
            if (sumRow != expectedSum) {
                return false;
            }
        }

        // Check if all columns have the same sum
        for (int i = 0; i < 3; i++) {
            int sumCol = 0;
            for (int j = 0; j < 3; j++) {
                sumCol += grid[row + j][col + i];
            }
            if (sumCol != expectedSum) {
                return false;
            }
        }

        // Check if diagonals have the same sum
        int sumDiag1 = 0, sumDiag2 = 0;
        for (int i = 0; i < 3; i++) {
            sumDiag1 += grid[row + i][col + i];
            sumDiag2 += grid[row + i][col + 2 - i];
        }
        if (sumDiag1 != expectedSum || sumDiag2 != expectedSum) {
            return false;
        }

        return true;
    }
}

