import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        Map<String, Integer> dir = new HashMap<>();
        dir.put("right", 0);
        dir.put("up", 1);
        dir.put("left", 2);
        dir.put("down", 3);

        double x = 0;
        double y = 0;
        int maxDistance = 0;

        String initialDirection = getInitialDirection(commands[0]);
        dir.put(initialDirection, (commands[0] == -2 ? 1 : -1));

        for (int command : commands) {
            if (command == -2 || command == -1) {
                String currentDir = getDirection(x, y);
                if (!currentDir.isEmpty()) { 
                    int newDir = (dir.get(currentDir) + (command == -2 ? 1 : -1)) % 4;
                    dir.put(currentDir, newDir);
                } else {
                    throw new RuntimeException("Invalid direction");
                }
            } else {
                double newX = x;
                double newY = y;

                if (dir.get(getDirection(x, y)) == 0) { // right
                    newX += command;
                } else if (dir.get(getDirection(x, y)) == 1) { // up
                    newY += command;
                } else if (dir.get(getDirection(x, y)) == 2) { // left
                    newX -= command;
                } else if (dir.get(getDirection(x, y)) == 3) { // down
                    newY -= command;
                }

                for (int[] obstacle : obstacles) {
                    if (newX == obstacle[0] && newY == obstacle[1]) {
                        newX = x;
                        newY = y;
                        break;
                    }
                }

                x = newX;
                y = newY;

                maxDistance = Math.max(maxDistance, (int) (x * x + y * y));
            }
        }

        return maxDistance;
    }

    private String getInitialDirection(int command) {
        if (command == -2) { // turn left
            return "left";
        } else if (command == -1) { // turn right
            return "right";
        } else { // move forward
            return "up"; // default direction is up
        }
    }

    private String getDirection(double x, double y) {
        if (x == 0 && y == 0) { // robot is at origin, direction is unknown
            return "";
        } else if (x > 0 && y > 0) { // right up
            return "right";
        } else if (x < 0 && y > 0) { // left up
            return "left";
        } else if (x > 0 && y < 0) { // right down
            return "down";
        } else if (x < 0 && y < 0) { // left down
            return "up";
        } else if (x == 0 && y > 0) { // up
            return "up";
        } else if (x == 0 && y < 0) { // down
            return "down";
        } else if (x > 0 && y == 0) { // right
            return "right";
        } else if (x < 0 && y == 0) { // left
            return "left";
        }
        throw new RuntimeException("Invalid direction");
    }
}

