import java.util.HashMap;
import java.util.Map;

public class Solution {
    private int n;

    public int largestIsland(int[][] grid) {
        this.n = grid.length;

        Map<Integer, Integer> parent = new HashMap<>();
        Map<Integer, Integer> size = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int root = findRoot(parent, i, j);
                    parent.put(root, root);
                    size.put(root, size.getOrDefault(root, 0) + 1);
                }
            }
        }

        int maxArea = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> roots = new HashSet<>();
                    int area = 1;

                    for (int x = Math.max(0, j - 1); x <= Math.min(n - 1, j + 1); x++) {
                        for (int y = Math.max(0, i - 1); y <= Math.min(n - 1, i + 1); y++) {
                            if (grid[y][x] == 1) {
                                int root = findRoot(parent, y, x);
                                roots.add(root);
                                area += size.getOrDefault(root, 0);
                            }
                        }
                    }

                    maxArea = Math.max(maxArea, area);

                    for (int root : roots) {
                        parent.put(findRoot(parent, i, j), root);
                        size.put(root, size.getOrDefault(root, 0) + size.get(findRoot(parent, i, j)));
                    }
                }
            }
        }

        return maxArea;
    }

    private int findRoot(Map<Integer, Integer> parent, int x, int y) {
        if (!parent.containsKey(x * n + y)) {
            parent.put(x * n + y, x * n + y);
        }

        return parent.get(x * n + y);
    }
}

