import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        Car[] cars = new Car[position.length];

        for (int i = 0; i < position.length; i++) {
            cars[i] = new Car(position[i], speed[i]);
        }

        Arrays.sort(cars, Comparator.comparingInt(Car::getPosition).reversed());

        int fleets = 1;
        double timeToReachDestination = (double) target / cars[0].getSpeed();

        for (int i = 1; i < position.length; i++) {
            // Calculate the time it takes to reach the destination
            double currentTimeToReachDestination = (double) target / cars[i].getSpeed();

            if (currentTimeToReachDestination > timeToReachDestination && cars[i-1].getSpeed() <= cars[i].getSpeed()) {  
                fleets++;
                timeToReachDestination = Math.max(timeToReachDestination, currentTimeToReachDestination);
            }
        }

        return fleets;
    }

    private static class Car {
        private int position;
        private int speed;

        public Car(int position, int speed) {
            this.position = position;
            this.speed = speed;
        }

        public int getPosition() {
            return position;
        }

        public int getSpeed() {
            return speed;
        }
    }
}

