import java.util.Arrays;

public class Solution {
    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int MOD = 1000000007;
        int m = group.length;
        int[][] dp = new int[m + 1][minProfit + 1];

        for (int i = 0; i <= m; i++) {
            Arrays.fill(dp[i], -1);
        }

        return helper(0, n, minProfit, group, profit, dp, MOD);
    }

    private int helper(int idx, int remainingMembers, int currentMinProfit, int[] group, int[] profit, int[][] dp, int MOD) {
        if (idx == group.length || currentMinProfit < 0) {
            return 0;
        }

        if (dp[idx][currentMinProfit] != -1) {
            return dp[idx][currentMinProfit];
        }

        int include = 0;
        if (group[idx] <= remainingMembers) {
            include = helper(idx + 1, remainingMembers - group[idx], Math.min(currentMinProfit + profit[idx], currentMinProfit), group, profit, dp, MOD);
        }

        int exclude = helper(idx + 1, remainingMembers, currentMinProfit, group, profit, dp, MOD);

        if (idx == group.length) {
            if (currentMinProfit >= minProfit) {
                return dp[idx][currentMinProfit] = 1;
            } else {
                return dp[idx][currentMinProfit] = 0;
            }
        }

        return dp[idx][currentMinProfit] = (include + exclude) % MOD;
    }
}

