public class Solution {
    public String maskPII(String s) {
        // Remove all non-alphanumeric characters from the string and convert to lowercase
        StringBuilder sb = new StringBuilder(s.replaceAll("[^a-zA-Z0-9]", "").toLowerCase());

        if (s.contains("@")) {
            // If it's an email address, replace all but the first and last character with asterisks
            StringBuilder name = new StringBuilder(sb.substring(0, 1));
            for (int i = 1; i < sb.length() - 1; i++) {
                name.append("*");
            }
            name.append(sb.charAt(sb.length() - 1));

            // Replace the '@' symbol and domain with asterisks
            int atIndex = s.indexOf('@');
            StringBuilder domain = new StringBuilder(s.substring(atIndex + 1, s.length()));
            for (int i = 0; i < domain.length(); i++) {
                if (i == 0 || i == domain.length() - 1) {
                    name.append(String.valueOf(domain.charAt(i)));
                } else {
                    name.append("*");
                }
            }

            return String.format("%s@%s", name, "xxxxx");
        } else {
            // If it's a phone number, remove all non-digit characters and format the country code
            StringBuilder countryCode = new StringBuilder();
            for (int i = 0; i < sb.length(); i++) {
                if (!Character.isDigit(sb.charAt(i))) {
                    break;
                }
                countryCode.append(sb.charAt(i));
            }

            String localNumber = sb.substring(countryCode.length());
            return String.format("%s-%s-****", countryCode, localNumber.substring(0, 4));
        }
    }
}

