public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int left = 0, right = n - 1;
        int maxDistance = 0;

        while (left < right) {
            if (seats[left] == 1 || seats[right] == 1) {
                // Update maxDistance with the maximum distance found so far
                maxDistance = Math.max(maxDistance, left + (right - left) / 2);
                if (seats[left] == 1) left++;
                else right--;
            } else {
                int currentDistance = 0;
                while (left < right && seats[left] == 0) {
                    currentDistance++;
                    left++;
                }
                maxDistance = Math.max(maxDistance, currentDistance);
                if (seats[right] == 1) right--;
                else {
                    currentDistance = 0;
                    while (left < right && seats[right] == 0) {
                        currentDistance++;
                        right--;
                    }
                    maxDistance = Math.max(maxDistance, currentDistance);
                }
            }
        }

        return maxDistance;
    }
}

