public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0 || n <= k - 1) return 1.0;

        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        for (int i = 1; i < k && i <= n; i++) {
            dp[i] = 1.0 / w;
        }

        double sum = 0.0;
        for (int i = k - 1; i <= n; i++) {
            if (i >= k) {
                dp[i] = sum + (double)(Math.min(n, i + w - 1) - i + 1) / w;
            } else {
                dp[i] = sum;
            }
            sum += dp[i];
        }

        return dp[n];
    }
}

