import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        // Check if the length of the hand array is a multiple of groupSize
        if (hand.length % groupSize != 0) {
            return false;
        }

        // Sort the hand array in ascending order
        Arrays.sort(hand);

        // Create a HashMap to store the frequency of each card value
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : hand) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        // Try to form groups of consecutive cards
        while (!freqMap.isEmpty()) {
            int minCard = freqMap.keySet().iterator().next();
            for (int i = minCard; i < minCard + groupSize && !freqMap.isEmpty(); i++) {
                if (!freqMap.containsKey(i)) {
                    return false;
                }
                int count = freqMap.get(i);
                if (count == 1) {
                    freqMap.remove(i);
                } else {
                    freqMap.put(i, count - 1);
                }
            }
        }

        // If we can form all groups of consecutive cards, return true
        return true;
    }
}

