public class Solution {
    public double soupServings(int n) {
        if (n >= 4800) return 1;

        int a = (int)Math.ceil((double)(n + 99) / 100);
        int b = (int)Math.ceil((double)n / 100);

        double[][] dp = new double[a + 1][b + 1];

        for (int i = 0; i <= a; i++) {
            for (int j = 0; j <= b; j++) {
                if (i == 0) {
                    dp[i][j] = 1;
                } else {
                    double p = 0;
                    if (Math.max(0, i - 4) >= 0 && Math.max(0, j) >= 0) {
                        p += dp[Math.max(0, i - 4)][Math.max(0, j)];
                    }
                    if (Math.max(0, i - 3) >= 0 && Math.max(0, j - 1) >= 0) {
                        p += dp[Math.max(0, i - 3)][Math.max(0, j - 1)];
                    }
                    if (Math.max(0, i - 2) >= 0 && Math.max(0, j - 2) >= 0) {
                        p += dp[Math.max(0, i - 2)][Math.max(0, j - 2)];
                    }
                    if (Math.max(0, i - 1) >= 0 && Math.max(0, j - 3) >= 0) {
                        p += dp[Math.max(0, i - 1)][Math.max(0, j - 3)];
                    }

                    double probability = 0.25 * p;
                    if (i == j) {
                        probability += 0.5;
                    }
                    dp[i][j] = 1 - probability;
                }
            }
        }

        return dp[a][b];
    }
}

