import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int minimumLengthEncoding(String[] words) {
        // Sort the words in descending order based on their lengths
        Arrays.sort(words, (a, b) -> Integer.compare(b.length(), a.length()));

        Set<String> set = new HashSet<>();
        for (String word : words) {
            if (!word.endsWith("#")) {
                String wordWithoutHash = word;
                while (set.contains(wordWithoutHash)) {
                    int lastIndexOfHash = wordWithoutHash.lastIndexOf('#');
                    if (lastIndexOfHash != -1) {
                        wordWithoutHash = wordWithoutHash.substring(0, lastIndexOfHash);
                    } else {
                        break;
                    }
                }
                set.add(word + "#");
            } else {
                String wordWithoutHash = word;
                while (set.contains(wordWithoutHash)) {
                    int lastIndexOfHash = wordWithoutHash.lastIndexOf('#');
                    if (lastIndexOfHash != -1) {
                        wordWithoutHash = wordWithoutHash.substring(0, lastIndexOfHash);
                    } else {
                        break;
                    }
                }
            }
        }

        int length = 0;
        for (String word : set) {
            length += word.length();
        }

        return length;
    }
}

