// #Medium #Array #Dynamic_Programming #Two_Pointers #Enumeration
// #2022_03_24_Time_2_ms_(94.37%)_Space_51.9_MB_(54.85%)
public class Solution {
    public int longestMountain(int[] arr) {
        int n = arr.length;
        if (n < 3) return 0;

        int res = 0;
        for (int i = 1; i < n - 1; i++) {
            // Check if the current element is a peak
            if (arr[i] > arr[i-1] && arr[i] > arr[i+1]) {
                int increasingLength = 0;
                for (int j = i - 1; j >= 0; j--) {
                    if (j == 0 || (arr[j] < arr[j + 1])) { // Check if current element is greater than previous one
                        increasingLength++;
                    } else {
                        break;
                    }
                }

                int decreasingLength = 0;
                for (int k = i + 1; k < n; k++) {
                    if ((k == n - 1) || (arr[k] > arr[k - 1])) { // Check if current element is greater than previous one
                        decreasingLength++;
                    } else {
                        break;
                    }
                }

                // Calculate the length of the mountain subarray
                int mountainLength = increasingLength + decreasingLength - 1;

                res = Math.max(res, mountainLength);
            }
        }
        return res;
    }
}

