import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        s = s.substring(1, s.length() - 1);
        List<String> res = new ArrayList<>();
        for (int i = 1; i < s.length(); i++) {
            String left = s.substring(0, i), right = s.substring(i);
            if (!isValid(left) || !isValid(right)) continue;
            for (String l : split(left)) {
                for (String r : split(right)) {
                    res.add(l + " " + r);
                }
            }
        }
        return res;
    }

    private boolean isValid(String num) {
        int i = 0, j = num.length() - 1;
        while (i < j && num.charAt(i) == '0') i++;
        if (i >= j) return false;
        if (num.charAt(i) == '.') {
            while (++i < j && num.charAt(i) != '.') return false;
            while (++i <= j && num.charAt(i) == '0') i--;
            return true;
        }
        while (i < j && num.charAt(j) == '0') j--;
        // Check for leading zeros
        if (num.length() > 1 && num.charAt(0) == '0' && num.charAt(1) != '.') {
            return false;
        }
        return true;
    }

    private List<String> split(String s) {
        List<String> res = new ArrayList<>();
        if (s.contains(".")) { // Check if the string contains a decimal point
            int i = 0;
            while (i < s.length()) {
                if (s.charAt(i) == '0' && i != 0) {
                    i++;
                } else {
                    for (int j = i + 1; j <= s.length(); j++) {
                        String t = s.substring(0, j);
                        if (!isValid(t)) continue;
                        res.add(t + "." + s.substring(j));
                    }
                    break;
                }
            }
        } else {
            // If there are no decimal points, add all possible splits
            for (int i = 1; i < s.length(); i++) {
                String t = s.substring(0, i);
                if (!isValid(t)) continue;
