import java.util.*;

public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;

        // Initialize a visited array to keep track of visited cells
        boolean[][] visited = new boolean[m][n];

        // Initialize an array to store the number of bricks that will fall after each erasure
        int[] result = new int[hits.length];

        // Function to perform DFS and mark all connected bricks as visited
        private void dfs(int i, int j) {
            if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0 || visited[i][j]) return;

            visited[i][j] = true;
            dfs(i - 1, j);
            dfs(i + 1, j);
            dfs(i, j - 1);
            dfs(i, j + 1);
        }

        // Function to calculate the number of bricks that will fall after each erasure
        private int countFallingBricks(int i, int j) {
            if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) return 0;

            int count = 1;
            // Check all four adjacent cells for bricks that will fall
            if (visited[i - 1][j]) {
                dfs(i, j);
                count += countFallingBricks(i + 1, j);
                count += countFallingBricks(i, j + 1);
                count += countFallingBricks(i, j - 1);
            }

            return count;
        }

        // Iterate over the grid and mark all connected bricks as visited
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) dfs(i, j);
            }
        }

        // Iterate over the hits array and calculate the number of bricks that will fall after each erasure
        for (int i = 0; i < hits.length; i++) {
            int x = hits[i][0];
            int y = hits[i][1];

            if (grid[x][y] == 0) continue;

            grid[x][y] = 0;

            // Calculate the number of bricks that will fall after this erasure
            result[i] += countFallingBricks(x, y);
        }

        return result;
    }
}

