public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        int[][] result = new int[rows * cols][2];
        int index = 0;
        boolean right = true;
        boolean down = false;
        boolean left = false;
        boolean up = false;

        int stepsRight = 1;
        int stepsDown = 1;
        int stepsLeft = 1;
        int stepsUp = 1;

        for (int i = 0; i < rows * cols; i++) {
            if (right) {
                result[index][0] = y;
                result[index++][1] = x++;
            }
            if (down && index < rows * cols) { 
                result[index][0] = ++y;
                result[index++][1] = x;
            }
            if (left && index < rows * cols) { 
                result[index][0] = y;
                result[index++][1] = --x;
            }
            if (up && index < rows * cols) { 
                result[index][0] = --y;
                result[index++][1] = x;
            }

            // Change direction
            if ((right && x == cols || !right && x == -1) ||
                (down && y == rows || !down && y == -1)) {
                right = !left;
                down = !up;
                left = !right;
                up = !down;

                // Reset steps
                stepsRight = 1;
                stepsDown = 1;
                stepsLeft = 1;
                stepsUp = 1;
            }
        }

        return result;
    }
}

