public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int totalSurfaceArea = 0;

        // Calculate the surface area of each tower and add it to the total surface area.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    int height = grid[i][j];
                    // Add the top and bottom faces of the tower to the total surface area.
                    totalSurfaceArea += 2;
                    // Add the side faces of the tower to the total surface area. 
                    totalSurfaceArea += (height - 1) * 4;

                    int minAdjacentHeight = height;
                    for (int k = Math.max(0, j - 1); k <= Math.min(n - 1, j + 1); k++) {
                        if (k != j && grid[i][k] > 0) {
                            totalSurfaceArea += Math.min(grid[i][k], minAdjacentHeight) * 2;
                            minAdjacentHeight = Math.min(minAdjacentHeight, grid[i][k]);
                        }
                    }

                    for (int k = Math.max(0, i - 1); k <= Math.min(n - 1, i + 1); k++) {
                        if (k != i && grid[k][j] > 0) {
                            totalSurfaceArea += Math.min(grid[k][j], minAdjacentHeight) * 2;
                            minAdjacentHeight = Math.min(minAdjacentHeight, grid[k][j]);
                        }
                    }

                }
            }
        }

        return totalSurfaceArea;
    }
}

