public class Solution {
    int maxDepth = 0;
    TreeNode deepestNode = null;

    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        if (root == null)
            return null;

        int depth = getDepth(root);
        if (depth > maxDepth) {
            maxDepth = depth;
            deepestNode = root;
        }

        TreeNode leftSubtree = subtreeWithAllDeepest(root.left);
        TreeNode rightSubtree = subtreeWithAllDeepest(root.right);

        if ((leftSubtree == null || getDepth(leftSubtree) < maxDepth)
                && (rightSubtree == null || getDepth(rightSubtree) < maxDepth))
            return root;

        if (leftSubtree != null && rightSubtree != null
                && getDepth(leftSubtree) == maxDepth && getDepth(rightSubtree) == maxDepth)
            return root;

        if (getDepth(leftSubtree) > getDepth(rightSubtree))
            return leftSubtree;
        else
            return rightSubtree;
    }

    private int getDepth(TreeNode node) {
        if (node == null)
            return 0;
        return 1 + Math.max(getDepth(node.left), getDepth(node.right));
    }
}

