public class Solution {
    public String pushDominoes(String dominoes) {
        StringBuilder sb = new StringBuilder(dominoes);
        int n = sb.length();

        for (int i = 0; i < n; i++) {
            if (sb.charAt(i) == '.') continue;

            int j = i + 1;
            while (j < n && sb.charAt(j) != '.' && sb.charAt(j) != 'L' && sb.charAt(j) != 'R') {
                break;
            }
            if (sb.charAt(i) == 'L' && sb.charAt(j) == 'R') {
                for (int k = i; k <= j; k++) {
                    sb.setCharAt(k, '.');
                }
                break;
            } else if (sb.charAt(i) == 'R' && sb.charAt(j) == 'L') {
                for (int k = i; k <= j; k++) {
                    sb.setCharAt(k, '.');
                }
                break;
            } else if (sb.charAt(i) == 'L' && sb.charAt(j) == 'L') {
                int count = 1;
                while (j < n - 1 && sb.charAt(j + 1) == 'L') {
                    j++;
                    count++;
                }
                for (int k = i; k <= j - 2; k++) { // Push all dominoes between two 'L's to the left
                    if (sb.charAt(k) != '.') {
                        sb.setCharAt(k, '.');
                    }
                }
                i = j;
            } else if (sb.charAt(i) == 'R' && sb.charAt(j) == 'R') {
                int count = 1;
                while (j < n - 1 && sb.charAt(j + 1) == 'R') {
                    j++;
                    count++;
                }
                for (int k = i; k <= j - 2; k++) { // Push all dominoes between two 'R's to the right
                    if (sb.charAt(k) != '.') {
                        sb.setCharAt(k, '.');
                    }
                }
                i = j;
            } else if (i == j) break;
        }

        return sb.toString();
    }
}

