import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        int curPos = 0;
        int res = 0;
        while (curPos < target) {
            if (curPos < stations.length) {
                // add current position to priority queue
                pq.offer(stations[curPos][0]);

                // add fuel to current position
                startFuel += stations[curPos][1];

                curPos = Math.max(curPos, stations[curPos][0]); // Update curPos here

                res++; // Increment refueling stops count
            } else if (!pq.isEmpty()) {
                int pos = pq.poll();

                startFuel -= pos;

                curPos++;
            } else {
                return -1; // The car cannot reach its destination.
            }
        }

        if (startFuel < target) {
            return -1;
        }

        return res;
    }
}

