import java.util.*;

public class Solution {
    public boolean possibleBipartition(int n, int[][] dislikes) {
        // build graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n + 1; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] dislike : dislikes) {
            graph.get(dislike[0]).add(dislike[1]);
            graph.get(dislike[1]).add(dislike[0]);
        }

        // color the nodes
        int[] colors = new int[n + 1];
        Arrays.fill(colors, -1);

        Set<Integer> visitedNodes = new HashSet<>();

        for (int i = 1; i <= n; i++) {
            if (colors[i] == -1) {
                if (!dfs(graph, colors, i, 0, visitedNodes)) {
                    return false;
                }
            }
        }

        // No need to run on other connected components if one component has failed.
        return true;
    }

    private boolean dfs(List<List<Integer>> graph, int[] colors, int node, int color, Set<Integer> visitedNodes) {
        if (colors[node] != -1 && colors[node] != color) {
            return false;
        }

        if (!visitedNodes.add(node)) {
            // If the node is already visited and its color matches the assigned color, we can skip it to avoid infinite recursion.
            return true;
        }

        colors[node] = color;

        for (int neighbor : graph.get(node)) {
            if (!dfs(graph, colors, neighbor, 1 - color, visitedNodes)) {
                return false;
            }
        }

        return true;
    }
}

