import java.lang.Math;

public class Solution {
    public int consecutiveNumbersSum(int n) {
        long sum = (long)n * (n + 1) / 2;

        // Check if n is a perfect square
        boolean isPerfectSquare = Math.sqrt(n) == Math.floor(Math.sqrt(n));

        int count = 0;
        for (int i = 1; i <= Math.sqrt(sum) + 1; i++) {
            if (sum % i == 0 && sum / i >= i) {
                long temp = sum / i;
                if ((temp + 1) * temp / 2 == n) count++;

                // Check the case when i equals sum / i
                if (i != sum / i) {
                    temp = i;
                    if ((temp + 1) * temp / 2 == n) count++;
                }
            }
        }

        return isPerfectSquare ? 1 : count;
    }
}

