public class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;

        // Calculate the maximum height of each row and column
        int[] maxRow = new int[n];
        int[] maxCol = new int[n];

        for (int i = 0; i < n; i++) {
            int max = Integer.MIN_VALUE;
            for (int j = 0; j < n; j++) {
                max = Math.max(max, grid[i][j]);
            }
            maxRow[i] = max;

            max = Integer.MIN_VALUE;
            for (int j = 0; j < n; j++) {
                max = Math.max(max, grid[j][i]);
            }
            maxCol[i] = max;
        }

        int sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // The maximum increase is the minimum of the row and column maximums minus the current height
                sum += Math.min(maxRow[i], maxCol[j]) - grid[i][j];
            }
        }

        return sum;
    }
}

