        Arrays.sort(jobsWithProfits, Comparator.comparingInt(i -> profit[(Integer)i]).reversed());

        int maxProfit = 0;

        for (int w : worker) {
            int j = Arrays.binarySearch(jobsWithProfits, Integer.valueOf(0), jobsWithProfits.length, i -> difficulty[(Integer)i] <= w);

            if (j < 0) {
                j = -j - 1;
            }

            maxProfit += profit[jobsWithProfits[j]];
        }

        return maxProfit;
    }
