import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public String orderlyQueue(String s, int k) {
        if (k == 1) {
            StringBuilder sb = new StringBuilder(s);
            for (int i = s.length() - 1; i > 0; i--) {
                char c = sb.charAt(i);
                for (int j = i - 1; j >= 0; j--) {
                    if (c < sb.charAt(j)) {
                        break;
                    } else if (c == sb.charAt(j) && j != i - 1) {
                        break;
                    }
                    char temp = sb.charAt(i);
                    sb.setCharAt(i, sb.charAt(j));
                    sb.setCharAt(j, temp);
                    i--;
                }
            }
            return sb.toString();
        } else {
            String[] substrings = new String[k];
            for (int i = 0; i < k; i++) {
                substrings[i] = s.substring(i, Math.min(k, s.length()));
            }

            Arrays.sort(substrings, new Comparator<String>() {
                @Override
                public int compare(String s1, String s2) {
                    if (s1.charAt(0) < s2.charAt(0)) return -1;
                    else if (s1.charAt(0) > s2.charAt(0)) return 1;
                    else {
                        for (int i = 1; i < Math.min(s1.length(), s2.length()); i++) {
                            if (s1.charAt(i) < s2.charAt(i)) return -1;
                            else if (s1.charAt(i) > s2.charAt(i)) return 1;
                        }
                        // If all characters are equal, consider the shorter string first
                        return s1.length() - s2.length();
                    }
                }
            });

            StringBuilder result = new StringBuilder();
            for (String substring : substrings) {
                result.append(substring);
            }
            return result.toString();
        }
    }
}

