import java.util.*;

public class Solution {
    public int kSimilarity(String a, String b) {
        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();

        if (a.equals(b)) return 0;

        queue.offer(a);
        visited.add(a);

        int minSwaps = Integer.MAX_VALUE;

        while (!queue.isEmpty()) {
            String cur = queue.poll();

            for (int i = 0; i < cur.length(); i++) {
                if (cur.charAt(i) != b.charAt(i)) {
                    StringBuilder sb = new StringBuilder(cur);
                    char[] chars = sb.toString().toCharArray();

                    for (int j = i + 1; j < cur.length(); j++) {
                        if (chars[j] == b.charAt(i) && chars[i] == b.charAt(j)) {
                            String next = swap(chars, i, j);

                            if (!visited.contains(next)) {
                                queue.offer(next);
                                visited.add(next);

                                // Update minSwaps only when a new minimum is found
                                int swaps = 0;
                                for (int k = 0; k < cur.length(); k++) {
                                    if (cur.charAt(k) != next.charAt(k)) {
                                        swaps++;
                                    }
                                }

                                minSwaps = Math.min(minSwaps, swaps);
                            }
                        }
                    }
                }
            }
        }

        // Return -1 if no solution is found
        return minSwaps == Integer.MAX_VALUE ? -1 : minSwaps;
    }

    private String swap(char[] chars, int i, int j) {
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;

        return new String(chars);
    }
}

