import java.util.Arrays;

public class Solution {
    public int minSwap(int[] nums1, int[] nums2) {
        int n = nums1.length;
        boolean[][] dp = new boolean[n][n];

        // Initialize base cases
        dp[0][0] = true;
        if (nums1[0] > nums1[1] && nums2[0] > nums2[1]) {
            dp[0][1] = true;
        }

        for (int i = 1; i < n; i++) {
            // If current element is greater than previous one, 
            // then we can swap or not swap
            if (nums1[i] > nums1[i-1] && nums2[i] > nums2[i-1]) {
                dp[i][0] = true;
                dp[i][1] = dp[i-1][1] || dp[i-1][0];
            } 
            // If current element is smaller than previous one, 
            // then we must swap
            else if (nums1[i] < nums1[i-1] && nums2[i] < nums2[i-1]) {
                dp[i][0] = false;
                dp[i][1] = dp[i-1][1];
            } 
            // If current element is equal to previous one, 
            // then we can swap or not swap
            else if (nums1[i] == nums1[i-1] && nums2[i] == nums2[i-1]) {
                dp[i][0] = true;
                dp[i][1] = false;
            } 
            // If current element is smaller than previous one, 
            // then we can swap
            else if (nums1[i] < nums1[i-1] && nums2[i] < nums2[i-1]) {
                dp[i][0] = true;
                dp[i][1] = false;
            }
        }

        int minIndex = 0;
        for (int i = 1; i < dp[n-1].length; i++) {
            if (!dp[n-1][i]) {
                break;
            }
            minIndex = i;
        }
        return minIndex == 0 ? 0 : 1;
    }
}

