public class Solution {
    public String shiftingLetters(String s, int[] shifts) {
        int sum = 0;
        StringBuilder sb = new StringBuilder();

        for (int i = shifts.length - 1; i >= 0; i--) {
            sum += shifts[i];
            char c = s.charAt(i);

            if ((c + sum) > 'z') {
                int diff = (c + sum) - 'z' - 1;
                sb.append((char) ('a' + diff));
