public class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int low = 1;
        int high = Integer.MAX_VALUE;

        while (low < high) {
            int mid = low + (high - low) / 2;
            long time = getTime(piles, mid);
            if (time > h) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return low;
    }

    private long getTime(int[] piles, int k) {
        long time = 0;
        for (int pile : piles) {
            time += (pile - 1) / k + 1;
        }
        return time;
    }
}

