import java.util.*;

public class Solution {
    private String[] strs;
    private int[] parent;
    private int[] rank;

    public Solution(String[] strs) {
        this.strs = strs;
        parent = new int[strs.length];
        rank = new int[strs.length];

        for (int i = 0; i < strs.length; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    private int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY)
            return;

        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
            rank[rootX]++;
        } else {
            parent[rootX] = rootY;
            rank[rootY]++;
        }
    }

    public int numSimilarGroups(String[] strs) {
        this.strs = strs; // assign the passed array to the class field

        for (int i = 0; i < strs.length; i++) {
            for (int j = i + 1; j < strs.length; j++) {
                if (isSimilar(strs[i], strs[j])) {
                    union(i, j);
                }
            }
        }

        int groups = 0;
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == i)
                groups++;
        }

        return groups;
    }

    private boolean isSimilar(String s1, String s2) {
        int diffCount = 0;
        for (int k = 0; k < s1.length(); k++) {
            if (s1.charAt(k) != s2.charAt(k)) {
                diffCount++;
            }
        }

        return diffCount == 2;
    }
}

