import java.util.Arrays;

public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        long[] lastCharIdx = new long[26];
        Arrays.fill(lastCharIdx, -1);

        long ans = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int idx = c - 'A';
            if (lastCharIdx[idx] == -1) {
                lastCharIdx[idx] = i + 1;
            } else {
                long prevLastCharIdx = lastCharIdx[idx];
                ans += (i - prevLastCharIdx) * (n - i);
                lastCharIdx[idx] = i + 1;
            }
        }

        // Simplified calculation
        for (int i = 0; i < n; i++) {
            long[] dp = new long[26];
            Arrays.fill(dp, -1);
            int count = 0;
            for (int j = i; j < n; j++) {
                char c = s.charAt(j);
                int idx = c - 'A';
                if (dp[idx] == -1) {
                    dp[idx] = j + 1;
                    count++;
                } else {
                    long prevLastCharIdx = dp[idx];
                    ans += (j - prevLastCharIdx) * (n - j);
                    dp[idx] = j + 1;
                }
            }

            // Add the sum of unique characters in all substrings
            for (int k = 0; k < 26; k++) {
                if (dp[k] != -1) {
                    long nMinusLastCharIdx = n - dp[k];
                    ans += (nMinusLastCharIdx * (nMinusLastCharIdx + 1)) / 2;
                }
            }

            // Update lastCharIdx array for the next iteration
            System.arraycopy(dp, 0, lastCharIdx, 0, 26);
        }

        return (int)(ans % (long)(Math.pow(10, 9) + 7));
    }
}

