public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        // Toggle first column to 1 if it's 0
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                for (int j = 0; j < n; j++) {
                    grid[i][j] ^= 1;
                }
            }
        }

        // Count the number of 1s in the first column
        int onesInFirstCol = 0;
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 1) {
                onesInFirstCol++;
            }
        }

        // Toggle rows to make first bit of each row as 1
        if (onesInFirstCol < m / 2) {
            for (int i = 1; i < m; i++) {
                if (grid[i][0] == 0 && grid[i - 1][0] == 0) {
                    for (int j = 0; j < n; j++) {
                        grid[i][j] ^= 1;
                    }
                }
            }
        }

        // Calculate the score
        int score = 0;
        for (int i = 0; i < m; i++) {
            int num = 0;
            for (int j = 0; j < n; j++) {
                num |= grid[i][j] << (n - 1 - j);
            }
            score += num;
        }

        return score;
    }
}

