// #Hard #Dynamic_Programming #Depth_First_Search #Tree #Graph
// #2022_03_24_Time_52_ms_(91.09%)_Space_96.7_MB_(75.86%)
public class Solution {
    int[] ans;
    List<List<Integer>> adj;
    int[] numNodes;
    int[] sumDistances;

    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        ans = new int[n];
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        numNodes = new int[n];
        sumDistances = new int[n];

        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        dfs(0, -1);

        dfs2(0, -1);
        return ans;
    }

    private int dfs(int node, int parent) {
        numNodes[node] = 1;
        sumDistances[node] = 0;

        for (int child : adj.get(node)) {
            if (child != parent) {
                numNodes[node] += dfs(child, node);
                sumDistances[node] += sumDistances[child] + numNodes[child];
            }
        }

        return numNodes[node];
    }

    private int dfs2(int node, int parent) {
        for (int child : adj.get(node)) {
            if (child != parent) {
                dfs2(child, node);
            }
        }

        ans[node] = sumDistances[node];

        for (int child : adj.get(node)) {
            if (child != parent) {
                ans[node] -= numNodes[child];
            }
        }

        return 0;
    }
}

