import java.util.*;

public class Solution {
    public int rectangleArea(int[][] rectangles) {
        Set<String> set = new HashSet<>();
        long ans = 0;

        // Sort the rectangles based on their start x-coordinate
        Arrays.sort(rectangles, (a, b) -> a[0] - b[0]);

        for (int[] rect : rectangles) {
            int x1 = rect[0], y1 = rect[1];
            int x2 = rect[2], y2 = rect[3];

            // Add the rectangle to the set
            String key = x1 + "," + y1;
            if (!set.contains(key)) {
                ans += (long) (x2 - x1) * (y2 - y1);
                set.add(key);

                // Remove points that are outside the current rectangle
                for (String point : set) {
                    String[] parts = point.split(",");
                    int px = Integer.parseInt(parts[0]);
                    int py = Integer.parseInt(parts[1]);

                    if ((px < x1 || px > x2) && (py < y1 || py > y2)) {
                        set.remove(point);
                    }
                }

                // Remove rectangles that are completely inside the current rectangle
                for (int[] otherRect : rectangles) {
                    int ox1 = otherRect[0], oy1 = otherRect[1];
                    int ox2 = otherRect[2], oy2 = otherRect[3];

                    if ((ox1 >= x1 && ox1 <= x2 && oy1 >= y1 && oy1 <= y2) ||
                        (ox2 >= x1 && ox2 <= x2 && oy2 >= y1 && oy2 <= y2)) {
                        set.remove(otherRect[0] + "," + otherRect[1]);
                    }
                }
            }

        }

        return (int) (ans % 1000000007);
    }
}

