            if (s.charAt(i) != goal.charAt(i)) {
                diffCount++;

                if (diffCount > 2) return false;

                diffIndices.add(i);
            }
        }

        if (diffCount == 0) {
            // If there are no differences, we can still swap two characters
            boolean[] charCounts = new boolean[26];

            for (int i = 0; i < s.length(); i++) {
                charCounts[s.charAt(i) - 'a'] = true;
            }

            for (boolean count : charCounts) {
                if (!count) return false;
            }
        } else if (diffCount == 2) {
            // If there are two differences, we need to check if swapping the characters at these indices results in goal
            int[] diff = new int[2];

            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) != goal.charAt(i)) {
                    diff[i - diffIndices.get(0)] = i;
                }
            }

            return s.charAt(diff[0]) == goal.charAt(diff[0]) && s.charAt(diff[1]) == goal.charAt(diff[1]);
        } else {
            // If there are more than two differences, we cannot swap characters to get goal
            return false;
        }

        // Try swapping the two different characters
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                char temp = s.charAt(i);
                String newS = s.substring(0, i) + goal.charAt(i) + s.substring(i + 1);

                // Check if the resulting string matches the goal string
                if (newS.equals(goal)) {
                    return true;
                }
            }
        }

        return false;
    }
}

