import java.util.*;

public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        long[] prefixSum = new long[shifts.length + 1];
        for (int i = 0; i < shifts.length; i++) {
            if (shifts[i][2] == 1) {
                prefixSum[i] = shifts[i][1] - shifts[i][0] + 1;
            } else {
                // Add the absolute value of the shift to the prefix sum
                prefixSum[i] = Math.abs(shifts[i][1] - shifts[i][0] + 1) * (shifts[i][2] == 0 ? -1 : 1);
            }
            prefixSum[i + 1] += prefixSum[i];
        }

        StringBuilder sb = new StringBuilder();
        int shift = 0;
        for (int i = 0; i < s.length(); i++) {
            for (int j = 0; j < shifts.length; j++) {
                if (shifts[j][0] <= i && i <= shifts[j][1]) {
                    // Apply the current shift operation to the characters in the string
                    if (shifts[j][2] == 1) {
                        shift += prefixSum[j];
                    } else {
                        shift -= prefixSum[j];
                    }
                }
            }

            char c = s.charAt(i);
            if (c >= 'a' && c <= 'z') {
                // Apply the shift to the character
                sb.append((char) ('a' + (c - 'a' + shift) % 26));
            } else {
                sb.append(c);
            }
        }

        return sb.toString();
    }
}

