import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int distinctSequences(int n) {
        Map<Integer, Integer> memo = new HashMap<>();
        return dfs(n, 0, -1, memo);
    }

    private int dfs(int n, int i, int prev, Map<Integer, Integer> memo) {
        if (i == n) {
            return 1;
        }
        if (memo.containsKey(i)) {
            return memo.get(i);
        }
        int res = 0;
        for (int j = 1; j <= 6; j++) {
            // Check if the current roll is equal to the previous one and there is no gap of 2 rolls between them
            if ((j == prev) || gcd(j, prev) != 1) { 
                res += dfs(n, i + 1, j, memo);
            }
        }
        memo.put(i, res % MOD);
        return res % MOD;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

