public class Solution {
    public long numberOfWays(int startPos, int endPos, int k) {
        int diff = Math.abs(endPos - startPos);
        if (diff > k) return 0;

        long ways = comb(k, diff);
        return ways % (1e9 + 7);
    }

    private long comb(int n, int r) {
        if (r > n - r) r = n - r;
        long result = 1;
        for (int i = 0; i < r; ++i) {
            result = (result * ((long)(n - i))) % ((long)(1e9 + 7));
        }
        return result;
    }
}

