public class Solution {
    public int largestOverlap(int[][] img1, int[][] img2) {
        if (img1 == null || img2 == null || img1.length == 0 || img2.length == 0 || img1[0].length == 0 || img2[0].length == 0) {
            return 0;
        }

        // Initialize a 2D array to store the count of overlapping pixels for each possible translation.
        int[][] overlapCount = new int[img1.length + img2.length][img1[0].length + img2[0].length];

        // Iterate over all possible translations.
        for (int i = -img1.length; i < img2.length; i++) {
            for (int j = -img1[0].length; j < img2[0].length; j++) {
                // For each translation, iterate over all pixels in both images and count the overlapping pixels.
                for (int x = 0; x < img1.length; x++) {
                    for (int y = 0; y < img1[0].length; y++) {
                        int newX = x + i;
                        int newY = y + j;

                        // Check whether the current pixel is within the bounds of both images after applying the translation.
                        if (newX >= 0 && newX < img2.length && newY >= 0 && newY < img2[0].length) {
                            overlapCount[i + img1.length][j + img1[0].length]++;
                        }
                    }
                }
            }
        }

        // Find the maximum overlap.
        int maxOverlap = 0;
        for (int i = -img1.length; i < img2.length; i++) {
            for (int j = -img1[0].length; j < img2[0].length; j++) {
                maxOverlap = Math.max(maxOverlap, overlapCount[i + img1.length][j + img1[0].length]);
            }
        }

        return maxOverlap;
    }
}

