import java.util.Arrays;

public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;

        // Create a 2D array dp to store the minimum cost of reaching each cell in the last row
        int[] dp = new int[n];

        // Initialize the first row of dp with the sum of values in the corresponding cells of grid
        for (int j = 0; j < n; j++) {
            dp[j] = grid[0][j];
        }

        // Calculate the minimum cost of reaching each cell in the last row
        for (int i = 1; i < m; i++) {
            int[] prevRow = new int[n];
            System.arraycopy(dp, 0, prevRow, 0, n);

            for (int j = 0; j < n; j++) {
                int minCost = Integer.MAX_VALUE;
                for (int k = 0; k < n; k++) {
                    // Calculate the cost of moving from the current cell to the next row
                    int moveCostVal = prevRow[k] + grid[i - 1][k];

                    // Update minCost if a cheaper path is found
                    minCost = Math.min(minCost, moveCost[grid[i - 1][k]][j % n] + moveCostVal);
                }
                dp[j] = minCost;
            }
        }

        // Find the minimum cost of reaching any cell in the last row
        int minCost = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            minCost = Math.min(minCost, dp[j]);
        }

        return minCost;
    }
}

