public class Solution {
    public int maximumSum(int[] nums) {
        Map<Integer, Integer> map = new HashMap<>();

        int maxNum = 0;
        for (int num : nums) {
            String strNum = Integer.toString(num);

            // Remove leading zeros
            while (strNum.length() > 1 && strNum.charAt(0) == '0') {
                strNum = strNum.substring(1);
            }

            int sumOfDigits = getSumOfDigits(strNum);

            if (!map.containsKey(sumOfDigits)) {
                map.put(sumOfDigits, num);
            } else {
                int storedValue = map.get(sumOfDigits);
                if (storedValue == Integer.MIN_VALUE) { // Handle non-digit characters
                    maxNum = Math.max(maxNum, num);
                } else {
                    maxNum = Math.max(maxNum, num + storedValue);
                }
            }
        }

        return maxNum;
    }

    private int getSumOfDigits(String str) {
        int sum = 0;
        boolean hasNonDigitChar = false;
        for (char c : str.toCharArray()) {
            if (Character.isDigit(c)) { // only add digits to the sum
                sum += Character.getNumericValue(c);
            } else {
                hasNonDigitChar = true;
            }
        }
        return hasNonDigitChar ? Integer.MIN_VALUE : sum; // Return a special value for non-digit characters
    }
}

