import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long countPairs(int n, int[][] edges) {
        Map<Integer, Integer> parent = new HashMap<>();

        // Initialize parent map with all nodes as their own parents
        for (int i = 0; i < n; i++) {
            parent.put(i, i);
        }

        // Union find to group connected components together
        for (int[] edge : edges) {
            int u = find(parent, edge[0]);
            int v = find(parent, edge[1]);

            if (u != v) {
                parent.put(v, u);
            }
        }

        Map<Integer, Integer> componentSizes = new HashMap<>();

        // Update the size of each component
        for (int i = 0; i < n; i++) {
            int root = find(parent, i);

            // Update the size of the current component
            componentSizes.put(root, componentSizes.getOrDefault(root, 0) + 1);
        }

        long count = 0;

        // Calculate the number of pairs within each component
        for (Map.Entry<Integer, Integer> entry : componentSizes.entrySet()) {
            int size = entry.getValue();
            count += (long) size * (size - 1) / 2;
        }

        return count;
    }

    private int find(Map<Integer, Integer> parent, int x) {
        if (x == parent.get(x)) {
            return x;
        } else {
            int root = find(parent, parent.get(x));
            parent.put(x, root);
            return root;
        }
    }
}

