import java.util.*;

public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        int[] dist1 = new int[n];
        Arrays.fill(dist1, Integer.MAX_VALUE);
        int[] dist2 = new int[n];
        Arrays.fill(dist2, Integer.MAX_VALUE);

        Queue<Integer> q1 = new LinkedList<>();
        Queue<Integer> q2 = new LinkedList<>();

        boolean[] visited = new boolean[n];

        q1.offer(node1);
        q2.offer(node2);

        while (!q1.isEmpty() && !q2.isEmpty()) {
            if (dist1[q1.peek()] < dist2[q2.peek()]) {
                int node = q1.poll();
                int edge = edges[node];
                if (edge == -1) continue;
                if (visited[edge] || dist1[edge] > dist1[node] + 1) {
                    // If the node has already been visited or its distance is not updated, return -1
                    return -1;
                }
                visited[edge] = true; // Mark the node as visited
                if (dist1[edge] > dist1[node] + 1) {
                    dist1[edge] = dist1[node] + 1;
                    q1.offer(edge);
                }
            } else if (dist2[q2.peek()] < dist1[q1.peek()]) {
                int node = q2.poll();
                int edge = edges[node];
                if (edge == -1) continue;
                if (visited[edge] || dist2[edge] > dist2[node] + 1) {
                    // If the node has already been visited or its distance is not updated, return -1
                    return -1;
                }
                visited[edge] = true; // Mark the node as visited
                if (dist2[edge] > dist2[node] + 1) {
                    dist2[edge] = dist2[node] + 1;
                    q2.offer(edge);
                }
            } else {
                // No common node, return -1
                return -1;
            }
        }

        int minDist = Integer.MAX_VALUE;
        int result = -1;
        for (int i = 0; i < n; i++) {
            if (dist1[i] != Integer.MAX_VALUE && dist2[i] != Integer.MAX_VALUE) {
                int maxDist = Math.max(dist1[i], dist2[i]);
                if (maxDist < minDist || (maxDist == minDist && i < result)) {
                    minDist = maxDist;
                    result = i;
                }
            }
        }

        return result;
    }
}

