public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = (long) 1e9 + 7;
        Map<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i <= n; i++) {
            if (i >= forget && !map.containsKey(i)) {
                continue;
            }

            int shareDay = Math.max(0, i - delay);
            int forgetDay = Math.min(n, i - forget);

            map.put(i, (int) ((map.getOrDefault(i, 0) + 
                       (shareDay < forgetDay ? map.getOrDefault(shareDay, 0) : 0)) % MOD));
        }

        return (int) map.getOrDefault(n, 0); // Return 0 if n is not a key in the map
