public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();

        // Check if the lengths of both strings are equal
        if (n != target.length()) return false;

        // Initialize two pointers at the beginning of each string
        int i = 0, j = 0;

        while (i < n && j < n) {
            // Check for 'L' characters in start and move to the next character in both strings if it matches with target
            if (start.charAt(i) == 'L') {
                if (target.charAt(j) != 'L') return false;
                i++;
                j++;
            }

            // Check for 'R' characters in start and move to the next character in both strings if it matches with target
            else if (start.charAt(i) == 'R') {
                if (j < n && target.charAt(j) == '_') { 
                    i++;
                    j++;
                } else if (target.charAt(j) != 'R') return false; // If not '_', check if it matches with target
                i++;
                j++;
            }

            // Check for '_' characters in start and move to the next character in both strings
            else if (start.charAt(i) == '_') {
                i++;
                j++;
            }

            // Check for '_' characters in target and move to the next character in start
            else if (target.charAt(j) == '_') {
                i++;
                j++;
            }
        }

        // Check if all characters in both strings have been processed
        return i == n && j == n;
    }
}

