import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;

        // Use a fixed-size array to store the maximum charge cost among k robots
        int[] maxChargeCosts = new int[n];
        for (int i = 0; i < n; i++) {
            maxChargeCosts[i] = chargeTimes[i];
        }
        Arrays.sort(maxChargeCosts);

        // Initialize variables to keep track of the sliding window
        int left = 0, right = 0;
        long sum = 0;

        while (right < n) {
            // Add right into the sliding window
            maxChargeCosts[right] = chargeTimes[right];
            Arrays.sort(maxChargeCosts);
            sum += runningCosts[right];

            // Update sliding window max and window sum
            while (!Arrays.binarySearch(maxChargeCosts, 0, n - left, chargeTimes[left]) >= 0 && sum * (right - left + 1) > budget) {
                if (maxChargeCosts[n - left] <= sum) { 
                    // Shrink window from front
                    sum -= runningCosts[left];
                    right--;
                } else {
                    // Update sliding window max and window sum
                    sum += runningCosts[right];
                    right++;
                }
            }

            if (sum * (right - left + 1) <= budget && right - left > 0) { 
                // Condition is met in the window, do nothing
                right++;
            } else {
                // Condition is not met in the window, shrink one from the front
                left++;
            }
        }

        return right - left;
    }
}

