        dp[0] = 1;

        for (int i = 1; i < n; i++) {
            // For each element, find the minimum number of replacements needed to make it equal to the previous elements
            int minReplacements = Integer.MAX_VALUE;
            for (int j = 0; j <= i - 1; j++) {
                if (nums[j] >= nums[i]) {
                    minReplacements = Math.min(minReplacements, dp[j]);
                }
            }

            // Update dp array with the minimum number of replacements needed
            dp[i] = minReplacements + 1;
        }

        // Find the maximum value in the dp array and add it to ans
        long maxVal = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            maxVal = Math.max(maxVal, dp[i]);
        }
        ans += maxVal;

        return ans - n + 1;
    }
}

