import com.github.leetcode.ListNode;

public class Solution {
    public int[][] generateMatrix(int m, int n, ListNode head) {
        if (head == null || m <= 0 || n <= 0) return new int[m][n];

        int[][] matrix = new int[m][n];
        int rowBegin = 0;
        int rowEnd = m - 1;
        int colBegin = 0;
        int colEnd = n - 1;

        while (head != null) {
            // Traverse from left to right
            for (int i = colBegin; i <= colEnd; i++) {
                matrix[rowBegin][i] = head.val;
                head = head.next;
            }
            rowBegin++;

            // Traverse from top to bottom
            for (int i = rowBegin; i <= rowEnd; i++) {
                matrix[i][colEnd] = head.val;
                head = head.next;
            }
            colEnd--;

            // Traverse from right to left
            if (rowBegin <= rowEnd) {
                for (int i = colEnd; i >= colBegin; i--) {
                    matrix[rowEnd][i] = head.val;
                    head = head.next;
                }
                rowEnd--;
            }

            // Traverse from bottom to top
            if (colBegin <= colEnd) {
                for (int i = rowEnd; i >= rowBegin; i--) {
                    matrix[i][colBegin] = head.val;
                    head = head.next;
                }
                colBegin++;
            }
        }

        return matrix;
    }
}

