public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        // Calculate total minutes to pick up each type of garbage
        int maxMetal = 0;
        int maxPaper = 0;
        int maxGlass = 0;

        for (int i = 0; i < garbage.length; i++) {
            if (garbage[i].contains("M")) {
