public class Solution {
    public int validSubarraySize(int[] nums, int threshold, int k) {
        if (nums.length == 0 || k < 1) return -1;

        int max = Arrays.stream(nums).max().getAsInt();
        if (max <= threshold / k) return -1;

        int left = 0, right = 0;
        while (right < nums.length) {
            if (nums[right] > threshold / k) {
                right++;
            } else {
                left++;
            }

            if (right - left >= k) {
                return right - left;
            }
        }

        return -1;
    }
}

