import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final int[][] DIRECTIONS = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
    private int n;

    public int countPaths(int[][] grid) {
        if (grid == null || grid.length == 0) {
            return 0; // or throw an exception, depending on your requirements
        }

        int m = grid.length;
        this.n = grid[0].length; // Initialize the class-level variable n

        long[] dp = new long[m * n];
        Arrays.fill(dp, -1);

        return (int) dfs(grid, dp, 0, 0);
    }

    private long dfs(int[][] grid, long[] dp, int i, int j) {
        if (i < 0 || i >= grid.length || j < 0 || j >= n) { // Use the class-level variable n
            return 0;
        }
        if (dp[i * n + j] != -1) {
            return dp[i * n + j];
        }

        long count = 0;

        for (int[] dir : DIRECTIONS) {
            int x = i + dir[0];
            int y = j + dir[1];

            if (x >= 0 && x < grid.length && y >= 0 && y < n // Use the class-level variable n
                    && grid[x][y] > grid[i][j]) {
                count += dfs(grid, dp, x, y);
            }
        }

        return dp[i * n + j] = count % MOD;
    }
}

