public class Solution {
    public int minimumOperations(int[] nums) {
        if (nums.length == 0) return 0;

        Arrays.sort(nums);
        int operations = 0;
        int min = Integer.MAX_VALUE;

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0 && nums[i] <= min) {
                min = nums[i];
            } else if (nums[i] > min) {
                while (nums[i] > min) {
                    int x = Math.min(min, nums[i]);
                    nums[i] -= x;
                    operations++;
                }
            }
        }

        return operations;
    }
}

