public class Solution {
    public int distinctNames(String[] ideas) {
        Map<Character, Set<String>> map = new HashMap<>();

        for (String idea : ideas) {
            char firstChar = idea.charAt(0);

            if (!map.containsKey(firstChar)) {
                map.put(firstChar, new HashSet<>());
            }

            map.get(firstChar).add(idea.substring(1));
        }

        int count = 0;

        for (Map.Entry<Character, Set<String>> entry : map.entrySet()) {
            char firstChar = entry.getKey();
            Set<String> setA = entry.getValue();

            for (char secondChar : map.keySet()) {
                if (secondChar != firstChar) {
                    Set<String> setB = map.get(secondChar);

                    int countAB = 0;
                    String ideaB = null;
                    for (String ideaA : setA) {
                        ideaB = getIdea(setB, ideaA);

                        if (ideaB == null) {
                            countAB++;
                        }
                    }

                    int countBA = 0;
                    String ideaA = null;
                    for (String ideaBTemp : setB) {
                        ideaA = getIdea(setA, ideaBTemp);

                        if (ideaA == null) {
                            countBA++;
                        }
                    }

                    if (ideaB != null && ideaA != null) {
                        boolean isValidPair = !map.get(firstChar).contains(ideaB.substring(1)) 
                                            && !map.get(secondChar).contains(ideaA.substring(1));

                        if (isValidPair) {
                            count += Math.max(countAB + 1, countBA + 1);
                        }
                    }
                }
            }
        }

        return count;
    }

    private String getIdea(Set<String> set, String idea) {
        for (String s : set) {
            if (!s.equals(idea)) {
                char firstChar = s.charAt(0);
                if (firstChar != idea.charAt(0)) {
                    return s;
                }
            }
        }

        return null;
    }
