import java.util.*;

public class Solution {
    int[] parent;
    int[] size;
    int totalXor = 0;
    boolean[] blocked;

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        parent = new int[n];
        size = new int[n];
        blocked = new boolean[n];

        for (int i = 0; i < n; i++) {
            totalXor ^= nums[i];
        }

        for (int[] edge : edges) {
            addEdge(edge[0], edge[1]);
        }

        int minScore = Integer.MAX_VALUE;
        for (int i = 0; i < n - 1; i++) {
            blocked[i] = true;
            for (int j = i + 1; j < n - 1; j++) {
                blocked[j] = true;
                minScore = Math.min(minScore, findSecondEdge(nums, i) ^ findSecondEdge(nums, j));
                blocked[j] = false;
            }
            blocked[i] = false;
        }
        return minScore;
    }

    private int findSecondEdge(int[] nums, int src) {
        if (size[src] == 1) {
            return totalXor;
        }

        int xor = 0;
        for (int nbr : getChildren(src)) {
            if (!blocked[nbr]) {
                xor ^= findSecondEdge(nums, nbr);
            }
        }

        // Calculate the XOR value of all nodes in the current component
        List<Integer> children = getChildren(src);
        for (int i = 0; i < children.size(); i++) {
            int child = children.get(i);
            if (!blocked[child] && !isBlockedChild(child)) {  
                xor ^= nums[child];
            }
        }

        return Math.max(xor, totalXor ^ xor);
    }

    private boolean isBlockedChild(int child) {
        int parent = find(parent[child], child);
        return blocked[parent];
    }

    private void addEdge(int u, int v) {
        parent[v] = u;
        size[u]++;
        size[v]++;
    }

    private List<Integer> getChildren(int src) {
        List<Integer> children = new ArrayList<>();
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == src && i != src) {
                children.add(i);
            }
        }
        return children;
    }

    private int find(int u, int v) {
        while (u != v) {
            if (size[u] > size[v]) {
                v = parent[v];
            } else {
                u = parent[u];
            }
        }
        return u;
    }
}

