public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        // Find the smallest divisor that divides all elements in numsDivide
        int gcd = 0;
        for (int i = 1; i <= Arrays.stream(numsDivide).min().getAsInt(); i++) {
            if (isDivisible(Arrays.stream(numsDivide).min().getAsInt(), i)) {
                boolean isDivisor = true;
                for (int num : numsDivide) {
                    if (!isDivisible(num, i)) {
                        isDivisor = false;
                        break;
                    }
                }
                if (isDivisor) {
                    gcd = i;
                    break;
                }
            }
        }

        // Count how many numbers in nums are not divisible by the smallest divisor
        int count = 0;
        Arrays.sort(nums);
        for (int num : nums) {
            if (!isDivisible(num, gcd)) {
                count++;
            }
        }

        return count == nums.length ? -1 : count;
    }

    private boolean isDivisible(int num, int divisor) {
        return num % divisor == 0;
    }
}

