import java.util.*;

public class Solution {
    int[] parent;
    int[] size;
    int n;

    public UF(int n) {
        this.n = n;
        parent = new int[n];
        size = new int[n];

        Arrays.fill(parent, -1);
        Arrays.fill(size, 1);

        for (int i = 0; i < n; i++) {
            insert(i, 0);
        }
    }

    public void insert(int x, int value) {
        union(x, x + 1);
        updateSize(x);
        updateSize(x + 1);
    }

    private int find(int x) {
        if (parent[x] < 0) return x;
        parent[x] = find(parent[x]);
        return parent[x];
    }

    public void union(int x, int y) {
        x = find(x);
        y = find(y);

        if (x != y) {
            if (size[x] > size[y]) {
                int temp = x;
                x = y;
                y = temp;
            }
            parent[x] += parent[y];
            parent[y] = x;
            size[x] += size[y];
            size[y] = 0;
        }
    }

    public void updateSize(int i) {
        if (parent[i] < 0) {
            size[i] = 1;
        } else {
            int p = find(i);
            size[i] = size[p];
        }
    }

    public long getSum(int l, int r) {
        int x = find(l), y = find(r);

        if (x == y) return parent[x];

        long sum = 0;
        while (x != y) {
            if (size[x] > size[y]) {
                int temp = x;
                x = y;
                y = temp;
            }
            sum += parent[x];
            x = parent[x];
        }

        return sum + Math.min(parent[x], 0);
    }
}

public class Solution {
    public int[] maxSumAfterRemoval(int[] nums, int[] removeQueries) {
        UF uf = new UF(nums.length);
        int n = nums.length;

        int[] answer = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int index = removeQueries[i];

            if (index == 0 || index == n - 1) {
                answer[i] = Arrays.stream(nums).sum();
                continue;
            }

            long sum = uf.getSum(index, index + 1);
            answer[i] = Math.max((int) sum, nums[index]);
        }

        return answer;
    }
}

