public class Solution {
    public String largestPalindromic(String num) {
        Map<Character, Integer> map = new HashMap<>();

        // Count frequency of each digit
        for (char c : num.toCharArray()) {
            map.put(c, map.getOrDefault(c, 0) + 1);
        }

        StringBuilder sb = new StringBuilder();

        // Place the largest digits in the middle and then fill up from both ends
        while (!map.isEmpty()) {
            char maxChar = '0';
            for (char c : map.keySet()) {
                if (c > maxChar) {
                    maxChar = c;
                }
            }

            int count = map.get(maxChar);
            // If the count is even, place it in the middle
            if (count % 2 == 0) {
                for (int i = 0; i < count / 2; i++) { 
                    sb.append(maxChar);
                }
            } 
            // If the count is odd, place one extra digit in the middle and then fill up from both ends
            else {
                sb.append(maxChar).append(maxChar);
                for (int i = 0; i < count / 2; i++) { 
                    sb.append(maxChar);
                }
            }

            // Remove the used digit from the map
            map.remove(maxChar);
        }

        return sb.toString();
    }
}

