public class Solution {
    public int longestIdealString(String s, int k) {
        int[] count = new int[26];

        for (char c : s.toCharArray()) {
            int index = c - 'a';

            // Check if the current character can be added to the ideal string
            boolean isIdeal = false;
            for (int i = Math.max(0, index - k); i <= Math.min(index + k, 25); i++) {
                if (count[i] > 0 && Math.abs(i - index) <= k) {
                    isIdeal = true;
                    break;
                }
            }

            // If the current character can be added to the ideal string
            if (isIdeal) {
                count[index]++;
            }
        }

        int maxCount = 0;
        for (int i : count) {
            maxCount = Math.max(maxCount, i);
        }

        return maxCount + 1; // Add 1 because we need to add one more character to make it a subsequence
    }
}

