public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        boolean[][] dp = new boolean[n][4];

        // Initialize base cases
        if(n >= 2 && nums[0] == nums[1]) dp[1][2] = true;
        if(n >= 3 && nums[0] == nums[1] && nums[1] == nums[2]) {
            dp[2][3] = true;
            dp[1][2] = true; // Add this line
        }
        dp[0][2] = true; // Initialize base cases for 2 equal elements
        dp[0][3] = true; // Initialize base cases for 3 consecutive increasing elements

        for(int i = 2; i < n; i++) {
            if(nums[i] == nums[i-1]) {
                dp[i][2] = true;
                if(i >= 3 && nums[i] == nums[i - 2]) dp[i][3] |= dp[i - 2][3];
            }
            if(i >= 2 && nums[i] == nums[i-1] && nums[i] == nums[i-2]) dp[i][3] |= dp[i-2][3];

            if(i >= 3) {
                if(nums[i] == nums[i - 1] + 1 && i >= 3 && nums[i-1] == nums[i - 2] + 1) dp[i][3] |= dp[i - 2][3];
            }
        }

        for(int i = 0; i < n; i++) {
            if(dp[i][2] || dp[i][3]) return true;
        }

        return false;
    }
}

