import java.util.Arrays;

public class Solution {
    public int fillCups(int[] amount) {
        Arrays.sort(amount);

        int seconds = 0;
        while (amount[0] > 0 || amount[1] > 0 || amount[2] > 0) {
            // Try to fill up as many cups as possible in each second
            if (amount[0] >= 2 && amount[1] == 0 && amount[2] == 0) {
                amount[0] -= 2;
                seconds++;
            } else if (amount[1] >= 2 && amount[0] == 0 && amount[2] == 0) {
                amount[1] -= 2;
                seconds++;
            } else if (amount[2] >= 2 && amount[0] == 0 && amount[1] == 0) {
                amount[2] -= 2;
                seconds++;
            } else {
                // Fill up one cup of any type
                int min = Math.min(amount[0], Math.min(amount[1], amount[2]));
                if (amount[0] > 0 && amount[0] == min) {
                    amount[0]--;
                } else if (amount[1] > 0 && amount[1] == min) {
                    amount[1]--;
                } else {
                    amount[2]--;
                }
            }
        }

        return seconds;
    }
}

