// #2022_08_14_Time_0_ms_(100.00%)_Space_70.5_MB_(27.33%)
public class Solution {
    public int maximumGroups(int[] grades) {
        long sum = 0;
        for (int grade : grades) {
            sum += grade;
        }

        int n = grades.length;
        int low = 1, high = n / 2 + 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            long totalSum = 0;
            for (int i = 1; i <= mid; i++) {
                if (i == mid) {
                    totalSum += sum;
                } else {
                    totalSum += (sum / mid);
                }
            }

            if (totalSum < sum) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low - 1;
    }
}

