public class Solution {
    public String greatestLetter(String s) {
        int[] count = new int[26];

        // Count frequency of lowercase letters
        for (char c : s.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                count[c - 'a']++;
            }
        }

        // Find the greatest letter that appears in both uppercase and lowercase forms
        String result = "";
        for (int i = 25; i >= 0; i--) {
            char c = (char) ('A' + i);
            if (count[i] > 0 && s.contains(String.valueOf(c))) {
                if (!result.isEmpty() && c < result.charAt(0)) {
                    continue;
                }
                result = String.valueOf(c);
            }
        }

        return result;
    }
}

