import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        Map<Character, Integer> suitCount = new HashMap<>();
        Map<Integer, Integer> rankCount = new HashMap<>();

        // Count the occurrences of each suit
        for (char suit : suits) {
            suitCount.put(suit, suitCount.getOrDefault(suit, 0) + 1);
        }

        // Check if there is a flush
        if (suitCount.values().stream().anyMatch(count -> count >= 5)) {
            return "Flush";
        }

        // Count the occurrences of each rank
        for (int rank : ranks) {
            rankCount.put(rank, rankCount.getOrDefault(rank, 0) + 1);
        }

        // Check if there is a three of a kind
        if (rankCount.values().stream().anyMatch(count -> count >= 3)) {
            return "Three of a Kind";
        }

        // Check if there are pairs
        int pairCount = 0;
        for (int rank : ranks) {
            if (rankCount.get(rank) == 2) {
                pairCount++;
            }
        }
        if (pairCount >= 2) {
            return "Pair";
        }

        // If none of the above conditions are met, it's a high card
        return "High Card";
    }
}

