import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        if (nums1.length == 0) {
            return 0; // or some other default value
        }

        int n = nums1.length;
        long totalDifferences = 0;

        // Calculate the sum of squared differences
        for (int i = 0; i < n; i++) {
            totalDifferences += (long)(nums1[i] - nums2[i]) * (nums1[i] - nums2[i]);
        }

        int[] diffCounts = new int[n + 1];

        // Count the number of differences
        for (int i = 0; i < n && Math.abs(nums1[i] - nums2[i]) <= n; i++) {
            if (nums1[i] != nums2[i]) {
                diffCounts[Math.abs(nums1[i] - nums2[i])]++;
            }
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>();

        // Add the counts of differences to a priority queue
        for (int i = 0; i < n && Math.abs(i) <= n; i++) {
            if (diffCounts[i] > 0) {
                pq.offer(diffCounts[i]);
            }
        }

        long kSum = k1 + k2;

        while (!pq.isEmpty() && kSum >= pq.peek()) {
            int groupSize = pq.poll();

            // If the current group has more differences than the totalK, we can only move k of them
            // to the lower level.
            if (groupSize > kSum) {
                long diffToMove = Math.min(groupSize - 1, kSum);
                kSum -= (int)diffToMove;
                totalDifferences += 2 * diffToMove * (long)groupSize; // Corrected formula
                pq.offer((int)(groupSize - diffToMove));
            } else {
                // We can make this whole group one level lower.
                totalDifferences += 2 * groupSize * (long)(n - groupSize);
                kSum -= groupSize;
            }
        }

        return totalDifferences;
    }
}

