import java.util.Arrays;

public class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double tax = 0.0;
        for (int i = 0; i < brackets.length; i++) {
            int upperBound = brackets[i][0];
            double rate = brackets[i][1] / 100.0;

            // Calculate the tax for this bracket
            if (i == brackets.length - 1) {
                tax += Math.min(income, upperBound) * rate;
            } else {
                int remainingIncome = Math.max(0, income - upperBound);
                if(remainingIncome > 0){
                    tax += Math.min(remainingIncome, brackets[i + 1][0] - upperBound) * rate;
                }
            }
        }

        return tax;
    }
}

