import java.util.*;

public class Solution {
    private int maxCycleLength = -1; // declare maxCycleLength as a class variable

    public int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        Map<Integer, Integer> depthMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, edges, visited, depthMap);
            }
        }

        return maxCycleLength;
    }

    private void dfs(int node, int[] edges, boolean[] visited, Map<Integer, Integer> depthMap) {
        if (!visited[node]) {
            visited[node] = true;

            if (edges[node] != -1) {
                int currentDepth = depthMap.getOrDefault(node, 0); // Get the current depth of node or default to 0 if it hasn't been visited before
                depthMap.put(node, currentDepth + 1);
                dfs(edges[node], edges, visited, depthMap);

                // If the node is already visited and its depth is greater than 0,
                // it means we've found a cycle
                if (depthMap.get(node) > 0 && depthMap.get(edges[node]) >= depthMap.get(node)) {
                    int j = node;
                    int cycleLength = 0;

                    while (edges[j] != -1 && edges[j] != node) { // changed i to node
                        j = edges[j];
                        cycleLength++;
                    }

                    if (edges[j] == node) {
                        maxCycleLength = Math.max(maxCycleLength, cycleLength + 1);
                    }
                }
            }
        } else {
            // If the node is already visited, it means we've found a cycle
            int j = node;
            int cycleLength = 0;

            while (edges[j] != -1 && edges[j] != node) { // changed i to node
                j = edges[j];
                cycleLength++;
            }

            if (edges[j] == node) {
                maxCycleLength = Math.max(maxCycleLength, cycleLength + 1);
            }
        }
    }
}

