// #Easy #Array #Matrix #2022_06_28_Time_3_ms_(53.58%)_Space_54_MB_(83.44%)
public class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;

        // Check the main diagonal
        for (int i = 0; i < n; i++) {
            if (grid[i][i] == 0) return false;
        }

        // Check the anti-diagonal
        for (int i = 0; i < n; i++) {
            if (grid[i][n - i - 1] == 0) return false;
        }

        // Check all other elements
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if(grid[i][j] == 0 && !(i == j || i == n - j - 1)) return false;
            }
        }

        // If all checks pass, the matrix is an X-Matrix
        return true;
    }
}

