public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        int n = matrix[0].length;

        // Create a boolean array to store the selected columns
        boolean[] selectedColumns = new boolean[n];

        // Initialize the count of covered rows
        int maxCoveredRows = 0;

        // Iterate over all possible subsets of numSelect columns
        for (int i = 1; i <= (1 << n); i++) {
            // Create a temporary array to store the current subset of selected columns
            boolean[] tempSelectedColumns = new boolean[n];

            int count = Integer.bitCount(i);
            if (count > numSelect) continue;

            // Check if the current subset covers more rows than the previous best
            int coveredRows = 0;
            for (int j = 0; j < m; j++) {
                boolean isRowCovered = true;
                for (int k = 0; k < n; k++) {
                    if ((i & (1 << k)) == 0 && matrix[j][k] == 1) {
                        isRowCovered = false;
                        break;
                    }
                }
                if (isRowCovered) {
                    coveredRows++;
                }
            }

            // Update the maximum number of rows that can be covered
            maxCoveredRows = Math.max(maxCoveredRows, coveredRows);
        }

        return maxCoveredRows;
    }
}

