import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        Map<String, Long> memo = new HashMap<>();

        return dp(m, n, prices, memo);
    }

    private long dp(int m, int n, int[][] prices, Map<String, Long> memo) {
        String key = m + "*" + n;

        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        long maxProfit = 0;

        for (int[] price : prices) {
            int h = price[0];
            int w = price[1];

            if (h <= m && w <= n) {
                // Calculate the number of pieces that can be cut from the current piece
                int numPiecesH = (m + h - 1) / h;
                int numPiecesW = (n + w - 1) / w;

                long profit = price[2] * numPiecesH * numPiecesW;

                maxProfit = Math.max(maxProfit, profit);
            }
        }

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (i < m && j < n) {
                    long profit = dp(i, j, prices, memo) + dp(m - i, n - j, prices, memo);
                    maxProfit = Math.max(maxProfit, profit);
                } else if (i == m || j == n) {
                    // Add a base case here
                    return price[2] * ((m + 1) / (price[0] + 1)) * ((n + 1) / (price[1] + 1));
                }
            }
        }

        memo.put(key, maxProfit);

        return maxProfit;
    }
}

