import java.util.*;

public class Solution {
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        // Base case: when the length of row or col is less than k, return empty.
        if (rowC.length < k || colC.length < k) {
            return new int[0][];
        }

        // Create a graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 1; i <= k; i++) {
            graph.put(i, new ArrayList<>());
        }
        for (int[] condition : rowC) {
            graph.get(condition[0]).add(condition[1]);
        }
        for (int[] condition : colC) {
            graph.get(condition[0]).add(condition[1]);
        }

        // Create a map to record the indegree of each number
        int[] indegrees = new int[k + 1];
        for (List<Integer> neighbors : graph.values()) {
            for (int neighbor : neighbors) {
                indegrees[neighbor]++;
            }
        }

        // Create a queue to do BFS
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (indegrees[i] == 0) {
                queue.offer(i);
            }
        }

        // Start the topo sort
        int[][] result = new int[k][k];
        int row = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (int neighbor : graph.get(node)) {
                indegrees[neighbor]--;
                if (indegrees[neighbor] == 0) {
                    queue.offer(neighbor);
                }
            }
            result[row][row] = node;
            row++;
        }

        // If the length of result is less than k, return empty.
        if (result.length < k) {
            return new int[0][];
        }

        // Fill the remaining cells
        for (int i = 1; i <= k; i++) {
            boolean[] visited = new boolean[k + 1];
            Arrays.fill(visited, false);
            fill(result, i, graph, indegrees, visited);
        }

        return result;
    }

    private void fill(int[][] result, int node, Map<Integer, List<Integer>> graph, int[] indegrees, boolean[] visited) {
        if (node > result.length || node <= 0) {
            return;
        }

        // Find an empty cell in the matrix that satisfies the conditions
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result[0].length; j++) {
                if (result[i][j] == 0) {
                    boolean isValid = true;

                    // Check if placing the node at this position satisfies the conditions
                    for (int neighbor : graph.get(node)) {
                        int row = -1, col = -1;

                        // Find the positions of the neighboring nodes in the matrix
                        for (int k = 0; k < result.length; k++) {
                            if (result[k][j] == neighbor) {
                                row = k;
                                break;
                            }
                        }

                        if (row != -1 && i > row) {
                            isValid = false;
                            break;
                        }

                        // Check column condition
                        for (int k = 0; k < result[0].length; k++) {
                            if (result[i][k] == neighbor) {
                                col = k;
                                break;
                            }
                        }

                        if (col != -1 && j > col) {
                            isValid = false;
                            break;
                        }
                    }

                    // If the position is valid, place the node at this position
                    if (isValid) {
                        result[i][j] = node;
                        return;
                    }
                }
            }
        }
    }
}

