import java.util.HashMap;
import java.util.Map;

public class Solution {
    private TrieNode root;

    public int maximumXOR(int[] nums) {
        root = new TrieNode();
        for (int num : nums) {
            insert(num);
        }

        int result = 0;
        for (int i = 31; i >= 0; --i) {
            if ((result | (1 << i)) != result && hasPath(root, result | (1 << i))) {
                result |= (1 << i);
            }
        }

        return result;
    }

    private void insert(int num) {
        TrieNode current = root;
        for (int i = 31; i >= 0; --i) {
            char bit = (num >> i & 1) == 1 ? '1' : '0';
            if (!current.children.containsKey(bit)) {
                current.children.put(bit, new TrieNode());
            }
            current = current.children.get(bit);
        }
        current.endOfWord = true;
    }

    private boolean hasPath(TrieNode node, int num) {
        for (int i = 31; i >= 0; --i) {
            char bit = (num >> i & 1) == 1 ? '1' : '0';
            if (!node.children.containsKey(bit)) {
                return false;
            }
            node = node.children.get(bit);
        }
        return true;
    }

    private static class TrieNode {
        Map<Character, TrieNode> children;
        boolean endOfWord;

        public TrieNode() {
            this.children = new HashMap<>();
            this.endOfWord = false;
        }
    }
}

