public class Solution {
    public int minimumRecolors(String blocks, int k) {
        // Check if there are at least k black blocks in total
        int count = 0;
        for (char c : blocks.toCharArray()) {
            if (c == 'B') {
                count++;
            }
        }
        if (count < k) {
            return -1; // Not enough black blocks to form a window of size k
        }

        int minOperations = 0;

        int left = 0;
        int right = k - 1;

        while (right < blocks.length()) {
            int whiteCount = 0;
            for (int i = left; i <= right; i++) {
                if (blocks.charAt(i) == 'W') {
                    whiteCount++;
                }
            }

            // Calculate the number of operations needed to get k consecutive black blocks
            int blackBlocksInWindow = k - whiteCount;

            minOperations = Math.min(minOperations, whiteCount);

            // Move the window to the right
            left++;
            right++;
        }

        return minOperations;
    }
}

