public class Solution {
    public int[][] largestLocal(int[][] grid) {
        int n = grid.length;
        int[][] maxLocal = new int[n - 2][n - 2];

        for (int i = 0; i < n - 2; i++) {
            for (int j = 0; j < n - 2; j++) {
                int max = Integer.MIN_VALUE;

                // Check the 3x3 matrix centered at grid[i+1][j+1]
                for (int x = Math.max(0, i); x <= Math.min(n-3, i); x++) {
                    for (int y = Math.max(0, j); y <= Math.min(n-3, j); y++) {
                        max = Math.max(max, grid[x+1][y+1]);
                    }
                }

                // Store the maximum value in maxLocal
                maxLocal[i][j] = max;
            }
        }

        return maxLocal;
    }
}

