import java.util.Arrays;

public class Solution {
    public int[] numberOfPairs(int[] nums) {
        Arrays.sort(nums);
        int pairs = 0;
        int leftovers = 0;

        // Sort the array first to group consecutive equal integers together
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                int count = 2;
                while (i < nums.length - 1 && nums[i] == nums[i + 1]) {
                    i++;
                    count++;
                }
                pairs += count / 2; // increment pairs by the number of pairs in this group
            } else {
                leftovers++; // increment leftoverCount when encountering a non-paired element
            }
        }

        // Check for leftover elements at the end of the array
        if (nums[nums.length - 1] != nums[nums.length - 2]) {
            leftovers++;
        }

        return new int[] {pairs, leftovers};
    }
}

