public class Solution {
    public String smallestNumber(String pattern) {
        int[] num = new int[10];
        StringBuilder sb = new StringBuilder();

        if (pattern.charAt(0) == 'D') { 
            // Special case for pattern starting with 'D'
            for (int i = 9; i > 0 && num[i] != 0; i--) {
                sb.append(i);
                num[i] = 1;
            }
        } else {
            sb.append('1');
        }

        boolean prevWasD = pattern.charAt(0) == 'D';

        for (int i = 1; i < pattern.length(); i++) {
            if (pattern.charAt(i) == 'D') {
                // Find the largest number smaller than the current one
                int k;
                for (k = 9; k > 0 && num[k] != 0; k--) ;
                sb.append(k);
                num[k] = 1;
                prevWasD = true;
            } else if (pattern.charAt(i) == 'I') {
                // Find the smallest number larger than the current one
                int l;
                for (l = 1; l < 10 && num[l] != 0; l++) ;
                sb.append(l);
                num[l] = 1;
                prevWasD = false;
            }

            if (prevWasD) {
                // If the previous one was 'D', then we need to find a number that is smaller than the current one
                int m;
                for (m = k - 1; m > 0 && num[m] != 0; m--) ;
                sb.insert(sb.length() - 1, m);
            }
        }

        return sb.toString();
    }
}

package referenz;


public class Solution {
    public int countHousePlacements(int n) {
        long MOD = (long) 1e9 + 7;
        long[][] dp = new long[n + 1][2];

        // Base cases
        dp[0][0] = 1; // Empty string
        dp[0][1] = 0; // No house

        for(int i = 1; i <= n; i++) {
            // For a string of length i, we can either append '0' or '1'
            // If we append '0', the new string will be of length (i - 1) and it was not ending with '1'
            dp[i][0] = (dp[i - 1][0] + dp[i - 1][1]) % MOD;

            // If we append '1', the new string will be of length (i - 1) and it was ending with '0'
            dp[i][1] = dp[i - 1][0];
        }

        long totalWays = ((dp[n][0] + dp[n][1]) * (dp[n][0] + dp[n][1])) % MOD;
        return (int) totalWays;
    }
}

