import java.util.*;

public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        Map<String, List<Integer>> map = new HashMap<>();

        // Store count of occurrences in count[]
        for (int i = 0; i < nums.length; i++) {
            map.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }

        // Build the output array
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            String trimmedNum = trim(nums[i], queries[i][1]);
            List<Integer> indices = map.get(trimmedNum);
            if (indices != null) {
                answer[i] = indices.get(Math.min(queries[i][0], indices.size() - 1));
            }
        }

        return answer;
    }

    private String trim(String num, int k) {
        StringBuilder sb = new StringBuilder();
        for (int i = num.length() - 1; i >= Math.max(0, num.length() - k); i--) {
            sb.append(num.charAt(i));
        }
        return sb.toString();
    }
}

