import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int n = buses.length;
        int m = passengers.length;

        int latestTime = 0;
        for (int i = 0; i < n - 1; i++) {
            if (buses[i + 1] - buses[i] <= capacity) {
                int availableSeats = capacity;
                for (int j = m - 1; j >= 0; j--) {
                    if (passengers[j] <= buses[i]) {
                        if (availableSeats > 0) { // Check if there are still available seats
                            availableSeats--;
                            latestTime = Math.max(latestTime, buses[i + 1]); // Update latestTime here
                        } else {
                            break; // No more seats available on this bus, move to the next one
                        }
                    }
                }
            }
        }

        return latestTime;
    }
}

