public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();

        // Initialize dp array with zeros.
        int[] dp = new int[n + 1];

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                dp[i + 1] = dp[i] + 1;
            } else {
                dp[i + 1] = dp[i]; // Corrected line
            }
        }

        int ans = 0;
        for (int i = n; i >= 0; i--) {
            if (dp[i] <= k) { // Corrected condition
                ans = Math.max(ans, dp[i] + (n - i));
            }
        }

        return ans;
    }
}

