import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int countDistinctIntegers(int[] nums) {
        Set<Integer> set = new HashSet<>();

        for (int num : nums) {
            if (num < 10) {
                // Add the original number to the set for single-digit numbers
                set.add(num);
            } else {
                int reversedNum = 0;
                int originalNum = num; // Store the original number
                while (num > 0) {
                    reversedNum = reversedNum * 10 + num % 10;
                    num /= 10;
                }
                // Add both the original number and its reverse to the set for numbers with more than one digit
                set.add(originalNum);
                set.add(reversedNum);
            }
        }

        return set.size();
    }
}

