import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        int n = nums.length;
        long res = 0;

        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                res++;
            }

            // Count the number of elements less than or equal to k
            int countLessThanK = 0;
            for (int j = 0; j <= i; j++) {
                if (nums[j] <= k) {
                    countLessThanK++;
                }
            }

            // Count the number of elements greater than k
            int countGreaterThanK = 0;
            for (int j = i + 1; j < n; j++) {
                if (nums[j] > k) {
                    countGreaterThanK++;
                } else {
                    break;
                }
            }

            // Calculate the median of the subarray [i - countLessThanK, i]
            int median = nums[i];
            for (int j = Math.max(i - countLessThanK, 0); j <= i; j++) {
                if (nums[j] > k) {
                    median = nums[j];
                    break;
                }
            }

            // Check if the median is equal to k
            if (median == k) {
                res += countGreaterThanK + 1;
            } else {
                int countLessThanMedian = (i - countLessThanK >= 0) ? map.getOrDefault(nums[i - countLessThanK], 0) : 0;
                res += countLessThanMedian * (countGreaterThanK + 1);
            }

            // Update the map
            if(i - countLessThanK >= 0)
                map.put(nums[i - countLessThanK], map.getOrDefault(nums[i - countLessThanK], 0) + 1);
        }

        return (int)res;
    }
}

