import java.util.Arrays;

public class Solution {
    public int deleteGreatestValue(int[][] grid) {
        int max = 0;
        while (grid.length > 0 && grid[0].length > 0) {
            int maxDeleted = 0; // Initialize maxDeleted here
            for (int i = 0; i < grid.length; i++) {
                Arrays.sort(grid[i]);
                maxDeleted = Math.max(maxDeleted, grid[i][grid[i].length - 1]); // Update maxDeleted here
                grid[i] = Arrays.copyOfRange(grid[i], 0, grid[i].length - 1);
            }
            max = Math.max(max, maxDeleted); // Update max with the maximum of all deleted values so far
        }

        return max;
    }
}

