import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int hardestWorker(int[][] logs) {
        Map<Integer, Integer> timeMap = new HashMap<>();

        for (int i = 0; i < logs.length; i++) {
            int id = logs[i][0];
            int leaveTime = logs[i][1];

            if (!timeMap.containsKey(id)) {
                timeMap.put(id, 0);
            }

            timeMap.put(id, Math.max(timeMap.get(id), leaveTime - (i == 0 ? 0 : logs[i-1][1])));
        }

        int maxTime = Integer.MIN_VALUE;
        int resultId = Integer.MAX_VALUE;

        for (int id : timeMap.keySet()) {
            if (timeMap.get(id) > maxTime || (timeMap.get(id) == maxTime && id < resultId)) {
                maxTime = timeMap.get(id);
                resultId = id;
            }
        }

        return resultId;
    }
}

