public class Solution {
    public int longestSubarray(int[] nums) {
        int n = nums.length;
        int maxAnd = 0; // Initialize maxAnd with bitwise AND of all numbers in array

        for (int i = 0; i < n; i++) {
            int curAnd = 0;
            for (int j = i; j < n; j++) {
                curAnd |= nums[j];
                if (curAnd > maxAnd) {
                    maxAnd = curAnd;
                }
            }
        }

        int res = 0;
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            int curAnd = 0;
            int left = -1, right = -1;
            for (int j = i; j < n; j++) {
                curAnd |= nums[j];
                if ((curAnd & maxAnd) == maxAnd && left == -1) {
                    left = j;
                }
                if ((curAnd & maxAnd) != maxAnd) {
                    right = j - 1;
                    break;
                }
            }

            // If we found a subarray with bitwise AND equal to maxAnd
            if (left != -1 && right != -1) {
                res = Math.max(res, right - left + 1);
            } else if ((curAnd & maxAnd) == maxAnd) {
                res = Math.max(res, n - i); // If the subarray ends at the end of array
            }
        }

        return res;
    }
}

package referenz;


public class Solution {
    public boolean isCircularSentence(String sentence) {
        String[] words = sentence.split(" ");

        for (int i = 0; i < words.length - 1; i++) {
            if (words[i].charAt(words[i].length() - 1) != words[i + 1].charAt(0)) {
                return false;
            }
        }

        // Check the last word with the first word
        return words[0].charAt(words[0].length() - 1) == words[words.length - 1].charAt(0);
    }
}

