import java.util.Arrays;

public class Solution {
    public int partitionString(String s) {
        int count = 1;
        boolean[] seen = new boolean[26];

        for (char c : s.toCharArray()) {
            if (!seen[c - 'a']) {
                seen[c - 'a'] = true;
            } else {
                count++;
                Arrays.fill(seen, false);
                seen[c - 'a'] = true;
            }
        }

        return count;
    }
}

