public class Solution {
    public int smallestEvenMultiple(int n) {
        if (n % 2 == 0) { // if n is already even
            return n;
        } else { // if n is odd, find the smallest multiple of both 2 and n
            int multiplier = 1;
            while ((n * multiplier) % 2 != 0) {
                multiplier++;
            }
            return n * multiplier;
        }
    }
}

