import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        Map<Integer, Integer> numCount = new HashMap<>();
        Map<Integer, Integer> targetCount = new HashMap<>();

        for (int num : nums) {
            numCount.put(num % 2, numCount.getOrDefault(num % 2, 0) + 1);
        }

        for (int num : target) {
            targetCount.put(num % 2, targetCount.getOrDefault(num % 2, 0) + 1);
        }

        long operations = 0;

        int maxDiff = Math.max(Math.abs(numCount.getOrDefault(0, 0) - targetCount.getOrDefault(0, 0)), 
                               Math.abs(numCount.getOrDefault(1, 0) - targetCount.getOrDefault(1, 0)));

        if (maxDiff != 0) {
            operations += maxDiff / 2;
        } else if (numCount.getOrDefault(0, 0) == targetCount.getOrDefault(0, 0) && numCount.getOrDefault(1, 0) == targetCount.getOrDefault(1, 0)) {
            // If the frequencies are already equal, return 0
            operations = 0;
        }

        return operations;
    }
}

