import java.util.Arrays;

public class Solution {
    public int maxSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int maxSum = Integer.MIN_VALUE;

                // Check all possible hourglass shapes centered at the current cell
                for (int k = Math.max(0, i - 2); k <= Math.min(m - 1, i + 2); k++) {
                    for (int l = Math.max(0, j - 2); l <= Math.min(n - 1, j + 2); l++) {
                        int sum = 0;

                        // Calculate the sum of the current hourglass shape
                        for (int x = i; x >= k && x <= m - 1; x++) {
                            if (x == k) sum += grid[x][l];
                            else if (x == i) sum += grid[x][j];
                            else if (x == m - 1) sum += grid[x][l];
                            else sum += grid[x][Math.min(Math.max(l, j), n - 1)];
                        }

                        maxSum = Math.max(maxSum, sum);
                    }
                }

                // Update the maximum sum
                maxSum = Math.max(maxSum, grid[i][j]);
            }
        }

        int result = Integer.MIN_VALUE;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result = Math.max(result, maxSum(grid, i, j));
            }
        }

        return result;
    }

    private int maxSum(int[][] grid, int i, int j) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length) {
            return Integer.MIN_VALUE;
        }

        int sum = grid[i][j];

        // Check top
        for (int k = Math.max(0, i - 1); k <= Math.min(grid.length - 1, i + 1); k++) {
            if (k != i) {
                sum += grid[k][j];
            }
        }

        // Check left and right
        int maxLeftRightSum = Integer.MIN_VALUE;
        for (int k = Math.max(0, j - 1); k <= Math.min(grid[0].length - 1, j + 1); k++) {
            if (k != j) {
                sum += grid[i][k];
                maxLeftRightSum = Math.max(maxLeftRightSum, sum);
                sum -= grid[i][k];
            }
        }

        return maxLeftRightSum;
    }
}

package referenz;


import com.leetcode.TreeNode;
import java.util.Map;
import java.util.HashMap;

public class Solution {
    private int[] heights = new int[1000];
    private Map<Integer, Integer> map = new HashMap<>();
    private int maxHeight = 0;

    public int[] treeQueries(TreeNode root, int[] queries) {
        dfs(root, 0);
        for (int i : queries) {
            map.put(i, heights[i]);
        }
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            answer[i] = maxHeight - map.get(queries[i]) - 1;
        }
        return answer;
    }

    private void dfs(TreeNode node, int height) {
        if (node == null) {
            return;
        }
        heights[node.val] = Math.max(heights[node.val], height);
        maxHeight = Math.max(maxHeight, heights[node.val]);
        dfs(node.left, height + 1);
        dfs(node.right, height + 1);
    }
}

package referenz;


public class Solution {
    public String oddString(String[] w) {
        int n = w[0].length();
        int[][] diff = new int[w.length][n - 1];

        // Calculate difference array for each string
        for (int i = 0; i < w.length; i++) {
            for (int j = 0; j < n - 1; j++) {
                diff[i][j] = w[i].charAt(j + 1) - w[i].charAt(j);
            }
        }

        // Find the string with different difference array
        String result = "";
        for (int i = 0; i < w.length; i++) {
            boolean isSame = true;
            for (int j = 0; j < n - 1; j++) {
                if (diff[i][j] != diff[0][j]) {
                    isSame = false;
                    break;
                }
            }

            if (!isSame) {
                result = w[i];
                break;
            }
        }

        // If no string has different difference array, return the first string
        if (result.isEmpty()) {
            result = w[0];
            for (int j = n - 2; j >= 0; j--) {
                result += (char)(diff[0][j] + 'a');
            }
        }

        return result;
    }
}

