public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        // sort factories :
        // 1. move all factories with 0-capacity to the end
        // 2. sort everything else by x-position in asc order and then by capacity in desc order
        Arrays.sort(f, (a, b) -> a[1] == 0 ? 1 : a[0] - b[0] != 0 ? a[0] - b[0] : b[1] - a[1]);

        int[] robotArray = new int[robot.size()];
        for (int i = 0; i < robot.size(); i++) {
            robotArray[i] = robot.get(i);
        }
        Arrays.sort(robotArray);

        long result = 0;
        int factoryIndex = 0, robotIndex = robotArray.length - 1;

        while (factoryIndex < f.length && robotIndex >= 0 && f[factoryIndex][1] > 0) {
            long distance = Math.abs(robotArray[robotIndex] - f[factoryIndex][0]);
            if (robotArray[robotIndex] < f[factoryIndex][0]) {
                distance = -distance;
            }
            result += distance;

            int robotsRepaired = Math.min(f[factoryIndex][1], robotIndex + 1);
            for (int i = 0; i < robotsRepaired; i++) {
                robotIndex--;
            }
            f[factoryIndex][1] -= robotsRepaired;
        }

        return result;
    }
}

