public class Solution {
    public int minGroups(int[][] intervals) {
        // Sort the intervals by their start value
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));

        int max = 1; // Initialize maximum group count to 1
        int end = intervals[0][1]; // Initialize end of current group

        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] > end) { // If new interval does not intersect with previous one
                max++; // Increase maximum group count
                end = Math.max(end, intervals[i][0]); // Update end of current group to be the maximum of its current value and the start of the new interval.
            } else if (intervals[i][0] <= end && intervals[i][1] >= end) {
                // Do not update the end of the current group
            } else {
                max++;
                end = intervals[i][1];
            }
        }

        return max; // Return minimum number of groups needed
    }
}

