public class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;

        // Apply operations
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] *= 2;
                nums[i + 1] = 0;
            }
        }

        // Shift zeros to the end of array
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                int temp = nums[j];
                nums[j] = nums[i];
                nums[i] = temp;
                j++;
            }
        }

        // Fill zeros at the end of array
        for (int i = j; i < n; i++) {
            nums[i] = 0;
        }

        return nums;
    }
