public class Solution {
    public int[][] findMinMax(TreeNode root, int[] queries) {
        TreeSet<Integer> set = new TreeSet<>();
        inOrder(root, set);

        int n = queries.length;
        int[][] answer = new int[n][2];

        for (int i = 0; i < n; i++) {
            int query = queries[i];

            Integer lower = set.lower(query);
            if (lower == null) {
                answer[i][0] = -1;
            } else {
                answer[i][0] = lower;
            }

            Integer higher = set.higher(query);
            if (higher == null) {
                answer[i][1] = -1;
            } else {
                answer[i][1] = higher;
            }
        }

        return answer;
    }

    private void inOrder(TreeNode node, TreeSet<Integer> set) {
        if (node != null) {
            inOrder(node.left, set);
            set.add(node.val);
            inOrder(node.right, set);
        }
    }
}

