public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;

        // Initialize an array to keep track of minimum length found so far for each starting index.
        int[] minLengths = new int[n];

        for (int i = 0; i < n; i++) {
            int maxOr = 0, windowStart = i;

            for (int j = i; j < n; j++) {
                maxOr |= nums[j];

                while (maxOr != 0 && windowStart <= j) {
                    if ((maxOr & nums[windowStart]) == maxOr) {
                        minLengths[i] = Math.min(minLengths[i], j - i + 1);
                        break;
                    }

                    maxOr ^= nums[windowStart++];
                }
            }
        }

        return minLengths;
    }
}

