import java.util.*;

public class Solution {
    private Map<String, TrieNode> trie = new HashMap<>();

    public int[] sumPrefixScores(String[] words) {
        int n = words.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            String word = words[i];
            TrieNode node = buildTrie(word);
            ans[i] = count(node, word);
        }
        return ans;
    }

    private TrieNode buildTrie(String word) {
        if (!trie.containsKey(word)) {
            trie.put(word, new TrieNode());
        }
        return trie.get(word);
    }

    private int count(TrieNode node, String word) {
        if (node == null) return 0;
        Map<String, Integer> memo = new HashMap<>();
        return count(node, word, memo);
    }

    private int count(TrieNode node, String word, Map<String, Integer> memo) {
        if (word.isEmpty()) return 1; // base case: empty string
        String prefix = word.substring(0, 1); // get the first character of the word
        if (!memo.containsKey(prefix)) {
            TrieNode child = node.children.get(prefix);
            if (child != null) {
                memo.put(prefix, count(child, word.substring(1), memo)); // pass only remaining characters here
            } else {
                memo.put(prefix, 0);
            }
        }
        return memo.get(prefix);
    }

    private static class TrieNode {
        Map<String, TrieNode> children = new HashMap<>();
    }
}

