import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        PriorityQueue<Worker> left = new PriorityQueue<>((a,b) -> a.cost == b.cost ? Integer.compare(a.index, b.index) : Integer.compare(a.cost, b.cost));
        PriorityQueue<Worker> right = new PriorityQueue<>((a,b) -> a.cost == b.cost ? Integer.compare(a.index, b.index) : Integer.compare(a.cost, b.cost));

        for (int i = 0; i < candidates && i < costs.length; i++) {
            left.offer(new Worker(i, costs[i]));
        }
        for (int i = costs.length - 1; i >= costs.length - candidates && i >= 0; i--) {
            right.offer(new Worker(i, costs[i]));
        }

        long totalCost = 0;
        int count = 0;

        while (!left.isEmpty() || !right.isEmpty()) {
            if (count == k) break;
            if (!left.isEmpty() && (!right.isEmpty() ? left.peek().cost <= right.peek().cost : true)) {
                Worker worker = left.poll();
                costs[worker.index] = Integer.MIN_VALUE; // mark as chosen
                totalCost += worker.cost;
                count++;
            } else {
                Worker worker = right.poll();
                costs[worker.index] = Integer.MIN_VALUE; // mark as chosen
                totalCost += worker.cost;
                count++;
            }
        }

        return totalCost;
    }

    public static class Worker {
        int index;
        int cost;

        public Worker(int index, int cost) {
            this.index = index;
            this.cost = cost;
        }
    }
}

