public class Solution {
    public int destroyTargets(int[] nums, int space) {
        Map<Integer, Integer> countMap = new HashMap<>();

        // Count occurrences of each number in the array
        for (int num : nums) {
            countMap.put(num % space, countMap.getOrDefault(num % space, 0) + 1);
        }

        int maxCount = 0;
        int minSeed = Integer.MAX_VALUE;

        // Find the minimum seed that has the maximum count
        for (int num : nums) {
            if (countMap.get(num % space) > maxCount) {
                maxCount = countMap.get(num % space);
                minSeed = Math.min(minSeed, num);
            } else if (countMap.get(num % space) == maxCount && num < minSeed) {
                minSeed = num;
            }
        }

        return minSeed;
    }
}

