public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            int currAnd = nums[i]; // Reset currAnd to the current element
            int prevAnd = 0; // Initialize prevAnd to 0
            int j = i + 1;
            while (j < nums.length && (prevAnd & nums[j]) == prevAnd) {
                maxLen = Math.max(maxLen, j - i);
