public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        Map<Integer, List<Integer>> graph = new HashMap<>();

        // Build adjacency list representation of the graph
        for (int[] edge : edges) {
            if (!graph.containsKey(edge[0])) {
                graph.put(edge[0], new ArrayList<>());
            }
            if (!graph.containsKey(edge[1])) {
                graph.put(edge[1], new ArrayList<>());
            }
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        long maxSum = 0;

        // Iterate over each node in the graph
        for (int node : graph.keySet()) {
            PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

            // Add values of neighbors to priority queue
            for (int neighbor : graph.get(node)) {
                pq.offer(nodeValues[neighbor]);
            }

            long sum = 0;
            int count = 0;

            // Iterate over the k largest values in the priority queue
            while (!pq.isEmpty() && count < maxNumberOfEdges) {
                sum += pq.poll();
                count++;
            }

            // Update maximum star sum if necessary
            maxSum = Math.max(maxSum, sum);
        }

        return (int)maxSum;
    }
}

