public class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null) return 0;

        Map<Integer, List<Integer>> levelMap = new HashMap<>();
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();

        queue.offer(root);
        levelMap.put(0, new ArrayList<>(Arrays.asList(root.val)));

        int operations = 0;
        int currentLevel = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> currentLevelValues = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null) {
                    queue.offer(node.left);
                    levelMap.computeIfAbsent(currentLevel + 1, k -> new ArrayList<>()).add(node.left.val);
                    currentLevelValues.add(node.left.val);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                    levelMap.computeIfAbsent(currentLevel + 1, k -> new ArrayList<>()).add(node.right.val);
                    currentLevelValues.add(node.right.val);
                }
            }

            Collections.sort(currentLevelValues);

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (!levelMap.get(currentLevel).equals(Arrays.asList(node.val))) {
                    operations++;
                }
                levelMap.computeIfAbsent(currentLevel + 1, k -> new ArrayList<>()).remove((Integer) node.val);
            }

            currentLevel++;

        }

        return operations;
    }
}

