public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;

        // Initialize variables to store the minimum cost and the current maximum jump length.
        int minCost = Integer.MAX_VALUE, maxJumpLength = 0;

        for (int i = 1; i < n - 1; i++) {
