import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        List<Integer> result = new ArrayList<>();

        // Check if there are at least 2k elements in the array
        if (nums.length < 2 * k + 1) return result;

        boolean[] increasing = new boolean[nums.length];
        boolean[] decreasing = new boolean[nums.length];

        // Initialize the first k elements as true for both arrays
        for (int i = 0; i < k; i++) {
            increasing[i] = true;
            decreasing[i] = true;
        }

        // Check if each element is in non-increasing order with its previous k elements
        for (int i = k; i < nums.length - k; i++) {
            if (!increasing[i - 1] && nums[i - 1] <= nums[i]) increasing[i] = true;
            else increasing[i] = false;
        }

        // Check if each element is in non-decreasing order with its next k elements
        for (int i = k; i < nums.length - k; i++) {
            if (!decreasing[i + 1] && i < nums.length - k - 1 && nums[i] <= nums[i + 1]) decreasing[i] = true;
            else decreasing[i] = false;
        }

        // Find the good indices and add them to the result list
        for (int i = k; i < nums.length - k; i++) {
            if (increasing[i] && decreasing[i]) result.add(i);
        }

        return result;
    }
}

