import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        dfs(graph, 0, -1, parent);

        long[][] dp = new long[n][2];

        for (int i = 0; i < n; i++) {
            if (parent[i] == -1) {
                dp[i][0] = amount[i];
                dp[i][1] = 0;
            } else {
                int p = parent[i];
                // Calculate dp[i][0] and dp[i][1] considering both Alice and Bob paying half the price or receiving half the reward.
                dp[i][0] = Math.max(dp[i][0], (amount[i] > 0) ? amount[i] / 2 + dp[p][1] : -Math.abs(amount[i]) / 2 + dp[p][0]);
                dp[i][1] = Math.max(dp[i][1], (amount[i] < 0) ? -amount[i] / 2 + dp[p][0] : amount[i] / 2 + dp[p][1]);
            }
        }

        long maxProfit = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == -1) {
                // Calculate the maximum net income based on the optimal path
                int leafNode = i;
                while (leafNode != 0 && parent[leafNode] != -1) {
                    leafNode = parent[leafNode];
                }

                long profit = 0;
                while (i != leafNode) {
                    if (parent[i] == leafNode) {
                        // Alice and Bob have reached a node simultaneously, so they share the reward.
                        profit += Math.max(dp[parent[i]][0], dp[parent[i]][1]);
                        i = parent[i];
                    } else {
                        profit -= Math.abs(Math.max(dp[parent[i]][0], dp[parent[i]][1]));
                        i = parent[i];
                    }
                }

                maxProfit = Math.max(maxProfit, profit);
            }
        }

        return (int)maxProfit;
    }

    private void dfs(List<List<Integer>> graph, int node, int parent, int[] parentArr) {
        for (int child : graph.get(node)) {
            if (child != parent) {
                parentArr[child] = node;
                dfs(graph, child, node, parentArr);
            }
        }
    }
}

