public class Solution {
    public int countTime(String time) {
        int hour = 0, minute = 0;

        // Check if there is a '?' in the hour position
        if (time.charAt(0) == '?') {
            for (int h1 = 0; h1 < 10; h1++) {
                for (int h2 = 0; h2 < 10; h2++) {
                    String t = time.replace("?", String.valueOf(h1) + String.valueOf(h2));

                    if (isValid(t)) {
                        hour++;

                        minute += countMinute(t);
                    }
                }
            }
        } else {
            // If there is no '?' in the hour position, we can directly call countMinute
            return countMinute(time);
        }

        return hour * 60 + minute;
    }

    private boolean isValid(String s) {
        int h = Integer.parseInt(s.substring(0, 2));
        int m = Integer.parseInt(s.substring(3, 5));

        if (h < 0 || h > 23 || m < 0 || m > 59) return false;

        String[] parts = s.split(":");
        for (String part : parts) {
            if (!part.matches("\\d+")) return false;
        }

        return true;
    }

    private int countMinute(String time) {
        int count = 0;

        // Iterate over all possible hours with one digit
        for (int h = 0; h < 10; h++) {
            String hourStr = String.format("%d", h);

            // Replace the '?' in the input string with the current hour
            String t = time.replace("?", hourStr.charAt(0) + "");

            if (isValid(t)) {
                // If the hour is valid, iterate over all possible minutes
                for (int m = 0; m < 60; m++) {
                    String minuteStr = String.format("%02d", m);

                    // Replace the '?' in the input string with the current minute
                    t = time.replace("?", minuteStr.charAt(1) + "");

                    if (isValid(t)) {
                        count++;
                    }
                }
            }
        }

        return count;
    }
}

