public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();

        // Initialize dp array with default value of false
        boolean[][] dp = new boolean[n][n];

        // Initialize diagonal elements as true (single character is always a palindrome)
        for(int i=0; i<n; i++) {
            dp[i][i] = true;
        }

        // Fill the upper triangular part of the 2D array
        int maxLen = Math.min(k, n);
        for(int len=k; len<=maxLen && len <= n; len++) { 
            for(int i=0; i+len-1<n; i++) {
                int j = i + len - 1;

                // If the substring is a palindrome, mark it as true
                if (s.charAt(i) == s.charAt(j)) {
                    dp[i][j] = (i+1 <= j-1 && dp[i+1][j-1]);
                }
            }
        }

        // Count the number of non-overlapping palindromic substrings
        int count = 0;
        for(int i=0; i<n; i++) {
            if (dp[i][i+k-1]) { 
                count++;
            }
        }

        return count;
    }
}

