public class Solution {
    private static final int MOD = (int) 1e9 + 7;
    private static final Set<Character> PRIME_DIGITS = new HashSet<>(Arrays.asList('2', '3', '5', '7'));

    public int beautifulPartitions(String s, int k, int minLength) {
        long[] dp = new long[s.length() + 1];
        dp[0] = 1;
        for (int i = 1; i <= s.length(); i++) {
            if (i >= minLength) {
                char c = s.charAt(i - 1);
                if (!PRIME_DIGITS.contains(c)) {
                    long prevSum = 0;
                    for (int j = Math.max(0, i - minLength + 1); j < i; j++) {
                        prevSum += dp[j];
                    }
                    dp[i] = prevSum % MOD;
                } else if (PRIME_DIGITS.contains(s.charAt(i-1))) { // Corrected condition
                    long sum = 0;
                    for (int j = Math.max(0, i - minLength + 1); j < i; j++) {
                        sum += dp[j];
                    }
                    dp[i] = sum % MOD;
                }
            }
        }
        long result = 0;
        for (int i = s.length(); i >= k * minLength; i--) {
            result += dp[i];
        }
        return (int) (result % MOD);
    }
}

