public class Solution {
    public long dividePlayers(int[] skill) {
        HashMap<Integer, Integer> map = new HashMap<>();

        // Count frequency of each skill
        for (int s : skill) {
            map.put(s, map.getOrDefault(s, 0) + 1);
        }

        int n = skill.length;
        long sumSkill = Arrays.stream(skill).sum();

        if ((n / 2) * 2 != n || sumSkill % (n / 2) != 0) {
            return -1;
        }

        long target = sumSkill / (n / 2);

        long chemistrySum = 0;

        for (int s : skill) {
            Integer count = map.get(s);

            if (count > 0 && s * 2 == target) {
                // Create a team
                chemistrySum += (long)s * s;

                // Update counts
                int newCount = count - 1;
                map.put(s, newCount);
                map.put((int)(target - s), (int)((map.getOrDefault(target - s, 0) + 1)));
            }
        }

        return chemistrySum;
    }
}

