public class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();

        // Calculate prefix sum array
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + (customers.charAt(i) == 'Y' ? 1 : -1);
        }

        // Initialize variables to track minimum penalty and best closing time
        int minPenalty = Integer.MAX_VALUE;
        int bestClosingTime = -1;

        // Iterate over the array to find the minimum penalty
        for (int i = 0; i <= n; i++) {
            int customersCount = prefixSum[i];

            // Calculate penalty for current closing time
            int penalty = 0;
            for (int j = 0; j <= n; j++) {
                int openHours = Math.max(i, j);
                int closeHours = Math.min(i, j);
                int noCustomersOpen = Math.max(0, openHours - customersCount);
                int customersClose = Math.max(0, closeHours - (customers.length() - customersCount));
                penalty += noCustomersOpen * 1 + customersClose * 2;
            }

            // Update minimum penalty and best closing time if necessary
            if (penalty < minPenalty) {
                minPenalty = penalty;
                bestClosingTime = i;
            }
        }

        return bestClosingTime;
    }
}

