public class Solution {
    public int distinctAverages(int[] nums) {
        Set<Double> averages = new HashSet<>();

        while (nums.length > 3) { // Changed condition to check for at least three elements left
            double min = Math.min(nums[0], nums[nums.length - 1]);
            double max = Math.max(nums[0], nums[nums.length - 1]);

            int minIndex = 0;
            int maxIndex = nums.length - 1;

            while (minIndex < maxIndex) {
                if (nums[minIndex] == min) {
                    break;
                }
                minIndex++;
            }

            while (maxIndex > minIndex) {
                if (nums[maxIndex] == max) {
                    break;
                }
                maxIndex--;
            }

            // Remove the minimum and maximum numbers from the array
            for (int i = minIndex; i < maxIndex; i++) {
                nums[i] = nums[minIndex + 1];
            }

            averages.add((min + max) / 2.0);
        }

        if (nums.length == 2) { // Handle the case when there are only two elements left
            averages.add((nums[0] + nums[1]) / 2.0);
        } else if (nums.length == 3) {
            double sum = nums[0] + nums[1] + nums[2];
            averages.add(sum / 3.0);
        }

        return averages.size();
    }
}

