public class Solution {
    public int minimizeArrayValue(int[] nums) {
        long max = 0;
        long minMax = Long.MAX_VALUE; // Initialize with a large value

        for (int i = 0; i < nums.length; i++) {
            if (i == 0) {
                max = nums[i];
            } else if (max > nums[i]) {
                // Update minMax whenever we find a new maximum value, considering the possibility of decreasing the previous element
                long newMax = Math.max(max - (nums[i] - nums[i-1]), nums[i]);
                minMax = Math.min(minMax, newMax);
                // Decrease the current element by increasing its previous element
                nums[i - 1] += max - nums[i];
            }
            max = Math.max(max, nums[i]);
        }

        return (int) minMax;
    }
}

