public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;

        // Create a UnionFind data structure to keep track of connected components in the tree.
        UnionFind uf = new UnionFind(n);

        // Create a map where each key is a value from the vals array and its corresponding value is a list of indices of nodes with that value.
        Map<Integer, List<Integer>> map = new HashMap<>();

        for (int i = 0; i < n; i++) {
            map.putIfAbsent(vals[i], new ArrayList<>());
            map.get(vals[i]).add(i);
        }

        int count = 0;

        // Iterate over the edges and union nodes in the UnionFind data structure.
        for (int[] edge : edges) {
            int u = uf.find(edge[0]);
            int v = uf.find(edge[1]);

            if (vals[u] <= vals[v]) {
                uf.union(u, v);
            } else {
                uf.union(v, u);
            }
        }

        // Iterate over the sorted vals array and for each value, count the number of distinct good paths.
        Arrays.sort(vals);
        for (int i = 0; i < n; i++) {
            List<Integer> list = map.get(vals[i]);
            int size = list.size();

            // Count all pairs of nodes
            for (int j = 0; j < size; j++) {
                for (int k = j + 1; k < size; k++) {
                    int rootU = uf.find(list.get(j));
                    int rootV = uf.find(list.get(k));

                    // Check if the current pair of nodes forms a good path.
                    boolean isGoodPath = true;
                    for (int l = j; l <= k; l++) {
                        if (vals[list.get(l)] > vals[list.get(k)]) {
                            isGoodPath = false;
                            break;
                        }
                    }

                    if (isGoodPath) { 
                        count += 1;
                    }
                }
            }
        }

        return count;
    }

    class UnionFind {
        private int[] parent;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = -1;
            }
        }

        public int find(int x) {
            if (parent[x] < 0) return x;
            parent[x] = find(parent[x]);
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                if (parent[rootX] > parent[rootY]) {
                    int temp = rootX;
                    rootX = rootY;
                    rootY = temp;
                }
                parent[rootX] += parent[rootY];
                parent[rootY] = rootX;
            }
        }

        public boolean connected(int x, int y) {
            return find(x) == find(y);
        }
    }
}

