public class Solution {
    public int magnificentSets(int n, int[][] edges) {
        UnionFind uf = new UnionFind(n);

        for (int[] edge : edges) {
            uf.union(edge[0], edge[1]);
        }

        Set<Integer> groups = new HashSet<>();
        for (int i = 0; i < n; i++) {
            groups.add(uf.find(i));
        }

        int maxGroups = groups.size();

        // Check if it's possible to group the nodes with the given conditions
        boolean isPossibleToGroup = true;
        for (int[] edge : edges) {
            if (Math.abs(uf.find(edge[0]) - uf.find(edge[1])) != 1) {
                isPossibleToGroup = false;
                break;
            }
        }

        // Check if the graph is connected
        boolean isConnected = true;
        for (int i = 1; i < n; i++) {
            if (!uf.find(i).equals(uf.find(0))) {
                isConnected = false;
                break;
            }
        }

        return isConnected && isPossibleToGroup ? Math.max(maxGroups, 2) : -1;
    }

    class UnionFind {
        int[] parent;
        int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
}

