public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        Deque<Integer> stack = new ArrayDeque<>();
        int n = nums.length;
        int[] result = new int[n];

        // First pass: find first greater element for each number
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[i] > nums[stack.peekLast()]) {
                result[stack.pollLast()] = -1;
            }
            stack.offerLast(i);
        }

        // Second pass: find second greater element for each number
        Deque<Integer> firstGreaterStack = new ArrayDeque<>();
        Arrays.fill(result, -1);  // Reset the result array

        for (int i = n - 1; i >= 0; i--) {
            while (!firstGreaterStack.isEmpty() && nums[i] > nums[firstGreaterStack.peekLast()]) {
                int j = firstGreaterStack.pollLast();

                if (result[j] == -1) {  
                    // If first greater element is not found, set second greater element to current number
                    result[j] = -1;  // Set to -1 instead of nums[i]
                } else {
                    // Continue searching for the second greater element
                    stack.pollLast();  // Remove j from the stack because we've already found its second greater element
                }
            }

            while (!stack.isEmpty() && nums[stack.peekLast()] > nums[i]) {
                int j = stack.pollLast();

                if (result[j] == -1) {  
                    // If first greater element is not found, set second greater element to current number
                    result[j] = -1;  // Set to -1 instead of nums[i]
                }
            }

            firstGreaterStack.offerLast(i);
        }

        return result;
    }
}

