public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        for (int i = 0; i < n; i++) {
            pq.offer(new int[] {i, Integer.MAX_VALUE});
        }

        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            map.put(i, 0);
        }

        PriorityQueue<int[]> delayedMeetings = new PriorityQueue<>((a, b) -> a[1] - b[1]);

        int current = 0;
        while (!pq.isEmpty() || !delayedMeetings.isEmpty()) {
            if (current < meetings.length && meetings[current][0] <= pq.peek()[1]) {
                int start = meetings[current][0];
                int end = meetings[current][1];
                current++;

                int room = pq.poll()[0];
                map.put(room, map.getOrDefault(room, 0) + 1);
                pq.offer(new int[] {room, Integer.MAX_VALUE});
                pq.offer(new int[] {end, Integer.MAX_VALUE});
            } else if (!delayedMeetings.isEmpty()) {
                int[] meeting = delayedMeetings.peek();
                int room = pq.poll()[0];

                map.put(room, map.getOrDefault(room, 0) + 1);
                pq.offer(new int[] {room, Integer.MAX_VALUE});
                pq.offer(new int[] {meeting[1] - (pq.peek()[1] - pq.poll()[1]), Integer.MAX_VALUE});
            } else {
                int room = pq.poll()[0];
                pq.offer(new int[] {room, Integer.MAX_VALUE});
                pq.offer(new int[] {Integer.MAX_VALUE, Integer.MAX_VALUE});
            }

            if (!delayedMeetings.isEmpty() && delayedMeetings.peek()[1] <= pq.peek()[1]) {
                delayedMeetings.poll();
                pq.offer(delayedMeetings.poll());
            } else if (current < meetings.length) {
                int start = meetings[current][0];
                int end = meetings[current][1];
                current++;

                delayedMeetings.offer(new int[] {start, Integer.MAX_VALUE});
                delayedMeetings.offer(new int[] {end, Integer.MAX_VALUE});
            }
        }

        int maxCount = 0;
        int result = -1;
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                result = entry.getKey();
            } else if (entry.getValue() == maxCount && entry.getKey() < result) {
                result = entry.getKey();
            }
        }

        return result;
    }
}

