public class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long res = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > maxK || nums[i] < minK) continue;

            int left = i - 1;
            while (left >= 0 && nums[left] <= minK) {
                left--;
            }
            int right = i + 1;
            while (right < nums.length && nums[right] <= maxK) {
                right++;
            }

            // Count subarrays with both minimum and maximum values within the current window
            int minCount = 0;
            int maxCount = 0;

            for (int j = left; j <= i; j++) {
                if (nums[j] == minK) {
                    minCount++;
                }
            }

            for (int k = right - 1; k >= i; k--) {
                if (nums[k] == maxK) {
                    maxCount++;
                }
            }

            res += minCount * maxCount;
        }
        return res;
    }
}

