public class Solution {
    public boolean makeEqual(String word) {
        Map<Character, Integer> frequency = new HashMap<>();

        // Count the frequency of each character in the string
        for (char c : word.toCharArray()) {
            frequency.put(c, frequency.getOrDefault(c, 0) + 1);
        }

        int n = word.length();
        int totalFrequency = 0;

        // Calculate the total frequency of all characters
        for (int freq : frequency.values()) {
            totalFrequency += freq;
        }

        if (totalFrequency % (n - 1) != 0) {
            return false; // If we can't remove one character to make frequencies equal, return false
        }

        int targetFrequency = totalFrequency / (n - 1);

        for (int freq : frequency.values()) {
            if (freq > targetFrequency && freq % targetFrequency != 0) {
                return false; // If any character's frequency is not a multiple of the target frequency, return false
            }
        }

        return true;
    }
}

