public class Solution {
    public String[] splitMessage(String message, int limit) {
        StringBuilder sb = new StringBuilder();
        List<String> result = new ArrayList<>();

        while (message.length() > 0) {
            if (sb.length() + 5 > limit) {
                String part = message.substring(0, Math.min(limit - sb.length(), message.length()));
                result.add(sb.toString().substring(0, sb.length() - 2));
                if (part.length() > 0) {
                    int suffixLength = "<" + (result.size() + 1) + "/" + message.length();
                    result.add(part + suffixLength);
                }
                sb = new StringBuilder();
            } else {
                sb.append("<1/");
                sb.append(message.length());
                message = message.substring(1);
            }
        }

        if (sb.length() > 0) {
            String lastPart = sb.toString();
            int suffixLength = "<" + result.size() + "/" + message.length();
            if (lastPart.length() + suffixLength <= limit) {
                lastPart += suffixLength;
            } else {
                lastPart = lastPart.substring(0, limit - suffixLength.length());
                lastPart += suffixLength;
            }
            result.add(lastPart);
        } else {
            List<String> list = new ArrayList<>();
            for (String s : result) {
                int index = s.indexOf("<");
                if (index != -1) {
                    list.add(s.substring(0, index));
                }
            }
            return list.toArray(new String[list.size()]);
        }

        return result.toArray(new String[result.size()]);
    }
}

