import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        int count = 0;

        for (int num : nums) {
            if (num == k) {
                count++;
            } else {
                int lcm = getLcm(num, k);
                if (lcm == k) {
                    count++;
                }

                if (!map.containsKey(lcm)) {
                    map.put(lcm, 1);
                } else {
                    map.put(lcm, map.get(lcm) + 1);
                }
            }
        }

        for (int num : nums) {
            int temp = k;
            for (int i = 2; i <= Math.sqrt(num); i++) {
                if (num % i == 0) {
                    while (temp % i == 0) {
                        temp /= i;
                    }

                    if (!map.containsKey(temp)) {
                        map.put(temp, 1);
                    } else {
                        map.put(temp, map.get(temp) + 1);
                    }
                }
            }

            if (num != k && temp == 1) {
                count += map.get(k);
            }
        }

        return count;
    }

    private int getLcm(int a, int b) {
        return (a * b) / gcd(a, b);
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }
}

