public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int countPalindromes(String s) {
        if(s.length() == 0){
            return 1;
        }

        int n = s.length();

        long[] dp = new long[n];
        dp[0] = 1;

        for (int i = 1; i < n; i++) {
            char c = s.charAt(i);

            // Calculate the count of palindromic subsequences ending at index i
            // and having a length of 2 or more.
            long count = 0;
            for (int j = 0; j <= i - 1; j++) {
                if (c == s.charAt(j)) {
                    count += dp[j];
                }
            }

            dp[i] = count + 1;
        }

        long ans = 0;
        for (long d : dp) {
            ans += d * (d - 1) / 2;
            ans %= MOD;
        }

        return (int) ans;
    }
}

