public class Solution {
    private int introvertsCount;
    private int extrovertsCount;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.introvertsCount = introvertsCount;
        this.extrovertsCount = extrovertsCount;
        return dp(m, n, 0, 0, new Integer[m][n][1 << (introvertsCount + extrovertsCount)]);
    }

    private int dp(int m, int n, int i, int j, Integer[][][] memo) {
        if (i == introvertsCount && j == extrovertsCount) return memo[i][j][(introvertsCount + extrovertsCount) - (i + j)]; // Base case: stop recursion when target numbers are reached

        if (memo[i][j][(introvertsCount + extrovertsCount) - (i + j)] != null) return memo[i][j][(introvertsCount + extrovertsCount) - (i + j)];

        int max = Integer.MIN_VALUE;

        for (int k = i; k <= introvertsCount && k * 2 <= m * n - (j + extrovertsCount); k++) {
            for (int l = j; l <= extrovertsCount && (k + l) * 2 <= m * n - (i + introvertsCount); l++) {
                int happiness = dp(m, n, k, l, memo);
                if (i < k) happiness += (k - i) * 120;
                else happiness -= (i - k) * 30;

                if (j < l) happiness += (l - j) * 40;
                else happiness -= (j - l) * 20;

                max = Math.max(max, happiness);
            }
        }

        memo[i][j][(introvertsCount + extrovertsCount) - (i + j)] = max;
        return max;
    }
}

