import java.util.PriorityQueue;
import java.util.Arrays;

public class Solution {
    public int minimumDeviation(int[] nums) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> a - b);

        int minVal = Integer.MAX_VALUE;
        for (int num : nums) {
            if (num % 2 == 0) {
                maxHeap.offer(num);
                minVal = Math.min(minVal, num);
            } else {
                maxHeap.offer(num * 2);
                minVal = Math.min(minVal, num * 2);
            }
        }

        int deviation = Integer.MAX_VALUE;
        while (true) {
            int top = maxHeap.peek();
            if (top % 2 == 0) {
                deviation = Math.min(deviation, top - minVal);
                maxHeap.poll();
                maxHeap.offer(top / 2);
            } else {
                // Update minVal with the actual minimum value that can be obtained from the current top element
                minVal = Math.min(minVal, top);
                deviation = Math.min(deviation, top - minVal);
                maxHeap.poll();
                maxHeap.offer(top * 2); // Multiply by 2 to make it even
            }
            if (maxHeap.isEmpty()) {
                break;
            }
        }

        return deviation;
    }
}

