import java.util.*;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        boolean[] visited = new boolean[portsCount];

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (int i = 0; i < boxes.length; i++) {
            if (boxes[i][1] <= maxWeight && i + 1 <= maxBoxes) {
                pq.offer(new int[]{boxes[i][0], i});
            }
        }

        int trips = 0;
        while (!pq.isEmpty()) {
            List<int[]> currentTrip = new ArrayList<>();
            int port = pq.poll()[0];

            if (visited[port]) continue;

            visited[port] = true; // declare visited here
            currentTrip.add(new int[]{port, -1});

            while (!pq.isEmpty() && pq.peek()[0] == port) {
                int[] box = pq.poll();
                currentTrip.add(box);
                boxes[box[1]][1] += 100; // mark as delivered
            }

            if (currentTrip.size() > maxBoxes || currentTrip.stream().mapToInt(a -> a[1]).sum() > maxWeight) {
                trips++;
                for (int[] box : currentTrip) {
                    pq.offer(box);
                }
                continue;
            }

            while (!pq.isEmpty()) {
                int[] box = pq.poll();
                if (box[0] != port) break;
                boxes[box[1]][1] += 100; // mark as delivered
            }

            trips++;
        }

        return trips + Arrays.stream(visited).filter(x -> !x).count(); // use stream API to count unvisited ports
    }
}

