import java.util.Arrays;
import java.util.List;

public class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        List<Boolean> result = new ArrayList<>();

        for (int i = 0; i < l.length; i++) {
            int subArray[] = Arrays.copyOfRange(nums, l[i], r[i] + 1);

            if (subArray.length <= 2) {
                result.add(true);
                continue;
            }

            java.util.Arrays.sort(subArray);

            boolean isArithmeticSequence = true;
            for (int j = 0; j < subArray.length - 2; j++) {
                if ((subArray[j + 1] - subArray[j]) != (subArray[subArray.length - 1] - subArray[subArray.length - 2])) {
                    isArithmeticSequence = false;
                    break;
                }
            }

            result.add(isArithmeticSequence);
        }

        return result;
    }
}

