import java.util.Arrays;

public class Solution {
    public String getSmallestString(int n, int k) {
        StringBuilder sb = new StringBuilder();

        // Calculate remaining value after assigning 'a' to all characters except last one
        int remainingValue = Math.max(0, k - n);

        for (int i = 1; i < n; i++) {
            char c;
            if (remainingValue >= 25) {
                c = 'z';
                remainingValue -= 25;
            } else {
                c = (char) ('a' + Math.min(remainingValue, 25));
                remainingValue -= Math.min(remainingValue, 25);
            }
            sb.append(c);
        }

        // If there is still value left, assign it to the last character
        if (remainingValue > 0) {
            c = 'a';
            sb.setCharAt(n - 1, c);
        } else {
            sb.append('a');
        }

        return sb.toString();
    }
}

