import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long minEquity(int[] nums, int k) {
        Arrays.sort(nums);
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }

        if (map.size() < k) return -1;

        long[] dp = new long[k];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;

        for (int num : nums) {
            Map<Integer, Integer> tempMap = new HashMap<>(map);
            int index = k - 1;
            while (index >= 0 && dp[index] == Long.MAX_VALUE / 2) index--;

            if (tempMap.get(num) > 0) {
                for (int i = index; i >= 0; i--) {
                    long minVal = Math.min(dp[i], tempMap.getOrDefault(num, 0));
                    int maxVal = Math.max(i + 1 == k ? num : dp[i + 1], num);

                    if (minVal != 0 && maxVal - minVal < dp[i]) {
                        // Explicitly cast one of the operands to long
                        dp[i] = (long)maxVal - minVal;
                        tempMap.put(num, tempMap.get(num) - 1);
                    }
                }
            }
        }

        long result = Long.MAX_VALUE / 2;
        for (long val : dp) {
            if (val != Long.MAX_VALUE / 2) result = Math.min(result, val);
        }

        return result;
    }
}

package referenz;


public class Solution {
    public boolean checkPalindromeFormation(String a, String b) {
        int n = a.length();

        // Check for all possible splits of the strings
        for (int i = 0; i < n; i++) {
            String prefixA = a.substring(0, i);
            String suffixB = b.substring(i);

            if (isPalindrome(prefixA + suffixB)) return true;

            String prefixB = b.substring(0, i);
            String suffixA = a.substring(i);

            // Check both ways of splitting
            if (isPalindrome(prefixB + suffixA) || isPalindrome(suffixA + prefixB)) return true;
        }

        return false;
    }

    private boolean isPalindrome(String s) {
        int left = 0;
        int right = s.length() - 1;

        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) return false;
            left++;
            right--;
        }

        return true;
    }
}

