// #Medium #Array #Hash_Table #Sliding_Window #2022_04_13_Time_5_ms_(99.82%)_Space_53.3_MB_(92.02%)
public class Solution {
    public int maximumUniqueSubarray(int[] nums) {
        int n = nums.length;
        int left = 0, right = 0;
        int maxSum = Integer.MIN_VALUE;
        boolean[] seen = new boolean[10001];

        while (right < n) {
            if (!seen[nums[right]]) {
                seen[nums[right]] = true;
                int sum = nums[right];
                while (left < right) { // Change made here
                    maxSum = Math.max(maxSum, sum);
                    sum += nums[++right];
                    if (seen[nums[right]]) break;
                }
            } else {
                left++; // Reset left to its previous value before the duplicate was encountered.
                seen[nums[left - 1]] = false;
            }
        }

        return maxSum;
    }
}

