import java.util.Arrays;

public class Solution {
    public double trimMean(int[] arr) {
        Arrays.sort(arr);

        int n = arr.length;
        int removeCount = (int)(n * 0.05); // Remove 5% of elements

        // Create two separate arrays to store removed elements
        int[] smallestRemoved = new int[removeCount];
        int[] largestRemoved = new int[removeCount];

        // Remove the smallest 5%
        for (int i = 0; i < removeCount; i++) {
            smallestRemoved[i] = arr[i];
        }

        // Remove the largest 5%
        for (int i = n - removeCount; i < n; i++) {
            largestRemoved[i - (n - removeCount)] = arr[i];
        }

        // Create a new array with remaining elements
        int[] remainingArr = Arrays.copyOfRange(arr, removeCount, n - removeCount);

        int sum = 0;
        for (int num : remainingArr) {
            sum += num;
        }

        return (double)sum / (n - 2 * removeCount);
    }
}

