import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean canFormArray(int[] arr, int[][] pieces) {
        Map<Integer, Integer> map = new HashMap<>();

        // Populate the map with the first element of each piece as key and its index in pieces array
        for (int i = 0; i < pieces.length; i++) {
            map.put(pieces[i][0], i);
        }

        int j = 0;
        while (j < arr.length) {
            boolean found = false;

            // Check if the current element in arr is present as a key in the map
            for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
                if (arr[j] == entry.getKey()) {
                    int[] piece = pieces[entry.getValue()];

                    // If it's found, check if the remaining elements match with the corresponding piece
                    if (j + piece.length <= arr.length && isMatch(arr, j, piece)) {
                        j += piece.length;
                        map.remove(entry.getKey());
                        found = true;
                        break;
                    }
                }
            }

            // If no matching piece is found for the current element, return false
            if (!found) {
                return false;
            }
        }

        // If all elements in arr are matched with pieces array, return true
        return map.isEmpty();
    }

    private boolean isMatch(int[] arr, int start, int[] piece) {
        for (int i = 0; i < piece.length; i++) {
            if (arr[start + i] != piece[i]) {
                return false;
            }
        }
        return true;
    }
}

