import java.util.*;

public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        if (destination[0] < 0 || destination[1] < 0) {
            throw new IllegalArgumentException("Destination coordinates cannot be negative.");
        }

        if (k <= 0) {
            throw new IllegalArgumentException("k must be a positive integer.");
        }

        int row = destination[0];
        int col = destination[1];

        char[] sb = new char[row + col + 2]; // Initialize with enough capacity
        int index = 0;
        while (row > 0 || col > 0) {
            if (col < row) {
                for (int i = 0; i < row - col; i++) {
                    sb[index++] = 'H';
                }
                sb[index++] = 'V';
                row--;
            } else {
                int count = col - row;
                long combinations = 1;
                for (int i = row + 1; i <= col; i++) {
                    combinations *= i;
                }
                if (k <= combinations) {
                    for (int i = 0; i < count; i++) {
                        sb[index++] = 'H';
                        col--; // Decrement only col here
                    }
                    sb[index++] = 'V';
                    row++;
                } else {
                    k -= combinations;
                }
            }
        }

        return new String(sb, 0, index);
    }
}

package referenz;

public class Solution {
    public int countSubstrings(String s, String t) {
        int m = s.length();
        int n = t.length();

        // Create a 2D array to store the count of substrings that differ by exactly one character
        int[][] dp = new int[m + 1][n + 1];

        for (int i = 0; i <= m; i++) {
            dp[i][0] = 0;
        }
        for (int j = 0; j <= n; j++) {
            dp[0][j] = 0;
        }

        // Fill in the rest of the 2D array
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + 1;
                }
            }
        }

        // Calculate the final count
        int count = 0;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (dp[i][j] == 2) {
                    count++;
                }
            }
        }

        return count;
    }
}

