import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxOperations(int[] nums, int k) {
        Arrays.sort(nums);
        Map<Integer, Integer> map = new HashMap<>();

        int left = 0, right = nums.length - 1;
        int operations = 0;

        while (left < right) {
            if (nums[left] + nums[right] == k) {
                int countLeft = map.getOrDefault(nums[left], 0);
                int countRight = map.getOrDefault(nums[right], 0);

                if (countLeft > 0 && countRight > 0) { 
                    operations++;
                    map.put(nums[left], countLeft - 1);
                    map.put(nums[right], countRight - 1); // Decrement the right number's count as well
                } else {
                    if (countLeft > 0) { 
                        operations++;
                        map.put(nums[left], countLeft + 1);
                    } else { 
                        operations++;
                        map.put(nums[right], countRight + 1);
                    }
                }

                left++;
                right--;
            } else if (nums[left] + nums[right] < k) {
                left++;
            } else {
                right--;
            }
        }

        return operations;
    }
}

