import java.util.*;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        if (edges == null || edges.length != n - 1) {
            throw new IllegalArgumentException("Invalid input: edges");
        }

        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            if (edge[0] < 1 || edge[0] > n || edge[1] < 1 || edge[1] > n) {
                throw new IllegalArgumentException("Invalid edge: " + Arrays.toString(edge));
            }
            graph[edge[0] - 1].add(edge[1] - 1);
            graph[edge[1] - 1].add(edge[0] - 1);
        }

        int[] res = new int[n - 1];
        Arrays.fill(res, 0);

        for (int i = 0; i < n; i++) {
            boolean[] visited = new boolean[n + 1];
            Queue<Integer> q = new LinkedList<>();
            q.offer(i);
            visited[i] = true;
            int diameter = getDiameter(graph, i, visited);

            if (diameter != -1) { // Check for the special case where diameter is -1
                res[diameter - 1]++;
            }
        }

        return res;
    }

    private int getDiameter(List<Integer>[] graph, int node, boolean[] visited) {
        Queue<Integer> q = new LinkedList<>();
        q.offer(node);
        visited[node] = true;

        int diameter = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            for (int j = 0; j < size; j++) {
                int node1 = q.poll();
                diameter++;
                if (graph[node1].isEmpty()) { // If the node has no neighbors, return -1
                    return -1;
                }
                for (int neighbor : graph[node1]) {
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        q.offer(neighbor);
                    }
                }
            }
        }

        return diameter; // Return the correct diameter value
    }
}

package referenz;


import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        Map<Integer, Integer> map = new HashMap<>();
        Map<Integer, List<int[]>> graph = new HashMap<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = matrix[i][j];
                if (!map.containsKey(val)) {
                    map.put(val, map.size() + 1);
                }

                graph.computeIfAbsent(map.get(val), k -> new ArrayList<>()).add(new int[] {i, j});
            }
        }

        int[][] ans = new int[m][n];
        Arrays.fill(ans[0], -1);

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);

        for (int val : map.keySet()) {
            int rank = map.get(val);
            List<int[]> list = graph.get(rank);

            if (!list.isEmpty()) {
                pq.offer(new int[] {rank, m * n});
            }
        }

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int rank = cur[0];
            int size = cur[1];

            for (int i = 0; i < size; i++) {
                int[] pos = graph.get(rank).get(i);
                ans[pos[0]][pos[1]] = rank;

                if (i + 1 < size) {
                    pq.offer(new int[] {rank, size - i - 1});
                }
            }

            updateNeighbors(ans, matrix, cur[0]);
        }

        return ans;
    }

    private void updateNeighbors(int[][] ans, int[][] matrix, int rank) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                if (row[j] == matrix[rank][rank]) {
                    ans[rank][j] = rank;
                }
            }
        }

        for (int i = 0; i < matrix.length; i++) {
            int val = matrix[i][rank];
            if (val != matrix[rank][rank]) {
                ans[i][rank] = map.get(val);
            }
        }
    }

    private Map<Integer, Integer> map;
}

