import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int numWays(String[] words, String target) {
        Map<Character, Integer>[] map = new HashMap[26];

        // Initialize the map array with empty HashMaps
        for (int i = 0; i < 26; i++) {
            map[i] = new HashMap<>();
        }

        // Populate the map array with character frequencies from words
        for (String word : words) {
            for (int i = 0; i < word.length(); i++) {
                char c = word.charAt(i);
                int index = c - 'a';
                map[index].put(c, map[index].getOrDefault(c, 0) + 1);
            }
        }

        long[][] dp = new long[target.length()][26];

        for (int j = 0; j < 26; j++) {
            if (map[j].containsKey(target.charAt(0))) {
                dp[0][j] = map[j].get(target.charAt(0));
            }
        }

        for (int i = 1; i < target.length(); i++) {
            char c = target.charAt(i);
            int index = c - 'a';

            if (c == target.charAt(i-1)) {
                // Calculate the new value based on previous values
                for (int j = 0; j < 26; j++) {
                    dp[i][j] += dp[i-1][j];
                }
            } else {
                long ways = map[index].getOrDefault(c, 0);

                if (ways > 0) {
                    // Calculate the new value based on previous values
                    for (int j = 0; j < 26; j++) {
                        dp[i][index] += dp[i-1][j];
                    }
                }
            }
        }

        long result = 0;
        for (int i = 0; i < 26; i++) {
            if (map[i].containsKey(target.charAt(target.length()-1))) {
                // Add up only the values where the corresponding character is present
                result += dp[target.length()-1][i];
            }
        }

        return (int)(result % 1000000007);
    }
}

