import java.util.Arrays;

public class Solution {
    public int[] getSumAbsoluteDifferences(int[] nums) {
        int n = nums.length;

        // Calculate prefix sum array
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        System.out.println("Prefix Sum Array: " + Arrays.toString(prefix));

        int[] result = new int[n];

        // Calculate the absolute difference and store in result array
        for (int i = 0; i < n; i++) {
            long sumLeft = prefix[i]; // Sum of elements to the left of index i
            long sumRight = prefix[n] - prefix[i + 1]; // Sum of elements to the right of index i

            System.out.println("i: " + i + ", sumLeft: " + sumLeft + ", sumRight: " + sumRight);

            result[i] = (int) ((sumLeft * (i + 1)) + (sumRight * (n - i)));
        }

        return result;
    }
}

