import leetcode.ListNode;

public class Solution {
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // Find the node before the start of the section to be removed
        ListNode prevStart = getPrev(list1, a - 1);

        // Find the node after the end of the section to be removed
        ListNode nextEnd = getNext(list1, b + 1);

        // Remove the section from list1 and insert list2 in between
        prevStart.next = list2;
        while (list2.next != null) {
            list2 = list2.next;
        }
        list2.next = nextEnd;

        return list1;
    }

    private ListNode getPrev(ListNode head, int index) {
        if (index < 0) {
            return null;
        }

        ListNode current = head;
        while (--index >= 0 && current != null) {
            current = current.next;
        }

        return current;
    }

    private ListNode getNext(ListNode head, int index) {
        if (index <= 0) {
            return head;
        }

        ListNode current = head;
        while (current.next != null && --index > 0) {
            current = current.next;
        }

        return current.next;
    }
}

