import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int maxResult(int[] nums, int k) {
        Deque<Integer> deque = new ArrayDeque<>();
        int n = nums.length;

        // Initialize dp array with -1 to handle edge cases
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = Integer.MIN_VALUE;
        }

        // Initialize the first element
        dp[0] = nums[0];
        deque.offerLast(dp[0]);

        System.out.println("Initial dp array: " + java.util.Arrays.toString(dp));

        for (int i = 1; i < n; i++) {
            while (!deque.isEmpty() && deque.peekFirst() > dp[i]) {
                deque.pollFirst();
            }

            if (i - k >= 0) {
                int minIndex = Math.min(i - k, n - 1);
                dp[i] = Math.max(dp[minIndex], dp[i]);
            } else {
                // If we're at the first index, only consider the current value of dp[0]
                dp[i] = nums[0];
            }

            deque.offerLast(dp[i]);
        }

        System.out.println("Final dp array: " + java.util.Arrays.toString(dp));

        return dp[n - 1];
    }
}

