import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minDeletions(String s) {
        Map<Character, Integer> charFrequency = new HashMap<>();

        // Count frequency of each character in string s
        for (char c : s.toCharArray()) {
            charFrequency.put(c, charFrequency.getOrDefault(c, 0) + 1);
        }

        int deletions = 0;

        // Sort the map by value (frequency)
        Map<Integer, Character> sortedCharFrequency = new HashMap<>();
        for (Map.Entry<Character, Integer> entry : charFrequency.entrySet()) {
            sortedCharFrequency.put(entry.getValue(), entry.getKey());
        }

        // Iterate over the sorted map and count deletions
        int prevFreq = -1;
        for (int freq : sortedCharFrequency.keySet()) {
            if (freq < prevFreq) {
                deletions += 1; 
            } else {
                int count = 0;
                for (Character c : sortedCharFrequency.keySet()) {
                    if (sortedCharFrequency.get(c).equals(freq)) {
                        count++;
                    }
                }
                if (count > 1) {
                    deletions += count - 1; // Increment deletions by the number of characters with the same frequency minus one
                }
                prevFreq = freq;
            }
        }

        return deletions;
    }
}

