public class Solution {
    public String getSmallestString(String s, int a, int b) {
        char[] chars = s.toCharArray();

        // Generate all possible strings by adding 'a' to odd indices
        for (int i = 0; i < chars.length; i++) {
            if ((i & 1) == 1) { // Check if index is odd
                int num = Integer.parseInt(String.valueOf(chars[i])) + a;
                char[] newChars = chars.clone();
                newChars[i] = (char)(num % 10 + '0');
                for(int j=i+1;j<chars.length;j++){
                    if((j&1)==1){
                        newChars[j]=(char)((Integer.parseInt(String.valueOf(newChars[j]))+a)%10+'0');
                    }
                }
                String str=new String(newChars);
                if(str.compareTo(s)<0){
                    return str;
                }
            }
        }

        // Generate all possible strings by rotating to the right by 'b' positions
        for (int i = 1; i <= b && i < s.length(); i++) {
            char[] newChars = chars.clone();
            for (int j = s.length() - 1; j >= i; j--) {
                newChars[j] = newChars[j - i];
            }
            String str=new String(newChars);
            if(str.compareTo(s)<0){
                return str;
            }
        }

        // If no smaller string is found, return the original string
        return s;
    }
