import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        if (points == null || points.isEmpty()) return 0;

        int n = points.size();
        double[] angles = new double[n];
        int maxCount = 0;
        int sameLocationCount = 0;

        for (int i = 0; i < n; i++) {
            List<Integer> point = points.get(i);
            if (point.get(0).equals(location.get(0)) && point.get(1).equals(location.get(1))) {
                angles[i] = sameLocationCount++;
                continue;
            }

            double angleRad = Math.atan2(point.get(1) - location.get(1), point.get(0) - location.get(0));
            if (angleRad < 0) {
                angles[i] = Math.toDegrees(angleRad + angle);
            } else {
                angles[i] = Math.toDegrees(angleRad - angle / 2);
            }
        }

        List<Double> anglesList = Arrays.stream(angles).boxed().collect(Collectors.toList());
        Collections.sort(anglesList);

        int left = 0;
        for (int right = 0; right < n; right++) {
            while (left < right && angles[right] - angles[left] > angle) {
                left++;
            }
            maxCount = Math.max(maxCount, right - left + 1);
        }

        return maxCount + sameLocationCount;
    }
}

