public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];

        if (k == 0) {
            for (int i = 0; i < n; i++) {
                result[i] = 0;
            }
            return result;
        }

        int sum = 0;
        if (k > 0) {
            for (int i = k; i < Math.min(n, n + k); i++) {
                sum += code[i % n];
            }
            for (int i = 0; i < Math.min(n, n + k); i++) {
                result[i] = sum;
                if (i >= Math.min(n, n + k) - 1) { 
                    sum -= code[i % n]; 
                }
            }
        } else if (k < 0) {
            for (int i = 0; i < Math.abs(k); i++) {
                sum += code[n - i - 1];
            }
            for (int i = Math.abs(k); i < n; i++) {
                result[i] = sum;
                if (i >= Math.max(0, Math.abs(k) - 1)) { 
                    sum -= code[n - (i + 1) % n]; 
                }
            }
        }

        return result;
    }
}

