public class Solution {
    public int concatenatedBinary(int n) {
        long ans = 0;
        long mod = (long)Math.pow(10, 9) + 7;
        int len = 1;

        for (int i = 1; i <= n; i++) {
            // Check if the binary representation of i has more bits than the previous one
            if (Integer.toBinaryString(i).length() >= len) {
                len = Integer.toBinaryString(i).length();
            }

            // Correctly concatenate the binary string using bitwise operations
            ans = ((ans << len) + i) % mod;
        }

        return (int)(ans % mod);
    }
}

