import java.util.*;

public class Solution {
    public boolean closeStrings(String word1, String word2) {
        Set<Character> set1 = new HashSet<>();
        Set<Character> set2 = new HashSet<>();

        for (char c : word1.toCharArray()) {
            set1.add(c);
        }
        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        if (set1.size() != set2.size()) return false;

        Map<Character, Integer> map1 = new HashMap<>();
        Map<Character, Integer> map2 = new HashMap<>();

        for (char c : word1.toCharArray()) {
            map1.put(c, map1.getOrDefault(c, 0) + 1);
        }
        for (char c : word2.toCharArray()) {
            map2.put(c, map2.getOrDefault(c, 0) + 1);
        }

        // Check if both maps have the same keys
        if (!map1.keySet().equals(map2.keySet())) return false;

        // Check if we can transform one string into another
        for (char c : map1.keySet()) {
            int count1 = map1.get(c);
            int count2 = map2.get(c);

            // If the counts are different, check if we can swap characters to make them equal
            if (count1 != count2) {
                // We should allow for cases where one string has more occurrences of a character than the other.
                // So, we only need to return false if the difference between the counts is greater than 1.
                if (Math.abs(count1 - count2) > 1) {
                    return false;
                }
            }
        }

        // Check if there are any characters in map1 that are not present in map2
        for (char c : map1.keySet()) {
            int count = map1.get(c);
            if (count != 0 && !map2.containsKey(c)) return false;
        }

        return true;
    }
}

