import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        // calculate longest increasing subsequence
        List<Integer> lis = new ArrayList<>();
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if (lis.isEmpty() || nums[i] > lis.get(lis.size() - 1)) {
                lis.add(nums[i]);
            } else {
                int index = Collections.binarySearch(lis, nums[i]);
                if (index < 0) {
                    index = ~index;
                }
                lis.set(index, nums[i]);
            }
        }

        // calculate longest decreasing subsequence
        List<Integer> lds = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            if (lds.isEmpty() || nums[i] > lds.get(lds.size() - 1)) {
                lds.add(nums[i]);
            } else {
                int index = Collections.binarySearch(lds, nums[i]);
                if (index < 0) {
                    index = ~index;
                }
                lds.set(index, nums[i]);
            }
        }

        // calculate minimum number of elements to remove
        int minRemovals = n;
        for (int i = 1; i < n - 1 && i < lis.size() && n - 1 - i < lds.size(); i++) {
            if (lis.get(i) > lds.get(n - 1 - i)) { // Check if the current element is a peak in both subsequences
                boolean isPeak = true;
                for (int j = i + 1; j <= n - 1 - i && j < lis.size() && n - 1 - j < lds.size(); j++) {
                    if ((lis.get(i) > lis.get(j)) || (lds.get(n - 1 - i) > lds.get(n - 1 - j))) { // Corrected comparison
                        isPeak = false;
                        break;
                    }
                }

                // If it's a peak, update minRemovals
                if (isPeak) {
                    minRemovals = Math.min(minRemovals, n - lis.size() - lds.size() + 2);
                }
            }
        }

        return minRemovals;
    }
}

