import java.util.*;

public class Solution {
    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;

        // Create a distance matrix and initialize it with infinity
        int[][] dist = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }

        // The effort to reach the starting point is 0
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        pq.offer(new int[] {0, 0, 0});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();

            // If the current cell is the destination, return its effort
            if (curr[0] == rows - 1 && curr[1] == cols - 1) {
                return curr[2];
            }

            // Explore all four directions
            for (int[] dir : new int[][] {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
                int x = curr[0] + dir[0];
                int y = curr[1] + dir[1];

                // Check if the new cell is within bounds
                if (x >= 0 && x < rows && y >= 0 && y < cols) {
                    // Calculate the effort to reach the new cell
                    int effort = Math.max(Math.abs(heights[x][y] - heights[curr[0]][curr[1]]), curr[2]);

                    // If a shorter path is found, update the distance and add it to the priority queue
                    if (effort < dist[x][y]) {
                        dist[x][y] = effort;
                        pq.offer(new int[] {x, y, effort});
                    }
                }
            }
        }

        // If there's no path to the destination, return -1
        return -1;
    }
}

