import java.util.Arrays;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int numberOfSets(int n, int k) {
        if (k > n) {
            return 0;
        }

        long[] dp = new long[k + 1];
        Arrays.fill(dp, 0);

        for (int i = 2; i <= Math.min(n, k); i++) {
            if (i % 2 == 0) { 
                dp[i] = (comb(n - i + 1, i / 2) * dp[(i - 2) / 2]) % MOD;
            } else {
                dp[i] = (comb(n - i + 1, (i + 1) / 2) * dp[(i - 1) / 2]) % MOD;
            }
        }

        long ans = 0;
        for (int i = 0; i <= k; i++) {
            ans += dp[k - i];
            ans %= MOD;
        }

        return (int) ans;
    }

    private long comb(int n, int k) {
        if (k > n || k < 0) return 0;
        long numerator = 1;
        for (int i = 1; i <= k; i++) {
            numerator *= n - i + 1;
            // denominator is not needed here
        }
        return numerator % MOD;
    }
}

