public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        Queue<Integer> queue = new LinkedList<>();
        for (int student : students) {
            queue.offer(student);
        }

        int topSandwich = 0;
        while (!queue.isEmpty()) {
            if (topSandwich == sandwiches[0]) {
                if (queue.peek() == topSandwich && queue.size() > 1) {
                    queue.poll();
                    topSandwich = sandwiches[0];
                } else if (queue.peek() == topSandwich && queue.size() == 1) {
                    queue.poll();
                    break;
                }
            } else {
                int temp = queue.poll();
                queue.offer(temp);
                if (queue.peek() == topSandwich) {
                    queue.poll();
                    topSandwich = sandwiches[0];
                }
            }
        }

        // Increment count of unable-to-eat students only when there are no more sandwiches left
        int unableToEatCount = 0;
        while (!queue.isEmpty()) {
            unableToEatCount++;
            queue.poll();
        }

        return unableToEatCount;
    }
}

