public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        long[] dp = new long[n];
        long[] preSum = new long[n + 1];

        // Calculate prefix sum array
        preSum[0] = 0;
        for (int i = 0; i < n; i++) {
