import java.util.*;

public class Solution {
    private int[] parent;
    private int[] rank;

    public boolean[] distanceLimitedPathsExist(int[][] edgeList, int[][] queries) {
        int n = edgeList.length + 1;
        parent = new int[n];
        Arrays.fill(parent, -1);
        rank = new int[n];
        Arrays.fill(rank, 0);

        for (int i = 0; i < edgeList.length; i++) {
            union(edgeList[i][0], edgeList[i][1]);
        }

        boolean[] answer = new boolean[queries.length];

        for (int j = 0; j < queries.length; j++) {
            int p = queries[j][0];
            int q = queries[j][1];
            int limit = queries[j][2];

            if (find(p) == find(q)) {
                answer[j] = true;
                continue;
            }

            for (int[] edge : edgeList) {
                if (edge[2] < limit && edge[0] != p && edge[0] != q && edge[1] != p && edge[1] != q) {
                    union(edge[0], p);
                    union(edge[1], p);
                    if (find(q) == find(p)) {
                        answer[j] = true;
                        break;
                    }
                }
            }

            if (!answer[j]) {
                for (int[] edge : edgeList) {
                    if (edge[2] <= limit && edge[0] != p && edge[0] != q && edge[1] != p && edge[1] != q) {
                        union(edge[0], p);
                        union(edge[1], p);
                        if (find(q) == find(p)) {
                            answer[j] = true;
                            break;
                        }
                    }
                }
            }

        }
        return answer;
    }

    private int find(int num) {
        if (parent[num] < 0) {
            return num;
        } else {
            parent[num] = find(parent[num]);
            return parent[num];
        }
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);

        if (rootA == rootB) {
            return;
        }

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }
    }
}

