import java.util.Arrays;

public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int[] count = new int[n];
        return backtrack(requests, 0, count);
    }

    private int backtrack(int[][] requests, int index, int[] count) {
        if (index == requests.length || isAllZero(count)) {
            return isAllZero(count) ? 1 : 0;
        }

        boolean[] visited = new boolean[requests.length];
        for (int i = 0; i < requests.length; i++) {
            visited[i] = false;
        }
        visited[index] = true;

        int maxRequests = 0;
        for (int j = index + 1; j < requests.length; j++) {
            if (!visited[j]) {
                updateCount(requests, index, j, count);
                int result = backtrack(requests, j, count);
                if (result != 0) {
                    maxRequests = Math.max(maxRequests, result + 1);
                }
                revertCount(requests, index, j, count);
            }
        }

        return maxRequests;
    }

    private boolean isAllZero(int[] count) {
        for (int i : count) {
            if (i != 0) {
                return false;
            }
        }
        return true;
    }

    private void updateCount(int[][] requests, int index, int j, int[] count) {
        count[requests[index][0]]--;
        count[requests[index][1]]++;
    }

    private void revertCount(int[][] requests, int index, int j, int[] count) {
        count[requests[index][0]]++;
        count[requests[index][1]]--;
    }
}

