// #2022_04_23_Time_4_ms_(98.95%)_Space_97.8_MB_(46.33%)
public class Solution {
    public int minOperations(int[] nums, int x) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum == x) return nums.length;

        int maxLen = -1;
        int currentSum = 0;
        for (int i = 0; i < nums.length; i++) {
            currentSum += nums[i];

            // Check if the sum of elements from index 'i' to the end equals totalSum - x
            if (currentSum == totalSum - x) {
                maxLen = Math.max(maxLen, i + 1);
            } else if (currentSum < totalSum - x) {
                int left = i;
                while (left >= 0 && currentSum + nums[left] <= totalSum - x) { // Change the condition to <=
                    currentSum += nums[left--];
                    // Check if the sum of elements from index 'i' to 'left' equals totalSum - x
                    if (currentSum == totalSum - x) {
                        maxLen = Math.max(maxLen, i - left + 1); // Update maxLen with the length of the current subarray
                    }
                }
            }
        }

        return nums.length - maxLen;
    }
}

