// #Medium #String #Dynamic_Programming
public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();
        int[] dp = new int[n + 1];

        // Initialize dp array with zeros.
        for (int i = 0; i <= n; i++) {
            dp[i] = 0;
        }

        // Base case: If the string is empty, no deletions are needed.
        dp[0] = 0;

        int bCount = 0;

        // Iterate over the string from left to right.
        for (int i = 1; i <= n; i++) {
            char c = s.charAt(i - 1);

            if (c == 'b') {
                bCount++;

                // If there are more 'a's than 'b's, we can delete all 'b's and some 'a's.
                if (i > 1) { 
                    dp[i] = Math.min(dp[i - 1], dp[Math.max(0, i - 2)] + bCount);
                } else {
                    dp[i] = bCount; // Handle the case when i is 1
                }
            } else {
                // If the current character is 'a', we don't need to delete any characters.
                dp[i] = Math.min(dp[i - 1], dp[Math.max(0, i - 2)] + bCount);
            }
        }

        return dp[n];
    }
}

