import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        long mod = (long) 1e9 + 7;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        for (int i : inventory) {
            pq.offer(new int[] {i, i});
        }

        long ans = 0;
        while (!pq.isEmpty() && orders > 0) {
            int[] top = pq.poll();
            int value = top[1];
            int count = top[0] - value + 1;

            if (count < orders) {
                ans += ((long) value * (orders - count)) % mod;
                orders -= count;
            } else {
                ans += ((long) value * (orders)) % mod;

                // Update the priority queue by decreasing the count of each ball
                while (!pq.isEmpty()) {
                    int[] ball = pq.poll();
                    if (ball[0] == value) {
                        ball[1]--;
                        if (ball[1] > 0) {
                            pq.offer(ball);
                        }
                    } else {
                        pq.offer(ball);
                    }
                }

                break;
            }
        }

        return (int) (ans % mod);
    }
}

