public class Solution {
    public int maxHeight(int[][] arr) {
        // Create a copy of the input array to avoid modifying it during sorting
        int[][] sortedArr = arr.clone();

        // Sort each cuboid by width, length and height in descending order
        for (int[] cuboid : sortedArr) {
            Arrays.sort(cuboid);
        }

        // Sort the array of cuboids based on their maximum dimension (max(width, length, height)) in descending order
        Arrays.sort(sortedArr, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                int maxA = Math.max(Math.max(a[0], a[1]), a[2]);
                int maxB = Math.max(Math.max(b[0], b[1]), b[2]);
                return Integer.compare(maxB, maxA);
            }
        });

        // Initialize an array to store the maximum height of cuboids
        int[] maxHeights = new int[sortedArr.length];

        // Iterate over each cuboid and calculate its maximum height
        for (int i = 0; i < sortedArr.length; i++) {
            maxHeights[i] = sortedArr[i][2];
            for (int j = 0; j < i; j++) {
                if (sortedArr[j][0] >= sortedArr[i][0] && sortedArr[j][1] >= sortedArr[i][1] && sortedArr[j][2] >= sortedArr[i][2]) {
                    maxHeights[i] = Math.max(maxHeights[i], maxHeights[j]);
                }
            }
        }

        // Return the maximum height of all cuboids
        int maxHeight = 0;
        for (int i : maxHeights) {
            maxHeight = Math.max(maxHeight, i);
        }
        return maxHeight;
    }
}

