import java.util.*;

public class Solution {
    public String reformatNumber(String number) {
        StringBuilder sb = new StringBuilder();

        // Remove all spaces and dashes from the string
        for (char c : number.toCharArray()) {
            if (c != ' ' && c != '-') {
                sb.append(c);
            }
        }

        StringBuilder result = new StringBuilder();

        while (sb.length() > 4) {
            if (sb.length() >= 7) {
                // Two blocks of length 3
                result.append(sb.substring(0, 3)).append("-");
                sb.delete(0, 3);
            } else if (sb.length() >= 4) {
                // One block of length 3 and one block of length 1
                result.append(sb.substring(0, 3)).append("-");
                sb.delete(0, 3);

                if (sb.length() > 0) {
                    result.append(sb.substring(0, 1)).append("-");
                    sb.delete(0, 1);
                }
            } else {
                // One block of length 3 and one block of length 2
                result.append(sb.substring(0, 3)).append("-");
                sb.delete(0, 3);

                if (sb.length() > 0) {
                    result.append(sb.substring(0, 2));
                    sb.delete(0, 2);
                }
            }

            // Handle remaining digits when there are 4 or fewer digits left
            if (sb.length() == 4) {
                result.append(sb.substring(0, 2)).append("-");
                result.append(sb.substring(2));
            } else if (sb.length() == 3) {
                result.append(sb).append("-");
                sb.delete(0, 1);
            }
        }

        // Add the remaining digits to the result
        if (sb.length() > 0) {
            result.append(sb);
        }

        return result.toString();
    }
}

