import java.util.HashSet;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        HashMap<Character, HashSet<Integer>> map = new HashMap<>();

        for (int i = 0; i < stickers.length; i++) {
            char[] chars = stickers[i].toCharArray();
            for (char c : chars) {
                if (!map.containsKey(c)) {
                    map.put(c, new HashSet<>());
                }
                map.get(c).add(i);
            }
        }

        int n = target.length();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);

        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            char c = target.charAt(i - 1);
            if (!map.containsKey(c)) continue;

            HashSet<Integer> set = map.get(c);
            long min = Long.MAX_VALUE;
            for (Integer index : set) {
                int prev = i - 1;
                while (prev >= 0 && target.charAt(prev) == c) {
                    prev--;
                }

                if (prev < 0) continue;

                min = Math.min(min, dp[prev]);
            }

            if (min != Long.MAX_VALUE) {
                dp[i] = Math.min(dp[i], min + 1);
            }
        }

        return dp[n] == Long.MAX_VALUE ? -1 : (int)dp[n];
    }
}

