public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        long[] prefixSums = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSums[i + 1] = prefixSums[i] + nums[i];
        }

        long[][] dp = new long[3][n + 1];
        int[] prevMax = new int[n + 1];

        for (int i = k; i <= n; i++) {
            long maxSum = Long.MIN_VALUE;
            int maxIndex = 0;

            for (int j = i - k; j >= Math.max(0, i - 2 * k); j--) {
                long sum = prefixSums[i] - prefixSums[j];
                if (sum > maxSum && j >= 0) { 
                    maxSum = sum;
                    if (j < 0) { // Add this condition to handle negative indices
                        maxIndex = 0; // Set maxIndex to a valid index when j is negative
                    } else {
                        maxIndex = j;
                    }
                }
            }

            dp[0][i] = maxSum;

            for (int j = 1; j <= 2 && i + k <= n; j++) {
                long sum = prefixSums[i + k] - prefixSums[i];
                if (sum > dp[j - 1][prevMax[i]]) {
                    dp[j][i] = sum;
                    prevMax[i] = maxIndex;
                }
            }

            for (int j = 2; j >= 0 && i + k <= n; j--) {
                if (dp[j][prevMax[i]] > 0) {
                    break;
                }
                prevMax[i]--;
            }
        }

        int[] result = new int[3];
        long maxSum = Long.MIN_VALUE;

        for (int i = n - k + 1; i <= n; i++) {
            if (dp[2][i] > maxSum) {
                maxSum = dp[2][i];
                result[0] = prevMax[i];
                result[1] = prevMax[result[0]];
                result[2] = i;
            }
        }

        return result;
    }
}

