import java.util.LinkedList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;

public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);

        for (int i = 0; i < forest.size(); i++) {
            for (int j = 0; j < forest.get(i).size(); j++) {
                if (forest.get(i).get(j) > 1) {
                    pq.offer(new int[] {i, j, forest.get(i).get(j)});
                }
            }
        }

        int startRow = 0;
        int startCol = 0;
        int steps = 0;

        while (!pq.isEmpty()) {
            int[] tree = pq.poll();
            int endRow = tree[0];
            int endCol = tree[1];

            Queue<int[]> q = new LinkedList<>();
            boolean[][] visited = new boolean[forest.size()][forest.get(0).size()];
            q.offer(new int[] {startRow, startCol});
            visited[startRow][startCol] = true;

            while (!q.isEmpty()) {
                int size = q.size();
                for (int i = 0; i < size; i++) {
                    int[] curr = q.poll();

                    if (curr[0] == endRow && curr[1] == endCol) {
                        steps += bfs(forest, visited, curr);
                        startRow = endRow;
                        startCol = endCol;
                        break;
                    }

                    for (int[] dir : directions) {
                        int newRow = curr[0] + dir[0];
                        int newCol = curr[1] + dir[1];

                        if (newRow >= 0 && newRow < forest.size() && newCol >= 0
                                && newCol < forest.get(0).size()
                                && !visited[newRow][newCol]
                                && forest.get(newRow).get(newCol) != 0) {
                            q.offer(new int[] {newRow, newCol});
                            visited[newRow][newCol] = true;
                        }
                    }
                }
            }

            steps++; // Increment the steps by 1 when polling a tree from the priority queue
        }

        return steps;
    }

    private static final int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    private int bfs(List<List<Integer>> forest, boolean[][] visited, int[] curr) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(curr);
        visited[curr[0]][curr[1]] = true;
        int steps = 0;

        while (!q.isEmpty()) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
                int[] node = q.poll();

                if (forest.get(node[0]).get(node[1]) > 1) {
                    forest.get(node[0]).set(node[1], 1);
                    return steps + 1;
                }

                for (int[] dir : directions) {
                    int newRow = node[0] + dir[0];
                    int newCol = node[1] + dir[1];

                    if (newRow >= 0 && newRow < forest.size() && newCol >= 0
                            && newCol < forest.get(0).size()
                            && !visited[newRow][newCol]) {
                        q.offer(new int[] {newRow, newCol});
                        visited[newRow][newCol] = true;
                    }
                }
            }

            steps++;
        }

        return -1; // If no more trees are found
    }
}

