public class Solution {
    public int numDecodings(String s) {
        if (s == null || s.length() == 0) return 0;

        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 1; i <= n; i++) {
            if (s.charAt(i - 1) == '*') {
                dp[i] += dp[i - 1];

                if (i >= 2 && s.substring(i - 2, i).startsWith("1") || s.substring(i - 2, i).equals("*1")) {
                    dp[i] += dp[i - 2];
                }
            } else if (s.charAt(i - 1) == '0') {
