public class Solution {
    public int findKthNumber(int m, int n, int k) {
        long left = 1;
        long right = (long)m * n + 1;

        // Precompute cumulative count of multiples for each row
        long[] cumCount = new long[m + 1];
        for(long i = 1; i <= m; i++){
            long maxMultiple = Math.min(n, (i * n) / i);
            cumCount[i] = cumCount[i - 1] + maxMultiple;
        }

        while(left < right){
            long mid = left + (right - left) / 2;

            // Calculate count using precomputed values
            long count = 0;
            for(long i = 1; i <= m; i++){
                if(i * n >= mid){
                    count += cumCount[(int)i];
                }else{
                    long maxMultiple = Math.min(n, (mid + i - 1) / i);
                    count += maxMultiple;
                }
            }

            if(count < k){
                left = mid + 1;
            }else{
                right = mid;
            }
        }

        return (int)(left - 1); // Change here
    }
}

