public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        // Coordinate compression using TreeSet
        Set<Integer> compressed = new TreeSet<>();
        int index = 0;
        for (int[] position : positions) {
            compressed.add(index++);
        }

        // converted the TreeSet to a List
        List<Integer> list = new ArrayList<>(compressed);
        Collections.reverse(list);

        // Storing the max heights for compressed coordinates
        Map<Integer, Integer> map = new HashMap<>();
        int globalMax = 0;

        // Our answer list
        List<Integer> ans = new ArrayList<>();

        // Global Max
        int maxHeight = 0;
        for (int[] position : positions) {
            int left = position[0];
            int sideLength = position[1];

            // coordinate compression lookup
            int x1 = Collections.binarySearch(list, left);
            if (x1 < 0) {
                x1 = -x1 - 1;
            }
            int x2 = Collections.binarySearch(list, left + sideLength);

            if (x2 < 0) {
                x2 = -x2 - 1;
            }

            // get the current max for the interval between x1 and x2
            int currMax = map.getOrDefault(x1, 0);
            for (int i = x1 + 1; i <= x2; i++) {
                currMax = Math.max(currMax, map.get(i));
            }

            // add the new square on the top
            currMax += sideLength;

            // update the interval with the new value
            for (int i = x1; i <= x2; i++) {
                map.put(i, currMax);
            }

            // Update maxHeight by considering all previously added squares and their heights.
            int maxTempHeight = 0;
            for (int height : map.values()) {
                maxTempHeight = Math.max(maxTempHeight, height);
            }

            if (x2 > x1 && currMax > maxTempHeight) {
                System.out.println("Updating maxTempHeight to " + currMax);
                maxTempHeight = currMax;
            }
            System.out.println("After update: maxTempHeight = " + maxTempHeight);

            // Update global max height
            globalMax = Math.max(globalMax, maxTempHeight);

            // add to answer list
            ans.add(globalMax);
        }
        return ans;
    }
}

