        return set.contains("24");
    }

    private void backtrack(Set<String> set, double sum, double a, double b, double c, double d) {
        if (Math.abs(sum - 24) < 1e-6 && !set.contains("24")) {
            return; // Do not add "24" to the set and do not recurse
        }

        if (sum == 24) {
            set.add(String.valueOf(sum));
            return;
        }

        // Try multiplication and division first
        double temp = sum * a * b;
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum / a * b;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum * a / b;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum / b * a;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        // Try addition and subtraction next
        temp = sum + a * b;
        if (temp > 0 && !set.contains(String.valueOf(temp))) {
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum + a / b;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum + b / a;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        // Try subtraction and division next
        temp = sum - a * b;
        if (temp > 0 && !set.contains(String.valueOf(temp))) {
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum - a / b;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

        temp = sum - b / a;
        if (Math.abs(temp - 24) < 1e-6 && !set.contains("24")) {
            set.add("24");
        }
        if (temp > 0 && !set.contains(String.valueOf(temp))) { 
            backtrack(set, temp, c, d, a, b);
        }

    }
