import java.util.*;

public class Solution {
    public String replaceWords(List<String> dictionary, String sentence) {
        TrieNode root = new TrieNode();
        for (String word : dictionary) {
            insert(root, word);
        }

        StringBuilder result = new StringBuilder();
        String[] words = sentence.split(" ");
        for (String word : words) {
            String replacedWord = getShortestRoot(word, root);
            if (!replacedWord.isEmpty()) {
                result.append(replacedWord).append(" ");
            } else {
                result.append(word).append(" ");
            }
        }

        return result.toString().trim();
    }

    private void insert(TrieNode node, String word) {
        int index = 0;
        for (char c : word.toCharArray()) {
            if (!node.children[c - 'a'].isPresent()) { // Check if character is present in dictionary
                return; // If not, skip this character and move on to the next one
            }
            node = node.children[c - 'a'];
            index++;
        }
        node.isEndOfWord = true;
    }

    private String getShortestRoot(String word, TrieNode root) {
        int index = 0;
        for (char c : word.toCharArray()) {
            if (!root.children[c - 'a'].isPresent()) { // Check if character is present in dictionary
                return "";
            }
            root = root.children[c - 'a'];
            index++;
            if (index == word.length() && root.isEndOfWord) {
                break;
            }
        }

        StringBuilder shortestRoot = new StringBuilder();
        while (!root.isEndOfWord || !shortestRoot.toString().isEmpty()) {
            char c = word.charAt(index);
            shortestRoot.insert(0, (char)(c + 'a'));
            if (index > 1 && root.children[index - 2].isPresent() && root.children[index - 2].isEndOfWord) { // Check for presence of character
                return shortestRoot.toString();
            }
            index--;
            root = root.parent;
        }

        return "";
    }

    private class TrieNode {
        boolean isEndOfWord;
        char charValue;
        TrieNode parent;
        TrieNode[] children;

        public TrieNode() {
            this.isEndOfWord = false;
            this.charValue = '\0';
            this.parent = null;
            this.children = new TrieNode[26];
        }

        public boolean isPresent() { // Method to check if a child node is present at a given index
            return children[c - 'a'] != null;
        }
    }
}

