// #Hard #String #Dynamic_Programming #2022_03_22_Time_24_ms_(76.35%)_Space_42_MB_(87.89%)
public class Solution {
    int[] memo;

    public int strangePrinter(String s) {
        memo = new int[s.length()];
        for (int i : memo)
            i = -1;

        return dfs(s, 0, s.length() - 1);
    }

    private int dfs(String s, int start, int end) {
        if (start >= end) 
            return 0;

        if (memo[start] != -1) 
            return memo[start];

        int min = Integer.MAX_VALUE;
        for (int i = start; i <= end; i++) {
            if (s.charAt(i) == s.charAt(start)) { // Check if the character is the same
                if (i != start) { // If it's not the first occurrence, don't increment the turn count
                    int temp = dfs(s, i + 1, end);
                    if (temp != -1)
                        min = Math.min(min, temp); // No need to increment the turn count when printing the same character
                } else {
                    int temp = dfs(s, i + 1, end);
                    if (temp != -1)
                        min = Math.min(min, temp); // If it's the first occurrence, don't increment the turn count
                }
            } else { // If the character is different, increment the turn count
                int temp = dfs(s, i + 1, end);
                if (temp != -1)
                    min = Math.min(min, temp + 1); // Only increment the turn count when there's a change in character
            }
        }

        memo[start] = (min == Integer.MAX_VALUE ? -1 : min);
        return memo[start];
    }
}

