import java.util.*;

public class Solution {
    private static final int MOD = (int) 1e9 + 7;

    public int kInversePairs(int n, int k) {
        long[][] dp = new long[n + 1][k + 1];

        for (long[] row : dp) Arrays.fill(row, -1);

        return (int) dfs(n, k, dp);
    }

    private long dfs(int n, int k, long[][] dp) {
        if (k > n * (n - 1) / 2) return 0;

        if (k < 0 || k > n * (n - 1) / 2) return 0;

        if (k <= n * (n - 1) / 2 && k < dp.length && dp[n][k] != -1) {
            return dp[n][k];
        }

        long res = 0;

        for (int i = Math.max(0, k - n + 1); i <= n; ++i) {
            int pairs = (n - i) * i / 2;

            if (pairs >= k) {
                res += dfs(i - 1, k - pairs, dp);
                res %= MOD;
            }
        }

        return dp[n][k] = res % MOD;
    }
}

