public class Solution {
    public int minSteps(int n) {
        if (n == 1) return 0;

        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        dp[1] = 0;

        for (int i = 2; i <= n; i++) {
            if (i % 2 == 0) {
                dp[i] = Math.min(dp[i], dp[i / 2] + 1);
            }

            int j = 1;
            while (j * j <= i) {
                if (i % j == 0) {
                    int k = i - j;
                    dp[i] = Math.min(dp[i], dp[j] + dp[k] + 1);
                }
                j++;
            }

            // Check for the case where we can copy all and paste
            if (dp[i - 1] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - 1] + 1);
            }
        }

        return dp[n];
    }
}

