public class Solution {
    public String solveEquation(String equation) {
        int x = 0, y = 0;
        boolean sign = true; // Flag to track the sign of the current number

        StringBuilder sb = new StringBuilder(); // String builder to build numbers

        // Parse the equation from left to right
        for (int i = 0; i < equation.length(); i++) {
            char c = equation.charAt(i);

            if (c == '+' || c == '-') {
                // If we encounter a sign, process the current number and reset the string builder
                if (sb.length() > 0) {
                    int num = Integer.parseInt(sb.toString());

                    if (sign)
                        y += num;
                    else
                        y -= num;

                    sb.setLength(0); // Reset the string builder
                }

                sign = (c == '+'); // Update the sign flag
            } else if (Character.isDigit(c)) {
                // If we encounter a digit, append it to the current number in the string builder
                sb.append(c);
            } else if (c == 'x') {
                int num = sb.length() > 0 ? Integer.parseInt(sb.toString()) : 1;

                if (!sign)
                    num *= -1;

                x += num; // Update the coefficient of 'x'

                sb.setLength(0); // Reset the string builder
            }
        }

        int num = Integer.parseInt(sb.toString()); // Parse the last number

        if (num != 0) {
            // If there is a constant term, check for infinite solutions or no solution
            if (y == 0 && x != 0) { 
                return "No solution";
            } else if (x == y) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        } else {
            // If there is no constant term, the equation has exactly one solution
            return "x=" + (y - x);
        }
    }
}

