import java.util.*;

public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        boolean[][] g = new boolean[n + 1][n + 1];
        int[] parent = new int[n + 1];
        Arrays.fill(parent, -1);

        // Find the first edge that has a duplicate
        Set<int[]> uniqueEdges = new HashSet<>();
        for (int[] edge : edges) {
            uniqueEdges.add(edge);
        }

        boolean hasCycle = false;
        List<int[]> cycleEdges = new ArrayList<>();

        for (int[] edge : edges) {
            if (!uniqueEdges.contains(edge)) continue;

            // Check if the edge causes a cycle
            boolean isCycleEdge = true;
            for (int i = 0; i < n; i++) {
                if (parent[i] == edge[1]) {
                    isCycleEdge = false;
                    break;
                }
            }

            if (isCycleEdge) {
                cycleEdges.add(new int[]{edge[0], edge[1]});
            } else {
                parent[edge[0]] = edge[1];
            }
        }

        // Check all nodes with a duplicate edge
        for (int[] edge : edges) {
            if (!uniqueEdges.contains(edge)) continue;

            // Check if the edge causes a cycle
            boolean isCycleEdge = true;
            for (int i = 0; i < n; i++) {
                if (parent[i] == edge[1]) {
                    isCycleEdge = false;
                    break;
                }
            }

            if (isCycleEdge) {
                // Check all nodes
                for (int i = 1; i <= n; i++) {
                    if (parent[i] != -1) {
                        g[parent[i]][i] = true;
                        boolean[] visited = new boolean[n + 1];
                        if (dfs(g, parent, i, visited)) {
                            hasCycle = true;
                            break;
                        }
                    }
                }

                // If a cycle is detected, return the last edge that caused it
                if (hasCycle) {
                    for (int i = edges.length - 1; i >= 0; i--) {
                        if (!cycleEdges.contains(edges[i])) return edges[i];
                    }
                }
            }
        }

        // If no cycle is detected, return null
        return null;
    }

    private boolean dfs(boolean[][] g, int[] parent, int node, boolean[] visited) {
        if (visited[node]) return true;

        visited[node] = true;
        for (int i = 1; i <= parent.length - 1; i++) {
            if (g[node][i] && parent[i] != -1) {
                if (dfs(g, parent, i, visited)) return true;
            }
        }

        return false;
    }
}

