import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int leastInterval(char[] tasks, int n) {
        Map<Character, Integer> taskCount = new HashMap<>();

        // Count occurrences of each task
        for (char task : tasks) {
            taskCount.put(task, taskCount.getOrDefault(task, 0) + 1);
        }

        // Find the maximum count and the number of tasks with this count
        int maxCount = 0;
        int maxTaskCount = 0;
        for (int count : taskCount.values()) {
            if (count > maxCount) {
                maxCount = count;
                maxTaskCount = 1;
            } else if (count == maxCount) {
                maxTaskCount++;
            }
        }

        // Calculate the least number of units of time
        int idleTime = (maxCount - 1) * (n + 1);
        return Math.max(tasks.length, maxTaskCount + idleTime);
    }
}

