        StringBuilder sb = new StringBuilder(a);

        while (sb.length() < b.length()) {
            sb.append(a);

            if (sb.toString().contains(b)) {
                int count = (sb.length() - a.length()) / a.length();
                if ((sb.length() - a.length()) % a.length() != 0) {
                    count++;
                }
                return count;
            }
        }

