public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        int min = Integer.MAX_VALUE;
        int secondMin = Integer.MAX_VALUE;

        dfs(root, min, secondMin);

        return (secondMin == Integer.MAX_VALUE) ? -1 : secondMin;
    }

    private void dfs(TreeNode node, int min, int secondMin) {
        if (node == null) return;

        if (node.val > min && node.val < secondMin) {
            secondMin = node.val;
        } else if (node.val <= min) {
            min = node.val;
        }

        dfs(node.left, min, secondMin);
        dfs(node.right, min, secondMin);
    }
}

