                        scores.remove(scores.size() - 1);
                    }
                    break;
                default:
                    try {
                        int score = Integer.parseInt(op);
                        scores.add(score);
                    } catch (NumberFormatException e) {}
            }
        }

        int sumOfScores = 0;
        for (int score : scores) {
            sumOfScores += score;
        }

        return sumOfScores;
    }
}

