public class Solution {
    public double knightProbability(int n, int k, int row, int column) {
        // Create a memoization table to store the probabilities of each cell
        double[][][] dp = new double[n + 1][n + 1][k + 1];

        // Initialize the base case where k is 0 and the knight is at the given position
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i >= 0 && i < n && j >= 0 && j < n) {
                    dp[i][j][0] = 1;
                }
            }
        }

        // Calculate the probabilities of each cell for k moves
        for (int i = 0; i < k; i++) {
            for (int r = 0; r <= n; r++) {
                for (int c = 0; c <= n; c++) {
                    if (dp[r][c][i] == 0) continue;
                    int[][] directions = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};
                    for (int[] direction : directions) {
                        int newRow = r + direction[0];
                        int newCol = c + direction[1];

                        // Check if the new position is within the board
                        if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n) {
                            dp[newRow][newCol][i + 1] += dp[r][c][i] / 8;
                        }
                    }
                }
            }
        }

        // Return the probability of the knight remaining on the board after k moves
        return dp[row][column][k];
    }
}

