import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();

        // Count frequency of each number in the array
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        while (!countMap.isEmpty()) {
            boolean foundSubsequence = false;

            // Try to find a subsequence of length 3 or more
            Map<Integer, Integer> newCountMap = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
                int num = entry.getKey();
                int count = entry.getValue();

                if (count >= 2) {
                    // Try to find a subsequence of length 3 or more
                    int nextNum = num + 1;
                    while (newCountMap.containsKey(nextNum)) {
                        newCountMap.put(nextNum, newCountMap.get(nextNum) - 1);
                        nextNum++;
                    }

                    if (!newCountMap.containsKey(nextNum)) {
                        // Found a subsequence of length 3 or more
                        foundSubsequence = true;
                        break;
                    } else {
                        int countNextNum = newCountMap.get(nextNum);
                        newCountMap.put(nextNum, countNextNum - 1);
                        if (countNextNum == 1) {
                            newCountMap.remove(nextNum);
                        }
                    }
                }
            }

            // Update the count map
            countMap = newCountMap;

            // If no subsequence of length 3 or more is found, return false
            if (!foundSubsequence) {
                return false;
            }
        }

        return true;
    }
}

