public class Solution {
    public String predictPartyVictory(String senate) {
        ArrayList<Integer> radiant = new ArrayList<>();
        ArrayList<Integer> dire = new ArrayList<>();

        for (int i = 0; i < senate.length(); i++) {
            if (senate.charAt(i) == 'R') {
                radiant.add(i);
            } else {
                dire.add(i);
            }
        }

        while (!radiant.isEmpty() && !dire.isEmpty()) {
            int rIndex = Collections.min(radiant);
            int dIndex = Collections.min(dire);

            // If a senator from one party bans another senator's right to vote in all following rounds, 
            // then the current round will be the last round
            if (rIndex < dIndex) {
                dire.remove((Integer)dIndex);
            } else {
                radiant.remove((Integer)rIndex);
            }
        }

        return radiant.isEmpty() ? "Dire" : "Radiant";
    }
}

