public class Solution {
    public int findShortestSubArray(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        Map<Integer, Integer> firstIndexMap = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            if (!countMap.containsKey(nums[i])) {
                countMap.put(nums[i], 1);
                firstIndexMap.put(nums[i], i);
            } else {
                int currentCount = countMap.get(nums[i]);
                countMap.put(nums[i], currentCount + 1);

                if (currentCount < countMap.get(nums[i])) {
                    firstIndexMap.put(nums[i], i);
                }
            }
        }

        int maxCount = 0;
        for (int count : countMap.values()) {
            maxCount = Math.max(maxCount, count);
        }

        int minLen = Integer.MAX_VALUE;

        for (Map.Entry<Integer, Integer> entry : firstIndexMap.entrySet()) {
            if (countMap.get(entry.getKey()) == maxCount) {
                int startIndex;
                if (!firstIndexMap.containsKey(nums[0]) || firstIndexMap.get(nums[0]) == 0) {
                    startIndex = 0;
                } else {
                    startIndex = Math.min(firstIndexMap.get(nums[0]), entry.getValue());
                }
                minLen = Math.min(minLen, entry.getValue() - startIndex + 1);
            }
        }

        return minLen;
    }
}

