public class Solution {
    public int triangleNumber(int[] nums) {
        Arrays.sort(nums);
        int count = 0;

        for (int i = 0; i < nums.length - 2; i++) {
            int k = i + 2;

            for (int j = i + 1; j < nums.length - 1; j++) {
                while (k < nums.length && nums[i] + nums[j] > nums[k]) {
                    k++;
                }

                if (k <= nums.length) {
                    count += Math.max(0, k - j - 1);
                }
            }
        }

        return count;
    }
}

