import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int shoppingOffers(int[] price, int[][] specials, int[] needs) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(price, specials, needs, 0, memo);
    }

    private int dfs(int[] price, int[][] specials, int[] needs, int index, Map<String, Integer> memo) {
        String key = needs.toString();
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int totalCost = 0;
        for (int i = 0; i < price.length; i++) {
            totalCost += needs[i] * price[i];
        }

        boolean canUseSpecial = true;
        for (int i = 0; i < specials[index].length - 1; i++) {
            if (specials[index][i] > needs[i]) {
                canUseSpecial = false;
                break;
            }
        }

        int costIfNoOffer = totalCost;

        if (canUseSpecial) {
            for (int i = index; i < specials.length; i++) {
                boolean validOffer = true;
                for (int j = 0; j < price.length; j++) {
                    if (specials[i][j] > needs[j]) {
                        validOffer = false;
                        break;
                    }
                }

                if (!validOffer) continue;

                int[] newNeeds = new int[needs.length];
                System.arraycopy(needs, 0, newNeeds, 0, needs.length);
                for (int j = 0; j < price.length; j++) {
                    newNeeds[j] -= specials[i][j];
                }

                int costIfUseThisOffer = dfs(price, specials, newNeeds, i + 1, memo);

                if (costIfUseThisOffer < costIfNoOffer) {
                    costIfNoOffer = costIfUseThisOffer;
                }
            }
        }

        memo.put(key, Math.min(costIfNoOffer, totalCost - specials[index][specials[index].length - 1]));
        return memo.get(key);
    }
}

