import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maximumSwap(int num) {
        String str = Integer.toString(num);
        int n = str.length();

        // Store the indices of each digit in a map
        Map<Character, Integer> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (!map.containsKey(c)) {
                map.put(c, i);
            }
        }

        // Iterate through the string from right to left
        for (int i = n - 1; i > 0; i--) {
            char c = str.charAt(i);

            // If the current digit is smaller than the previous one, try to swap it with a larger digit on its left
            if (c < str.charAt(i - 1)) {
                char maxChar = '9';
                int tempMaxIndex = n;

                // Find the largest digit that can be swapped with the current digit
                for (int j = i - 1; j >= 0; j--) {
                    char d = str.charAt(j);

                    if (d > c && (maxChar == '9' || d > maxChar)) {
                        maxChar = d;
                        // Update tempMaxIndex correctly to point to the original position
                        tempMaxIndex = map.get(d); 
                        break; 
                    }
                }

                // If a larger digit is found, swap them
                if (tempMaxIndex != n) {
                    char[] arr = str.toCharArray();
                    char temp = arr[i];
                    // Use the original position of maxChar to swap with
                    arr[i] = arr[tempMaxIndex];
                    arr[tempMaxIndex] = temp;

                    return Integer.parseInt(new String(arr));
                }
            }
        }

        // If no swap is needed, just return the original number
        return num;
    }
}

