import java.util.*;

public class Solution {

    public int[] smallestRange(List<List<Integer>> nums) {
        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);

        int n = nums.size();
        for (int i = 0; i < n; i++) {
            minHeap.offer(new int[] {nums.get(i).get(0), i, 0});
        }

        double minDiff = Double.POSITIVE_INFINITY;
        int[] minRange = new int[2];

        while (!minHeap.isEmpty()) {
            int[] top = minHeap.poll();

            if (top[1] < nums.get(top[1]).size() - 1) {
                for (int i = Math.min(top[2] + 1, nums.get(top[1]).size() - 1); i <= nums.get(top[1]).size() - 1; i++) {
                    int nextVal = nums.get(top[1]).get(i);

                    minHeap.offer(new int[] {nextVal, top[1], i});
                }
            } else {
                // If we've reached the end of a list, remove it from the heap
                while (!minHeap.isEmpty() && minHeap.peek()[1] == top[1]) {
                    minHeap.poll();
                }
            }

            if (minDiff > top[0] + top[2] - minHeap.peek()[0]) {
                minDiff = top[0] + top[2] - minHeap.peek()[0];
                minRange[0] = top[0];
                minRange[1] = minHeap.peek()[0];
            }
        }

        return new int[] {minRange[0], minRange[1]};
    }
}

