public class Solution {
    public int[] constructArray(int n, int k) {
        int[] result = new int[n];

        // Fill in the first half of the array with alternating values from the start and end.
        int start = 1;
        int end = n;
        for (int i = 0; i < n - k; i++) {
            if ((i & 1) == 0) { 
                result[i] = start++;
            } else { 
                result[i] = end--;
            }
        }

        // Fill in the second half of the array with values that are k steps apart from each other.
        int index = n - k;
        for (int i = 0; i < (k + 1) / 2; i++) {
            result[index++] = start++;
        }

        return result;
    }
}

