public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each word and store it in a map
        for (String word : words) {
            frequencyMap.put(word, frequencyMap.getOrDefault(word, 0) + 1);
        }

        // Create a list of entries from the map and sort them by frequency and then lexicographically
        List<Map.Entry<String, Integer>> sortedList = new ArrayList<>(frequencyMap.entrySet());
        Collections.sort(sortedList, (o1, o2) -> {
            if (o1.getValue().equals(o2.getValue())) {
                return o1.getKey().compareTo(o2.getKey());
            } else {
                return o2.getValue().compareTo(o1.getValue());
            }
        });

        // Return the k most frequent words
        List<String> result = new ArrayList<>();
        for (int i = 0; i < Math.min(k, sortedList.size()); i++) {
            result.add(sortedList.get(i).getKey());
        }
        return result;
    }
}

