public class Solution {
    public void flatten(TreeNode root) {
        if (root == null) return;

        TreeNode leftmostNode = root;
        while (leftmostNode.left != null) {
            // find the tail of left subtree, tail means the most left leaf
            leftmostNode = leftmostNode.left;
        }

        // stitch the right subtree below the tail
        leftmostNode.right = root.right;
        root.right = root.left;
        root.left = null;

        // find tail of the right subtree
        TreeNode newTail = root.right;
        while (newTail.right != null) {
            newTail = newTail.right;
        }

        // stitch the left subtree below the new tail
        newTail.right = root.left;
    }
}

