public class Solution {
    private Map<TreeNode, Integer> heightMap = new HashMap<>();

    public boolean isBalanced(TreeNode root) {
        return checkHeight(root) != -1;
    }

    private int checkHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }

        if (heightMap.containsKey(node)) {
            return heightMap.get(node);
        }

        int leftHeight = checkHeight(node.left);
        if (leftHeight == -1) {
            heightMap.put(node, -1); // Left subtree is not balanced
            return -1; 
        }

        int rightHeight = checkHeight(node.right);
        if (rightHeight == -1) {
            heightMap.put(node, -1); // Right subtree is not balanced
            return -1;
        }

        if (Math.abs(leftHeight - rightHeight) > 1) {
            heightMap.put(node, -1); // Current node is not balanced
            return -1; 
        }

        heightMap.put(node, Math.max(leftHeight, rightHeight) + 1);
        return Math.max(leftHeight, rightHeight) + 1;
    }
}

