public class Solution {
    public int candy(int[] ratings) {
        int n = ratings.length;
        int[] candies = new int[n];

        // First pass: from left to right
        for (int i = 0; i < n; i++) {
            if (i > 0 && ratings[i] > ratings[i - 1]) {
                candies[i] = candies[i - 1] + 1;
                candies[i - 1] = Math.max(candies[i - 1], candies[i]);
            } else {
                // If the current child's rating is lower than their neighbor on the left,
                // they should still get at least one candy
                if (i == 0 || ratings[i] >= ratings[i - 1]) {
                    candies[i] = 1;
                }
            }
        }

        // Make one pass through the array to ensure that each child gets at least one candy more than their neighbor if they have a higher rating
        for (int i = n - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) {
                candies[i] = Math.max(candies[i], candies[i + 1] + 1);
                candies[i + 1] = Math.max(candies[i + 1], candies[i]);
            }
        }

        int sum = Arrays.stream(candies).sum();
        return sum;
    }
}

