public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        int n = triangle.size();

        // Initialize the last row of dp array with values from the last row of triangle array.
        List<Integer> dp = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            dp.add(triangle.get(n - 1).get(i));
        }

        // Iterate over each row in reverse order, starting from the second last row.
        for (int i = n - 2; i >= 0; i--) {
            // For each element in the current row, add its value to both of its adjacent elements in the dp array.
            for (int j = 0; j <= i; j++) {
                dp.set(j, triangle.get(i).get(j) + Math.min(dp.get(j), dp.get(j + 1)));
            }
        }

        // The minimum path sum is stored at index 0 of the dp array.
        return dp.get(0);
    }
}

