public class Solution {
    public List<Integer> rightSideView(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) return result;

        traverse(root, 0, result);
        return result;
    }

    private List<Integer> traverse(TreeNode node, int level, List<Integer> result) {
        if (node == null) return result; // Return the current result list

        if (level >= result.size()) {
            result.add(node.val);
        }

        List<Integer> rightResult = traverse(node.right, level + 1, new ArrayList<>());
        List<Integer> leftResult = traverse(node.left, level + 1, new ArrayList<>());

        // Combine the results from both sides
        if (level >= result.size()) {
            result.addAll(rightResult);
            result.addAll(leftResult);
        } else {
            result.set(level, node.val); // Update the value at the current level
        }

        return result;
    }
}

