public class Solution {
    public int maxPoints(int[][] points) {
        if (points.length <= 2) return points.length;

        int n = points.length, res = 0;
        for (int i = 0; i < n; i++) {
            int samePoint = 1;
            Map<Double, Integer> map = new HashMap<>();
            for (int j = i + 1; j < n; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    samePoint++;
                } else {
                    double slope;
                    if (points[i][0] - points[j][0] == 0) {
                        slope = Double.POSITIVE_INFINITY; // vertical line
                    } else {
                        slope = (double)(points[i][1] - points[j][1]) / (points[i][0] - points[j][0]);
                    }
                    map.put(slope, map.getOrDefault(slope, 0) + 1);
                }
            }
            if (samePoint > 1) { 
                res = Math.max(res, samePoint);
            } else {
                int maxPointsOnLine = map.values().stream().max(Integer::compare).orElse(0);
                res = Math.max(res, maxPointsOnLine);
            }
        }

        return res;
    }
}

