import java.util.Arrays;

public class Solution {
    public int minCut(String s) {
        int n = s.length();
        boolean[][] isPalindrome = new boolean[n][n];
        int[] dp = new int[n];

        for (int i = 0; i < n; i++) {
            isPalindrome[i][i] = true;
            if (i > 0) {
                isPalindrome[i - 1][i] = s.charAt(i) == s.charAt(i - 1);
            }
        }

        // Fix the ArrayIndexOutOfBoundsException
        for (int i = 0; i < n; i++) {
            for (int length = 2; length <= n - i; length++) {
                int j = i + length - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    isPalindrome[i][j] = true;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (isPalindrome[0][i]) {
                dp[i] = 0;
            } else {
                int minCut = Integer.MAX_VALUE;
                for (int j = 0; j < i; j++) { // Change the loop condition here
                    if (isPalindrome[j + 1][i]) {
                        minCut = Math.min(minCut, dp[j]);
                    }
                }
                dp[i] = minCut + 1;
            }
        }

        int minCuts = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (isPalindrome[0][i]) {
                minCuts = Math.min(minCuts, dp[i]);
            }
        }

        return minCuts;
    }
}

