public class Solution {
    public int rob(int[] nums) {
        if (nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];

        // Initialize dp array to store maximum amount of money that can be robbed up to each house
        int[] dp = new int[nums.length];
        dp[0] = nums[0];
        dp[1] = Math.max(nums[0], nums[1]);

        for (int i = 2; i < nums.length; i++) {
            // For each house, the maximum amount of money that can be robbed is the maximum of two options:
            // 1. Rob this house and skip the previous one: dp[i-2] + nums[i]
            // 2. Don't rob this house and keep the previous option: dp[i-1]
            dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i]);
        }

        return dp[nums.length - 1];
    }
}

