public class Solution {
    public int numDistinct(String s, String t) {
        int m = s.length();
        int n = t.length();

        // Create a 2D array to store the number of distinct subsequences.
        int[][] dp = new int[m + 1][n + 1];

        // Initialize the base case where t is empty. In this case, there's only one way
        // to form an empty string from s, which is by not removing any characters.
        for (int i = 0; i <= m; i++) {
            dp[i][0] = 1;
        }

        // Iterate over both strings.
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {

                // If the current character in s matches the current character in t, we have
                // two options: either include this character in our subsequence or not.
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
                } else {

                    // If the current characters don't match, we can only not include this
                    // character in our subsequence.
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }

        // The number of distinct subsequences is stored in the last cell of the array.
        return dp[m][n];
    }
}

