            ListNode nextTemp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nextTemp;
        }

        // merge two halves
        ListNode firstNode = head, secondNode = prev;
        while (secondNode != null) {
            ListNode nextTemp1 = firstNode.next;
            ListNode nextTemp2 = secondNode.next;

            firstNode.next = secondNode;
            secondNode.next = nextTemp1;

            firstNode = nextTemp1;
            secondNode = nextTemp2;
        }
    }
}

