import java.util.*;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return new ArrayList<>();

        Map<String, List<String>> graph = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        wordSet.remove(beginWord);

        boolean foundEnd = false;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String curWord = queue.poll();

                if (curWord.equals(endWord)) {
                    foundEnd = true;
                    break;
                }

                List<String> neighbors = getNeighbors(curWord, wordSet);
                for (String neighbor : neighbors) {
                    graph.computeIfAbsent(curWord, k -> new ArrayList<>()).add(neighbor);
                    queue.offer(neighbor);
                    wordSet.remove(neighbor);
                }
            }

            if (foundEnd) break;
        }

        if (!foundEnd) return new ArrayList<>();

        List<List<String>> ans = new ArrayList<>();
        dfs(graph, beginWord, endWord, new ArrayList<>(), ans);
        return ans;
    }

    private void dfs(Map<String, List<String>> graph, String curWord, String endWord, List<String> path, List<List<String>> ans) {
        if (curWord.equals(endWord)) {
            ans.add(new ArrayList<>(path));
            return;
        }

        for (String neighbor : graph.get(curWord)) {
            if (!path.contains(neighbor)) {
                path.add(neighbor);
                dfs(graph, neighbor, endWord, path, ans);
                path.remove(path.size() - 1);
            }
        }
    }

    private List<String> getNeighbors(String word, Set<String> wordSet) {
        List<String> neighbors = new ArrayList<>();
        for (int i = 0; i < word.length(); i++) {
            char[] chars = word.toCharArray();
            for (char c = 'a'; c <= 'z'; c++) {
                if (chars[i] == c) continue;
                chars[i] = c;
                String neighbor = new String(chars);
                if (wordSet.contains(neighbor)) neighbors.add(neighbor);
            }
        }
        return neighbors;
    }
}

