    public int[] corpFlightBookings(int[][] bookings, int n) {
        int[] seats = new int[n];

        // Calculate the prefix sum array
        for (int[] booking : bookings) {
            int start = Math.max(0, booking[0] - 1);
            int end = Math.min(n - 1, booking[1]);

            for (int i = start; i <= end; i++) {
                seats[i] += booking[2]; // Increment seat count by the number of seats reserved
