import java.util.Arrays;

public class Solution {
    public int minHeightShelves(int[][] books, int shelfWidth) {
        int n = books.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);

        for (int i = 1; i <= n; i++) {
            int width = 0, height = 0;
            for (int j = i - 1; j >= 0; j--) {
                if (width + books[j][0] <= shelfWidth) {
                    width += books[j][0];
                    height = Math.max(height, books[j][1]);

                    // Case 1: Place all current set of books on one shelf
                    dp[i] = Math.min(dp[i], height);

                    // Case 2: Split the current set of books into multiple shelves
                    if (j > 0) {
                        dp[i] = Math.min(dp[i], dp[j - 1] + height);
                    }
                } else {
                    break;
                }
            }
        }

        return dp[n];
    }
}

