public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;

        // Initialize variables to store the maximum sum with and without deletion
        int maxWithoutDeletion = Integer.MIN_VALUE, maxWithDeletion = Integer.MIN_VALUE;

        // Initialize variables to store the current sum with and without deletion
        int currWithoutDeletion = 0, currWithDeletion = 0;

        for (int i = 0; i < n; i++) {
            // Update the maximum sum without deletion by considering the current element
            maxWithoutDeletion = Math.max(maxWithoutDeletion, currWithoutDeletion += arr[i]);

            // Update the maximum sum with deletion by considering the current element and the previous maximum sum without deletion
            if (i > 0) {
                int maxSubarraySum = getMaxSubarraySum(arr, i - 1);
                maxWithDeletion = Math.max(maxWithDeletion, currWithDeletion + arr[i] - maxSubarraySum);
            } else {
                maxWithDeletion = Math.max(maxWithDeletion, currWithDeletion + arr[0]);
            }

            // Update the current sum with deletion by adding the current element
            currWithDeletion += arr[i];
        }

        return Math.max(maxWithoutDeletion, maxWithDeletion);
    }

    private int getMaxSubarraySum(int[] arr) {
        int n = arr.length;
        int maxSoFar = Integer.MIN_VALUE;
        int maxEndingHere = 0;

        for (int i = 0; i < n; i++) {
            maxEndingHere = Math.max(arr[i], maxEndingHere + arr[i]);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }

        return maxSoFar;
    }
}

