import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int maxDistance(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Find all land cells and store their coordinates in a queue
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    queue.offer(new int[] {i, j});
                    visited[i][j] = true;
                }
            }
        }

        // If there are no land cells or water cells, return -1
        if (queue.isEmpty() || grid[0][0] == 0 || grid[rows-1][cols-1] == 0) {
            return -1;
        }

        int maxDistance = 0;

        // Perform BFS from all land cells simultaneously
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();

                // Explore all four directions (up, down, left, right)
                int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
                for (int[] direction : directions) {
                    int newRow = current[0] + direction[0];
                    int newCol = current[1] + direction[1];

                    // Check if the new position is within grid boundaries and has not been visited before
                    if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && !visited[newRow][newCol]) {
                        // Mark the cell as visited
                        visited[newRow][newCol] = true;

                        // Check if the new position is water
                        if (grid[newRow][newCol] == 0) {
                            // Calculate the Manhattan distance from the current water cell to its nearest land cell
                            int distance = Math.abs(current[0] - newRow) + Math.abs(current[1] - newCol);

                            // Update the maximum distance seen so far for this water cell
                            maxDistance = Math.max(maxDistance, distance);

                            // Add the new position to the queue for further exploration
                            queue.offer(new int[] {newRow, newCol});
                        }
                    }
                }
            }
        }

        return maxDistance;
    }
}

