        boolean isRoot = true;
        for (TreeNode child : new TreeNode[]{parent.left, parent.right}) {
            if (child != null && !child.getValSet(to_delete)) {
                isRoot = false;
            }
        }

        if (!isRoot) {
            if (node.getValSet(to_delete)) {
                if (parent == null) {
