public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        int evenMoves = 0, oddMoves = 0;

        // Check if every even-indexed element is greater than adjacent elements
        for (int i = 1; i < n - 1; i += 2) {
            if (i > 0 && nums[i] <= nums[i - 1]) {
                int diff = Math.max(0, nums[i - 1] - nums[i] + 1);
                evenMoves += diff;
            }
            if (i < n - 1 && nums[i] <= nums[i + 1]) {
                int diff = Math.max(0, nums[i + 1] - nums[i] + 1);
                evenMoves += diff;
            }
        }

        // Check if every odd-indexed element is greater than adjacent elements
        for (int i = 0; i < n - 1; i += 2) {
            if (i > 0 && nums[i] <= nums[i - 1]) {
                int diff = Math.max(0, nums[i - 1] - nums[i] + 1);
                oddMoves += diff;
            }
            if (i < n - 1 && nums[i] <= nums[i + 1]) {
                int diff = Math.max(0, nums[i + 1] - nums[i] + 1);
                oddMoves += diff;
            }
        }

        // Check the last element
        if (n > 0 && nums[0] <= nums[1]) {
            int diff = Math.max(0, nums[1] - nums[0] + 1);
            evenMoves += diff;
        }
        if (n > 1 && nums[n-1] <= nums[n-2]) {
            int diff = Math.max(0, nums[n-2] - nums[n-1] + 1);
            oddMoves += diff;
        }

        return Math.min(evenMoves, oddMoves);
    }
}

