import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        int[] hash = new int[n];

        // calculate prefix sum of frequency of each character
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                hash[i] = 1 << (s.charAt(i) - 'a');
            } else {
                hash[i] = hash[i-1];
                hash[i] |= 1 << (s.charAt(i) - 'a');
            }
        }

        List<Boolean> res = new ArrayList<>();

        for (int[] query : queries) {
            int left = query[0], right = query[1], k = query[2];

            // calculate the frequency of each character in the substring
            int freq = left == 0 ? hash[right] : (hash[right] & (hash[left-1]));

            // count the number of characters that need to be replaced
            int replaceCount = 0;
            while (freq > 0) {
                replaceCount += (freq & 1);
                freq >>= 1;
            }

            res.add(replaceCount <= k);
        }

        return res;
    }
}

