        long middleCount = n - leftCount - rightCount - 1;

        // If one of the subtrees has more than half of the total nodes, return true
        if (leftCount > n / 2 || rightCount > n / 2 || middleCount > n / 2) {
            return true;
        }

        // If none of the above conditions are met, it's not possible to win
        return false;
    }

    private TreeNode findNode(TreeNode root, int x) {
        if (root == null) return null;
        if (root.val == x) return root;
        TreeNode left = findNode(root.left, x);
        if (left != null) return left;
        return findNode(root.right, x);
    }

    private long countNodes(TreeNode node) {
        if (node == null) return 0;
        return countNodes(node.left) + countNodes(node.right) + 1;
    }
}

