import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int mctFromLeafValues(int[] arr) {
        Deque<Integer> stack = new ArrayDeque<>();

        long sum = 0;
        Deque<Integer> maxLeft = new ArrayDeque<>();
        Deque<Integer> maxRight = new ArrayDeque<>();

        for (int num : arr) {
            while (!stack.isEmpty() && num > stack.peekLast()) {
                int min1 = stack.pollLast();
                if (!maxLeft.isEmpty()) {
                    int maxL = maxLeft.pollFirst();
                    sum += Math.max(Math.min(min1, num), maxLeft.peekFirst()) * Math.max(maxL, num);
                } else {
                    sum += Math.max(Math.min(min1, num), maxLeft.peekFirst()) * num;
                }
            }
            stack.offerLast(num);

            if (maxLeft.isEmpty()) {
                maxLeft.offerLast(num);
            } else {
                int maxL = maxLeft.peekFirst();
                if (num > maxL) {
                    maxLeft.offerFirst(num);
                }
            }

            maxRight.offerLast(num);
        }

        while (!stack.isEmpty() && stack.size() > 1) {
            int min1 = stack.pollFirst();
            if (!maxLeft.isEmpty()) {
                int maxL = maxLeft.pollFirst();
                sum += Math.max(Math.min(min1, maxL), maxLeft.peekFirst()) * Math.max(maxL, min1);
            } else {
                sum += Math.max(Math.min(min1, min1), maxLeft.peekFirst()) * min1;
            }
        }

        return (int) sum;
    }
}

