public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        long[] dp = new long[n];
        Arrays.fill(dp, Long.MIN_VALUE / 2);
        dp[0] = piles[0];

        for (int i = 1; i < n; i++) {
            for (int m = 1; m <= 2 * Math.max(i + 1, 1); m++) {
                int j = i - 1;
                long maxStones = Long.MIN_VALUE / 2;
                while (j >= 0 && j - m + 1 >= 0) {
                    maxStones = Math.max(maxStones, piles[j] + dp[Math.max(j - m + 1, 0)]);
                    j--;
                }
                dp[i] = Math.max(dp[i], maxStones);
            }
        }

        return (int) (dp[n - 1] / 2);
    }
}

