import java.util.*;

public class Solution {
    public int[] smallestSufficientTeam(String[] skills, List<List<String>> people) {
        Map<String, Integer> skillMap = new HashMap<>();
        for (int i = 0; i < skills.length; i++) {
            skillMap.put(skills[i], i);
        }

        int n = people.size();
        boolean[][] dp = new boolean[n][1 << skills.length];
        int[] prev = new int[n];
        Arrays.fill(prev, -1);

        for (int i = 0; i < n; i++) {
            for (String skill : people.get(i)) {
                int mask = 1 << skillMap.get(skill);
                if (!dp[i][mask]) {
                    dp[i][mask] = true;
                    prev[i] = i;

                    for (int j = 0; j < i; j++) {
                        if (dp[j][mask ^ (1 << skillMap.get(skill))]) {
                            dp[i][mask] = true;
                            prev[i] = j;
                            break;
                        }
                    }
                }
            }
        }

        int[] res = new int[0];
        for (int i = 0; i < n; i++) {
            if (dp[i][(1 << skills.length) - 1]) {
                List<Integer> list = new ArrayList<>();
                while (i != -1) {
                    list.add(i);
                    i = prev[i];
                }

                Collections.reverse(list);
                res = Arrays.copyOf(res, list.size());
                for (int j = 0; j < list.size(); j++) {
                    res[j] = list.get(j);
                }
            }
        }

        return res;
    }
}

