                            }
                            subExprs.add(result);
                            if (k == chars.length || chars[k] == ')') {
                                break;
                            } else {
                                j = k;
                            }
                        }
                        boolean result2 = false;
                        for (Boolean b : subExprs) {
                            result2 |= b;
                        }
                        stack.add(result2);
                    } else if (chars[i] == 't' || chars[i] == 'f') {
                        stack.add(Boolean.parseBoolean(new String(chars, i, 1)));
                        i++;
                    }
                }
                i++;
            } else if (chars[i] == '!') {
                i++;
                while (i < chars.length && chars[i] != '(') {
                    i++;
                }
                if (!stack.isEmpty()) { // Add this check
                    stack.add(!stack.get(stack.size() - 1));
                } else {
                    stack.add(false); // Return a default value if the stack is empty
                }
            } else if (chars[i] == '&') {
                int j = i + 1;
                if (j < chars.length && chars[j] != ',' && chars[j] != ')') {
                    String subExpr = new String(chars, j, 1);
                    boolean result = parseBoolExpr(subExpr);
                    if (!result) { // Check if the sub-expression has been parsed successfully
                        throw new RuntimeException("Failed to parse sub-expression: " + subExpr);
                    }
                    stack.add(result);
                    i = j + 1;
                }
            } else if (chars[i] == '|') {
                int j = i + 1;
                if (j < chars.length && chars[j] != ',' && chars[j] != ')') {
                    String subExpr = new String(chars, j, 1);
