public class Solution {
    public String lastSubstring(String s) {
        int n = s.length();
        char[] chars = s.toCharArray();

        int maxIndex = 0;
        int maxLength = 1;

        for (int i = 1; i < n; i++) {
            if (i <= maxIndex && chars[i] > chars[maxIndex]) {
                maxIndex = i;
                maxLength = 1;
            } else if (chars[i] == chars[maxIndex]) {
                int j = i + 1;
                while (j < n && chars[j] == chars[i]) { // Fix: Changed <= to <
                    j++;
                }
                if (j - i >= maxLength) { // Fix: Changed > to >=
                    maxIndex = i; // Update maxIndex here
                    maxLength = j - i;
                } else if (j - i == maxLength) {
                    while (maxIndex < i && chars[maxIndex] == chars[i]) {
                        maxIndex++;
                    }
                }
            }
        }

        return s.substring(maxIndex, maxIndex + maxLength);
    }
}

