public class Solution {
    public int longestWPI(int[] hours) {
        int score = 0, maxLen = 0;
        HashMap<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i < hours.length; i++) {
            score += hours[i] > 1 ? 1 : -1;

            if (score > 0) {
                maxLen = Math.max(maxLen, i + 1);
            } else {
                map.put(score, i);
            }
        }

        for (int i = 0; i < hours.length; i++) {
            score += hours[i] > 1 ? 1 : -1;

            if (map.containsKey(score)) {
                int prevIndex = map.get(score);

                // Check all intervals between the current index and the previous occurrence of the same score
                for (int j = i - 1; j >= prevIndex; j--) {
                    maxLen = Math.max(maxLen, i - j + 1);

                    // If we find an interval where the number of tiring days is strictly larger than the number of non-tiring days, update maxLen
                    if (score > 0 && score - (hours[j] > 1 ? 1 : -1) > 0) {
                        maxLen = Math.max(maxLen, i - j + 1);
                        break;
                    }
                }
            } else if (score > 0) {
                maxLen = Math.max(maxLen, i + 1);
            }
        }

        return maxLen;
    }
}

