import java.util.*;

public class Solution {
    public int numPrimeArrangements(int n) {
        boolean[] prime = new boolean[n + 1];
        Arrays.fill(prime, true);
        prime[0] = false;
        prime[1] = false;

        for (int i = 2; i * i <= n; i++) {
            if (prime[i]) {
                for (int j = i * i; j <= n; j += i) {
                    prime[j] = false;
                }
            }
        }

        long p = 1, q = 1;
        int primeCount = 0, nonPrimeCount = 0;

        // Count the number of prime numbers and non-prime numbers
        for (int i = 0; i < n; i++) {
            if (prime[i + 1]) {
                primeCount++;
            } else {
                nonPrimeCount++;
            }
        }

        // Calculate the permutations using combinatorial formulas
        p = factorial(primeCount);
        q = factorial(nonPrimeCount);

        return (int) ((p * q) % (1000000007));
    }

    private long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result = (result * i) % (1000000007);
        }
        return result;
    }
}

