import java.util.*;

public class Solution {
    public int kConcatenationMaxSum(int[] arr, int k) {
        long sum = 0;
        for (int num : arr) {
            sum += num;
        }

        if (k == 1) {
            return (int)(Math.max(0, Kadane(arr)) % (1000000007));
        } else if (k > 2) {
            long maxSum = Long.MIN_VALUE;
            for (int i = 1; i <= k - 1; i++) { // Repeat the array k-1 times
                int kadane = Kadane(arr);
                maxSum = Math.max(maxSum, sum * i + kadane);
            }

            long maxSum2 = Long.MIN_VALUE;
            for (int i = 1; i <= k; i++) { // Repeat the array k times
                int kadane = Kadane(arr);
                if(i == 2){
                    maxSum2 = Math.max(maxSum2, sum * i + kadane);
                } else {
                    maxSum2 = Math.max(maxSum2, sum * i + Kadane(arr));
                }
            }

            return (int)(Math.max(maxSum, maxSum2) % (1000000007));
        } else {
            int kadane = Kadane(arr);
            int totalSum = Arrays.stream(arr).sum();
            if (totalSum < 0) {
                return Math.max(0, kadane);
            } else {
                return (int)((kadane + sum * (k - 2)) % (1000000007));
            }
        }
    }

    private int Kadane(int[] arr) {
        int maxSoFar = Integer.MIN_VALUE;
        int maxEndingHere = 0;

        for (int num : arr) {
            maxEndingHere += num;
            if (maxEndingHere < 0) {
                maxEndingHere = 0;
            }
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }

        return maxSoFar;
    }
}

