public class Solution {
    public TreeNode lcaDeepestLeaves(TreeNode root) {
        int maxDepth = 0;
        TreeNode deepestLCA = null;

        dfs(root, 0, maxDepth, deepestLCA);

        return deepestLCA;
    }

    private void dfs(TreeNode node, int depth, int maxDepth, TreeNode deepestLCA) {
        if (node == null) {
            return;
        }

        if (isLeaf(node)) {
            if (depth > maxDepth) {
                maxDepth = depth;
                deepestLCA = node;
            }
        } else {
            dfs(node.left, depth + 1, maxDepth, deepestLCA);
            dfs(node.right, depth + 1, maxDepth, deepestLCA);
        }
    }

    private boolean isLeaf(TreeNode node) {
        return (node.left == null && node.right == null);
    }
}

