public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        int n = 1, level = 0;
        while (n <= label) {
            n *= 2;
            level++;
        }
        n /= 2;
        List<Integer> res = new LinkedList<>();
        while (level >= 0) {
            if (((label - 1) & 1) == 0) { // Check if label is even
                res.add(0, (n >> 1) + 1); // Add parent node's label to the beginning of the list
            } else {
                res.add((n >> 1) - 1); // Add parent node's label to the end of the list
            }
            level--;
            n >>= 1;
        }
        return res;
    }
}

