                        int y = j - k + 1;
                        boolean isValid = true;
                        for (int p = x; p <= i; p++) {
                            if (dp[p][y] < k || dp[x][p] < k) {
                                isValid = false;
                                break;
                            }
                        }
                        if (isValid && k > max) { // Check if this is the largest square subgrid found so far
                            max = k;
                        }
                    }
                } else {
                    dp[i][j] = 0;
                }
            }
        }

        // Return the maximum size of the square subgrid with all 1s on its border
        return max * max;
    }
}

