import java.util.*;

public class Solution {
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : redEdges) {
            graph.get(edge[0]).add(edge[1]);
        }

        for (int[] edge : blueEdges) {
            graph.get(edge[0]).add(edge[1]);
        }

        int[][] directions = {{-1, 0}, {0, -1}};
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][2];
        int[][] distance = new int[n][2];

        for (int i = 0; i < n; i++) {
            Arrays.fill(distance[i], Integer.MAX_VALUE);
        }

        queue.offer(new int[] {0, 1});
        distance[0][1] = 0;
        visited[0][1] = true;

        int color = 1; // Start with blue edges

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int[] dir : directions) {
                int nextNode = current[0] + dir[0];
                if (nextNode < 0 || nextNode >= n) continue;

                if ((color == 1 && distance[nextNode][0] != Integer.MAX_VALUE) ||
                    (color == 0 && distance[nextNode][1] != Integer.MAX_VALUE)) {
                    int newDistance = current[1] + 1;
                    if (newDistance < Math.min(distance[nextNode][current[1]^1], distance[nextNode][(current[1]^1)^1])) {
                        distance[nextNode][current[1]^1] = newDistance;
                        queue.offer(new int[] {nextNode, current[1]^1});
                    }
                }

                color ^= 1; // Switch colors
            }
        }

        for (int i = 0; i < n; i++) {
            if (distance[i][0] == Integer.MAX_VALUE && distance[i][1] == Integer.MAX_VALUE) {
                distance[i][0] = -1;
            } else {
                distance[i][0] = Math.min(distance[i][0], distance[i][1]);
            }
        }

        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = distance[i][0];
        }

        return answer;
    }
}

