import java.util.Arrays;

public class Solution {
    private static final String[] BOARD = {"abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"};
    private static final int[][] POSITIONS = new int[BOARD.length][BOARD[0].length()];

    static {
        for (int i = 0; i < BOARD.length; i++) {
            for (int j = 0; j < BOARD[i].length(); j++) {
                POSITIONS[i][j] = BOARD[i].charAt(j) - 'a';
            }
        }
    }

    public String alphabetBoardPath(String target) {
        int[] pos = new int[]{0, 0};
        StringBuilder sb = new StringBuilder();

        for (char c : target.toCharArray()) {
            int row = Arrays.binarySearch(BOARD, String.valueOf(c));

            // Handle the case where the character c is not present in the BOARD array
            if (row < 0) {
                if (!c.equals("z")) { 
                    throw new RuntimeException("The character '" + c + "' is not present in the BOARD array");
                }
            } else {
                // Move to the correct row
                if (pos[0] != row) {
                    int diff = Math.abs(pos[0] - row);
                    if (pos[0] < row) {
                        // Move down
                        for (int i = 0; i < diff; i++) {
                            sb.append("D");
                        }
                    } else {
                        // Move up
                        for (int i = 0; i < diff; i++) {
                            sb.append("U");
                        }
                    }
                    pos[0] = row;
                }
            }

            int col = POSITIONS[row][pos[1]];
            if (pos[1] != col) {
                // Move to the correct column
                int diff = Math.abs(pos[1] - col);
                if (pos[1] < col) {
                    // Move right
                    for (int i = 0; i < diff; i++) {
                        sb.append("R");
                    }
                } else {
                    // Move left
                    for (int i = 0; i < diff; i++) {
                        sb.append("L");
                    }
                }
            }

            pos[1] = col;
            sb.append("!").append(c);
        }

        return sb.toString();
    }
}

