public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        int index = 0;
        int step = 1;

        while (candies > 0) {
            for (int i = 0; i < numPeople && candies > 0; i++) {
                if (index == numPeople - 1) {
                    result[index] += Math.min(candies, step + 1);
                } else {
                    result[index] += Math.min(candies, step);
                }
                index = (index + 1) % numPeople;
                candies -= Math.min(candies, step);
            }
            if (index == 0) { // Corrected condition to reset the index
                index = 0; // Reset the index to 0
                step++; // Increment the step by 1 for the next cycle
            }
        }

        return result;
    }
}

