import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        // Calculate frequency of each word and store it in an array along with the word itself
        WordFreq[] wordFrequencies = new WordFreq[words.length];
        for (int i = 0; i < words.length; i++) {
            char minChar = findMinChar(words[i]);
            int freq = countCharFrequency(words[i], minChar);
            wordFrequencies[i] = new WordFreq(minChar, freq);
        }

        // Sort the array of word frequencies in descending order
        Arrays.sort(wordFrequencies, Comparator.comparingInt(WordFreq::getFreq));

        // For each query, count the number of words with a higher frequency
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            char minChar = findMinChar(queries[i]);
            int freq = countCharFrequency(queries[i], minChar);
            int j;
            for (j = 0; j < wordFrequencies.length; j++) {
                if (wordFrequencies[j].getFreq() > freq) {
                    break;
                }
            }
            result[i] = wordFrequencies.length - j;
        }

        return result;
    }

    private char findMinChar(String s) {
        char minChar = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < minChar) {
                minChar = s.charAt(i);
            }
        }
        return minChar;
    }

    private int countCharFrequency(String s, char c) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == c) {
                count++;
            }
        }
        return count;
    }

    private static class WordFreq {
        private char minChar;
        private int freq;

        public WordFreq(char minChar, int freq) {
            this.minChar = minChar;
            this.freq = freq;
        }

        public char getMinChar() {
            return minChar;
        }

        public int getFreq() {
            return freq;
        }
    }
}

