import java.util.*;

public class Solution {
    private int[] rank;
    private List<List<Integer>> result;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // build graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i, new ArrayList<>());
        }
        for (List<Integer> connection : connections) {
            int u = connection.get(0);
            int v = connection.get(1);
            graph.get(u).add(v);
            graph.get(v).add(u); // undirected graph
        }

        // record rank
        this.rank = new int[n];
        Arrays.fill(this.rank, -1);

        // store result
        this.result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (this.rank[i] == -1) {
                dfs(i, graph);
            }
        }

        return this.result;
    }

    private int dfs(int node, Map<Integer, List<Integer>> graph) {
        // record current node's rank
        int naturalRank = 0;

        for (int nei : graph.get(node)) {
            if (this.rank[nei] == -1) { // unvisited neighbor
                this.rank[node] = -1; // mark as visited

                // step1: run dfs to get the rank of this nei, if it is visited before, it will reach base case immediately
                int neiTime = dfs(nei, graph);

                // if neiTime is strictly larger than current node's rank, there is no cycle,
                // connections between node and nei is a critically connection.
                if (neiTime > naturalRank) {
                    this.result.add(Arrays.asList(node, nei));
                }

                // keep updating current node's rank with nei's smaller ranks
                naturalRank = Math.max(naturalRank, neiTime);
            } else if (this.rank[nei] < naturalRank && nei != node) { // skip the parent, since this is undirected graph
                this.result.add(Arrays.asList(node, nei));
            }
        }

        return naturalRank + 1;
    }
}

