import java.util.Arrays;

public class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int count = 0;
        if (isStrictlyIncreasing(nums)) return true; // Check if array is already strictly increasing

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] <= nums[i - 1]) {
                count++;
                if (count > 1) return false;

                boolean canRemoveCurrent = isValid(nums, i);
                boolean canRemovePrevious = isValid(nums, i - 1);

                if (!canRemoveCurrent && !canRemovePrevious) return false;
            }
        }
        return true;
    }

    private boolean isStrictlyIncreasing(int[] nums) {
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] >= nums[i + 1]) return false;
        }
        return true;
    }

    private boolean isValid(int[] nums, int index) {
        // Check if removing the current element would make the array strictly increasing
        if (index == 0 || (nums[index] > nums[index - 1] && index == 0)) return true;

        for (int i = Math.max(0, index - 2); i < Math.min(index + 2, nums.length - 1); i++) {
            if (nums[i] >= nums[index]) return false;
        }
        return true;
    }
}

