public class Solution {
    public int[] rearrangeArray(int[] nums) {
        Arrays.sort(nums);

        int[] result = new int[nums.length];
        int left = 0;
        int right = nums.length - 1;

        // Greedy algorithm to place each element at an index where it is not equal to the average of its neighbors
        for (int i = 0; i < nums.length; i++) {
            if (i % 2 == 0) {
                result[i] = nums[left++];

                // If placing the next number would make the current one equal to the average, place it at an odd index instead
                if (left <= right && (nums[left] + nums[right]) / 2 == nums[i]) {
                    i--;
                    left++;
                }
            } else {
                result[i] = nums[right--];

                // If placing the next number would make the current one equal to the average, place it at an even index instead
                if (left <= right && (nums[left] + nums[right]) / 2 == nums[i]) {
                    i--;
                    right--;
                }
            }
        }

        return result;
    }
}

