        int eliminated = 0;
        while (time < times[times.length - 1]) {
            if (eliminated < dist.length && time >= times[eliminated]) { // Check if we can eliminate more monsters
                eliminated++;
                time += 2; // Increment the time by 2 after eliminating a monster, to account for charging the weapon
            } else {
                time++; // Only increment the time by 1 when you didn't eliminate a monster
            }
        }

        return eliminated;
    }
}

