// #Medium #Array #Greedy #Matrix #2022_05_21_Time_4_ms_(100.00%)_Space_79.8_MB_(36.28%)
public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        int n = matrix.length;

        // Initialize minimum and maximum values
        long minVal = Long.MAX_VALUE, maxVal = 0;

        // Initialize sum of all elements in the matrix
        long totalSum = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = Math.abs(matrix[i][j]);

                // Update minimum and maximum values
                minVal = Math.min(minVal, val);
                maxVal = Math.max(maxVal, val);

                // Add the absolute value to total sum
                totalSum += val;
            }
        }

        // Count the number of negative elements
        int negCount = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] < 0) {
                    negCount++;
                }
            }
        }

        // Adjust the result by subtracting twice the minimum value
        return maxVal == 0 ? totalSum : totalSum + (maxVal - minVal * 2);
    }
}

