import java.util.Stack;

public class Solution {
    public int minSwaps(String s) {
        Stack<Character> stack = new Stack<>();

        for (char c : s.toCharArray()) {
            if (!stack.isEmpty() && stack.peek() == '[' && c == ']') {
                stack.pop();
            } else {
                stack.push(c);
            }
        }

        return Math.abs(stack.size() - s.length() / 2);
    }
}

