public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = (m + n - 1) / 2;

        // Calculate the number of rotations needed for each layer
        k %= layers * 4;

        // Perform the rotation
        for (int i = 0; i < Math.min(k, layers); i++) {
            rotateLayer(grid, m, n);
        }

        return grid;
    }

    private void rotateLayer(int[][] grid, int m, int n) {
        int layerSize = Math.min(m, n) - 2;
        for (int layer = 0; layer < layerSize; layer++) {
            // Save the top edge
            int temp = grid[layer][n - 1];

            // Move left edge to top
            for (int i = n - 2; i > layer; i--) {
                grid[layer][i + 1] = grid[layer][i];
            }

            // Move bottom edge to left
            for (int i = m - 2; i > layer; i--) {
                grid[i][layer] = grid[i - 1][layer];
            }

            // Move right edge to bottom
            for (int i = n - 2; i >= layer + 1; i--) {
                grid[i - 1][n - 1] = grid[i][n - 1];
            }

            // Put the saved top edge at left position and then move it one more step to its final position
            grid[layer][layer + 1] = temp;
        }
    }
}

