import java.util.Deque;
import java.util.LinkedList;

public class Solution {
    private int[] obstacles; // declare obstacles as a field
    private int[] ans; // declare ans as a field

    public Solution(int[] obstacles) { // initialize obstacles in constructor
        this.obstacles = obstacles;
        this.ans = new int[obstacles.length];
    }

    public int[] longestObstacleCourseAtEachPosition() {
        Deque<int[]> stack = new LinkedList<>();

        for (int i = 0; i < obstacles.length; i++) {
            if (stack.isEmpty() || stack.peek()[0] <= obstacles[i]) {
                stack.offerLast(new int[]{obstacles[i], 1});
            } else {
                int[] temp = stack.pollLast();
                while (!stack.isEmpty() && stack.peek()[0] > obstacles[i]) {
                    temp[1]++;
                    stack.offerLast(temp);
                    temp = stack.pollLast();
                }
                stack.offerLast(new int[]{obstacles[i], temp[1] + 1});
            }

            if (i == 0) {
                continue;
            }

            ans[i] = stack.peek()[1];
        }

        return ans;
    }
}

