import java.util.*;

public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        Map<String, Integer> studentMap = new HashMap<>();

        // Create a map to store the compatibility scores of each student
        for (int i = 0; i < students.length; i++) {
            String key = Arrays.toString(students[i]);
            studentMap.put(key, i);
        }

        int maxScore = 0;

        // Iterate over each mentor's answers
        for (int[] mentor : mentors) {
            int score = 0;

            // Find the best matching student for this mentor
            String key = Arrays.toString(mentor);
            if (studentMap.containsKey(key)) {
                int studentIndex = studentMap.get(key);

                // Calculate the compatibility score of this pair
                for (int i = 0; i < students[studentIndex].length; i++) {
                    score += (students[studentIndex][i] == mentor[i]) ? 1 : 0;
                }
            } else {
                // If no student matches exactly, try to find the best match among all students
                int maxMatchingAnswers = 0;
                String bestKey = null;

                for (Map.Entry<String, Integer> entry : studentMap.entrySet()) {
                    String studentKey = entry.getKey();
                    int matchingAnswers = 0;

                    // Calculate the number of matching answers between this student and the mentor
                    for (int i = 0; i < students[entry.getValue()].length; i++) {
                        if (students[entry.getValue()][i] == mentor[i]) {
                            matchingAnswers++;
                        }
                    }

                    // Update the best match if we find a better one
                    if (matchingAnswers > maxMatchingAnswers) {
                        maxMatchingAnswers = matchingAnswers;
                        bestKey = studentKey;
                    } else if (matchingAnswers == maxMatchingAnswers && entry.getValue() < studentMap.get(bestKey)) {
                        // If multiple students have the same maximum number of matching answers, choose the first one
                        bestKey = entry.getKey();
                    }
                }

                // If we found a good enough match, use it
                if (bestKey != null) {
                    int studentIndex = studentMap.get(bestKey);

                    // Calculate the compatibility score of this pair
                    for (int i = 0; i < students[studentIndex].length; i++) {
                        score += (students[studentIndex][i] == mentor[i]) ? 1 : 0;
                    }
                }
            }

            // Update the maximum score if necessary
            maxScore = Math.max(maxScore, score);
        }

        return maxScore;
    }
}

