import java.util.Arrays;

public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;

        // Perform binary search on each row to find a peak element
        for (int i = 0; i < m; i++) {
            int left = 0, right = n - 1;
            while (left <= right) {
                int mid = left + (right - left) / 2;

                // Check if the middle column has a peak element
                boolean found = false;
                for (int j = 0; j < m; j++) {
                    if ((mid == n - 1 || mat[j][mid] > mat[j][(mid + 1) % n]) && 
                        (mid == 0 || mat[j][mid] > mat[j][(mid - 1) % n])) {
                        found = true;
                        break;
                    }
                }

                if (!found) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }

            // If a peak element is found, return its indices
            int j = left;
            boolean isPeak = false;
            for (int k = 0; k < m; k++) {
                if ((j == n - 1 || mat[k][j] > mat[k][(j + 1) % n]) && 
                    (j == 0 || mat[k][j] > mat[k][(j - 1) % n])) {
                    isPeak = true;
                    break;
                }
            }

            if (isPeak) {
                return new int[] {i, j};
            }
        }

        // If no peak element is found, return an empty array
        return new int[] {};
    }
}
